#[cfg(any(feature = "pipnn_cuda", test))]
fn compact_topk_batch_from_leaf_gram(
    leaf_id: u64,
    point_ids: &[u32],
    norms: &[f32],
    gram_row_major: &[f32],
    rows: usize,
    requested_k: usize,
) -> AnnResult<CompactTopKBatch> {
    if point_ids.len() != rows
        || norms.len() != rows
        || gram_row_major.len() != rows.saturating_mul(rows)
    {
        return Err(AnnError::log_index_error(format!(
            "Invalid cuBLAS leaf gram shape: rows={rows} point_ids={} norms={} gram={}",
            point_ids.len(),
            norms.len(),
            gram_row_major.len()
        )));
    }

    let k = requested_k.min(rows.saturating_sub(1));
    let mut batch = CompactTopKBatch {
        leaf_id,
        point_ids: point_ids.to_vec(),
        rows,
        k,
        topk_ids: vec![u32::MAX; rows.saturating_mul(k)],
        topk_dists: vec![f32::INFINITY; rows.saturating_mul(k)],
        estimated_dtoh_bytes: estimate_compact_topk_dtoh_bytes(rows, k),
        estimated_lune_witness_dtoh_bytes: 0,
        ..CompactTopKBatch::default()
    };
    if rows == 0 || k == 0 {
        return Ok(batch);
    }

    for row in 0..rows {
        let mut candidates = Vec::with_capacity(rows.saturating_sub(1));
        for col in 0..rows {
            if row == col {
                continue;
            }
            let dot = gram_row_major[row * rows + col];
            let mut dist = norms[row] + norms[col] - 2.0 * dot;
            if dist <= 0.0 {
                dist = 0.0;
            }
            if !dist.is_finite() {
                return Err(AnnError::log_index_error(format!(
                    "Invalid cuBLAS leaf gram distance: leaf={leaf_id} row={row} col={col} dist={dist}"
                )));
            }
            candidates.push((point_ids[col], dist));
        }
        candidates.sort_unstable_by(|left, right| {
            super::stable_distance_order(left.1, left.0, right.1, right.0)
        });
        let out = row * k;
        for (rank, &(target, dist)) in candidates.iter().take(k).enumerate() {
            batch.topk_ids[out + rank] = target;
            batch.topk_dists[out + rank] = dist;
        }
    }
    Ok(batch)
}

#[cfg(feature = "pipnn_cuda")]
fn validate_library_compact_topk_batch(batch: &CompactTopKBatch) -> AnnResult<()> {
    use std::collections::HashSet;

    if batch.point_ids.len() != batch.rows
        || batch.topk_ids.len() != batch.rows.saturating_mul(batch.k)
        || batch.topk_dists.len() != batch.rows.saturating_mul(batch.k)
    {
        return Err(AnnError::log_index_error(format!(
            "Invalid library compact top-k batch shape: leaf={} rows={} k={} point_ids={} topk_ids={} topk_dists={}",
            batch.leaf_id,
            batch.rows,
            batch.k,
            batch.point_ids.len(),
            batch.topk_ids.len(),
            batch.topk_dists.len()
        )));
    }

    let leaf_points: HashSet<u32> = batch.point_ids.iter().copied().collect();
    for (row, &point_id) in batch.point_ids.iter().enumerate() {
        let offset = row.saturating_mul(batch.k);
        for rank in 0..batch.k {
            let neighbor = batch.topk_ids[offset + rank];
            let dist = batch.topk_dists[offset + rank];
            if neighbor == u32::MAX {
                return Err(AnnError::log_index_error(format!(
                    "Library compact top-k batch leaf={} row={row} rank={rank} did not emit a neighbor",
                    batch.leaf_id
                )));
            }
            if !dist.is_finite() {
                return Err(AnnError::log_index_error(format!(
                    "Library compact top-k batch leaf={} row={row} rank={rank} has non-finite distance {dist}",
                    batch.leaf_id
                )));
            }
            if neighbor == point_id {
                return Err(AnnError::log_index_error(format!(
                    "Library compact top-k batch leaf={} row={row} rank={rank} references itself as point {neighbor}",
                    batch.leaf_id
                )));
            }
            if !leaf_points.contains(&neighbor) {
                return Err(AnnError::log_index_error(format!(
                    "Library compact top-k batch leaf={} row={row} rank={rank} references point {neighbor} outside its leaf",
                    batch.leaf_id
                )));
            }
        }
    }

    Ok(())
}
