const GPU_PERSISTENT_LARGE_TILE_MAX_TILES: u64 = u32::MAX as u64;

#[cfg(any(feature = "pipnn_cuda", test))]
fn gpu_persistent_large_tile_count(row_count: u64) -> Result<u32, String> {
    let required_tiles = row_count / GPU_PERSISTENT_LARGE_TILE_ROWS
        + u64::from(row_count % GPU_PERSISTENT_LARGE_TILE_ROWS != 0);
    if required_tiles > GPU_PERSISTENT_LARGE_TILE_MAX_TILES {
        return Err(format!(
            "CUDA persistent large-task tile capacity exceeded: row_count={row_count} tile_rows={GPU_PERSISTENT_LARGE_TILE_ROWS} required_tiles={required_tiles} max_tiles={GPU_PERSISTENT_LARGE_TILE_MAX_TILES}"
        ));
    }
    Ok(required_tiles as u32)
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn gpu_persistent_large_ticket_batch_size(
    requested: PiPNNGpuSubtreePersistentLargeTicketBatch,
    dense_sq8: bool,
    padded_dim: usize,
    assignment_kernel_code: u32,
) -> u32 {
    requested.explicit_batch().unwrap_or_else(|| {
        if dense_sq8
            && padded_dim != 0
            && padded_dim % 16 == 0
            && assignment_kernel_code != GPU_PERSISTENT_SQ8_ASSIGNMENT_KERNEL_WARP_DP4A
        {
            8
        } else {
            1
        }
    })
}

#[cfg(any(feature = "pipnn_cuda", test))]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct GpuPersistentSchedulerConfig {
    actual_mode: PiPNNGpuSubtreePersistentSchedulerMode,
    idle_backoff_ns: u32,
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn resolve_gpu_persistent_scheduler_config(
    requested: PiPNNGpuSubtreePersistentSchedulerMode,
    configured_backoff_ns: u32,
    compute_capability_major: usize,
) -> AnnResult<GpuPersistentSchedulerConfig> {
    let actual_mode = requested.resolved();
    let idle_backoff_ns = if actual_mode == PiPNNGpuSubtreePersistentSchedulerMode::AdaptiveIdle {
        if !matches!(configured_backoff_ns, 0 | 350 | 700 | 1400) {
            return Err(AnnError::log_index_error(format!(
                "Persistent adaptive-idle backoff must be one of 0, 350, 700, 1400 ns, got {configured_backoff_ns}"
            )));
        }
        if compute_capability_major < 7 {
            return Err(AnnError::log_index_error(format!(
                "Persistent adaptive-idle requires SM70+, got compute capability {compute_capability_major}.x"
            )));
        }
        configured_backoff_ns
    } else {
        0
    };
    Ok(GpuPersistentSchedulerConfig {
        actual_mode,
        idle_backoff_ns,
    })
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn gpu_persistent_idle_delay_ns(cap_ns: u32, streak: u32) -> u32 {
    if cap_ns == 0 || streak == 0 {
        0
    } else if streak >= 4 {
        cap_ns
    } else {
        (cap_ns >> (4 - streak)).max(1).min(cap_ns)
    }
}

