#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) const GPU_PERSISTENT_SQ8_LEAF_MODE_D96_K2: u32 = 2;
#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) const GPU_PERSISTENT_SQ8_ASSIGNMENT_KERNEL_AUTO: u32 = 0;
#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) const GPU_PERSISTENT_SQ8_ASSIGNMENT_KERNEL_WARP_DP4A: u32 = 1;
#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) const GPU_PERSISTENT_SQ8_ASSIGNMENT_KERNEL_WMMA: u32 = 2;
#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) const GPU_PERSISTENT_SQ8_LEAF_EXECUTOR_AUTO: u32 = 0;
#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) const GPU_PERSISTENT_SQ8_LEAF_EXECUTOR_WARP_DP4A: u32 = 1;
#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) const GPU_PERSISTENT_SQ8_LEAF_EXECUTOR_WMMA: u32 = 2;
#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) const GPU_PERSISTENT_TOPK_WMMA_DIAG_WORDS: usize = 24;
#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_topk_operator_code(
    backend: PiPNNGpuSubtreeLeafTopKBackend,
) -> AnnResult<Option<u32>> {
    match backend {
        PiPNNGpuSubtreeLeafTopKBackend::PersistentCustom => {
            Ok(Some(GPU_PERSISTENT_TOPK_OPERATOR_CUSTOM_FP32))
        }
        PiPNNGpuSubtreeLeafTopKBackend::PersistentTiledGemmFp32 => {
            Ok(Some(GPU_PERSISTENT_TOPK_OPERATOR_TILED_GEMM_FP32))
        }
        PiPNNGpuSubtreeLeafTopKBackend::CuvsBruteforce => {
            Ok(Some(GPU_PERSISTENT_TOPK_OPERATOR_CUVS_BRUTEFORCE_FP32))
        }
        PiPNNGpuSubtreeLeafTopKBackend::PersistentBlockselectFp32 => {
            Err(AnnError::log_index_error(
                "GPU subtree leaf top-k backend 'persistent-blockselect-fp32' is parsed but not implemented yet; use persistent-custom or persistent-tiled-gemm-fp32".to_string(),
            ))
        }
        PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32 => {
            Ok(Some(GPU_PERSISTENT_TOPK_OPERATOR_WMMA_TF32))
        }
        PiPNNGpuSubtreeLeafTopKBackend::CublasGemm => Ok(None),
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_assignment_operator_code(
    backend: PiPNNGpuSubtreeAssignmentBackend,
) -> AnnResult<u32> {
    match backend {
        PiPNNGpuSubtreeAssignmentBackend::Current
        | PiPNNGpuSubtreeAssignmentBackend::PersistentCustomFp32 => {
            Ok(GPU_PERSISTENT_ASSIGNMENT_OPERATOR_CURRENT)
        }
        PiPNNGpuSubtreeAssignmentBackend::PersistentTiledGemmFp32 => {
            Ok(GPU_PERSISTENT_ASSIGNMENT_OPERATOR_TILED_GEMM_FP32)
        }
        PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32 => {
            Ok(GPU_PERSISTENT_ASSIGNMENT_OPERATOR_WMMA_TF32)
        }
        PiPNNGpuSubtreeAssignmentBackend::PersistentCuvsBruteforceFp32 => {
            Ok(GPU_PERSISTENT_ASSIGNMENT_OPERATOR_CUVS_BRUTEFORCE_FP32)
        }
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_assignment_dco_mode_code(mode: PiPNNGpuSubtreeDcoMode) -> AnnResult<u32> {
    match mode {
        PiPNNGpuSubtreeDcoMode::None => Ok(GPU_PERSISTENT_ASSIGNMENT_DCO_NONE),
        PiPNNGpuSubtreeDcoMode::PrefixProjection => {
            Ok(GPU_PERSISTENT_ASSIGNMENT_DCO_PREFIX_PROJECTION)
        }
        PiPNNGpuSubtreeDcoMode::Quantized => Ok(GPU_PERSISTENT_ASSIGNMENT_DCO_QUANTIZED),
        other => Err(AnnError::log_index_error(format!(
            "GPU subtree assignment DCO mode '{other}' is parsed but not implemented in the persistent kernel yet; use none, prefix-projection, or quantized"
        ))),
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_assignment_dco_rerank_code(mode: PiPNNGpuSubtreeDcoRerankMode) -> u32 {
    match mode {
        PiPNNGpuSubtreeDcoRerankMode::Exact => GPU_PERSISTENT_ASSIGNMENT_DCO_RERANK_EXACT,
        PiPNNGpuSubtreeDcoRerankMode::ExactStamp => GPU_PERSISTENT_ASSIGNMENT_DCO_RERANK_EXACT,
        PiPNNGpuSubtreeDcoRerankMode::None => GPU_PERSISTENT_ASSIGNMENT_DCO_RERANK_NONE,
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_leaf_dco_mode_code(mode: PiPNNGpuSubtreeDcoMode) -> AnnResult<u32> {
    match mode {
        PiPNNGpuSubtreeDcoMode::None => Ok(GPU_PERSISTENT_LEAF_DCO_NONE),
        PiPNNGpuSubtreeDcoMode::PrefixProjection => Ok(GPU_PERSISTENT_LEAF_DCO_PREFIX_PROJECTION),
        PiPNNGpuSubtreeDcoMode::DdcRes => Ok(GPU_PERSISTENT_LEAF_DCO_DDC_RES),
        PiPNNGpuSubtreeDcoMode::WmmaFilter => Ok(GPU_PERSISTENT_LEAF_DCO_WMMA_FILTER),
        PiPNNGpuSubtreeDcoMode::RabitqWmmaFilter => Ok(GPU_PERSISTENT_LEAF_DCO_RABITQ_WMMA_FILTER),
        PiPNNGpuSubtreeDcoMode::RabitqSplitFilter => {
            Ok(GPU_PERSISTENT_LEAF_DCO_RABITQ_SPLIT_FILTER)
        }
        other => Err(AnnError::log_index_error(format!(
            "GPU subtree leaf top-k DCO mode '{other}' is parsed but not implemented in the persistent kernel yet; use none, prefix-projection, ddc-res, wmma-filter, rabitq-wmma-filter, or rabitq-split-filter"
        ))),
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_leaf_dco_rerank_code(mode: PiPNNGpuSubtreeDcoRerankMode) -> u32 {
    match mode {
        PiPNNGpuSubtreeDcoRerankMode::Exact => GPU_PERSISTENT_LEAF_DCO_RERANK_EXACT,
        PiPNNGpuSubtreeDcoRerankMode::None => GPU_PERSISTENT_LEAF_DCO_RERANK_NONE,
        PiPNNGpuSubtreeDcoRerankMode::ExactStamp => GPU_PERSISTENT_LEAF_DCO_RERANK_EXACT_STAMP,
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_sq8_leaf_mode_code(
    requested: PiPNNGpuSubtreeSq8LeafMode,
    dense_sq8: bool,
    dim: usize,
    padded_dim: usize,
    k: usize,
    no_rerank: bool,
    audit: bool,
) -> AnnResult<u32> {
    let explicit_row_owned_supported =
        dense_sq8 && padded_dim != 0 && padded_dim % 16 == 0 && k <= 4 && no_rerank && !audit;
    let auto_row_owned_supported = explicit_row_owned_supported && padded_dim <= 256;
    let d96_k2_supported = explicit_row_owned_supported && dim == 96 && padded_dim == 96 && k == 2;
    match requested {
        PiPNNGpuSubtreeSq8LeafMode::Staged => Ok(GPU_PERSISTENT_SQ8_LEAF_MODE_STAGED),
        PiPNNGpuSubtreeSq8LeafMode::Auto if auto_row_owned_supported => {
            Ok(GPU_PERSISTENT_SQ8_LEAF_MODE_ROW_OWNED)
        }
        PiPNNGpuSubtreeSq8LeafMode::Auto => Ok(GPU_PERSISTENT_SQ8_LEAF_MODE_STAGED),
        PiPNNGpuSubtreeSq8LeafMode::RowOwned if explicit_row_owned_supported => {
            Ok(GPU_PERSISTENT_SQ8_LEAF_MODE_ROW_OWNED)
        }
        PiPNNGpuSubtreeSq8LeafMode::D96K2 if d96_k2_supported => {
            Ok(GPU_PERSISTENT_SQ8_LEAF_MODE_D96_K2)
        }
        other => Err(AnnError::log_index_error(format!(
            "GPU subtree SQ8 leaf mode '{other}' requires dense SQ8, non-zero 16-aligned padded_dim, k <= 4, no rerank, and no audit; auto row-owned additionally requires padded_dim <= 256, while d96-k2 requires dim=padded_dim=96 and k=2 (dense_sq8={dense_sq8}, dim={dim}, padded_dim={padded_dim}, k={k}, no_rerank={no_rerank}, audit={audit})"
        ))),
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_sq8_assignment_kernel_code(
    requested: PiPNNGpuSubtreeSq8AssignmentKernel,
    dense_sq8: bool,
    padded_dim: usize,
    sm72_plus: bool,
    no_dco: bool,
) -> AnnResult<u32> {
    let explicit_wmma_supported =
        dense_sq8 && padded_dim != 0 && padded_dim % 16 == 0 && sm72_plus && no_dco;
    match requested {
        PiPNNGpuSubtreeSq8AssignmentKernel::WarpDp4a => {
            Ok(GPU_PERSISTENT_SQ8_ASSIGNMENT_KERNEL_WARP_DP4A)
        }
        PiPNNGpuSubtreeSq8AssignmentKernel::Auto if explicit_wmma_supported => {
            Ok(GPU_PERSISTENT_SQ8_ASSIGNMENT_KERNEL_AUTO)
        }
        PiPNNGpuSubtreeSq8AssignmentKernel::Auto => {
            Ok(GPU_PERSISTENT_SQ8_ASSIGNMENT_KERNEL_WARP_DP4A)
        }
        PiPNNGpuSubtreeSq8AssignmentKernel::Wmma if explicit_wmma_supported => {
            Ok(GPU_PERSISTENT_SQ8_ASSIGNMENT_KERNEL_WMMA)
        }
        PiPNNGpuSubtreeSq8AssignmentKernel::Wmma => Err(AnnError::log_index_error(format!(
            "GPU subtree SQ8 assignment kernel 'wmma' requires dense SQ8, non-zero 16-aligned padded_dim, SM72+, and assignment DCO disabled (dense_sq8={dense_sq8}, padded_dim={padded_dim}, sm72_plus={sm72_plus}, no_dco={no_dco})"
        ))),
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_sq8_leaf_executor_code(
    requested: PiPNNGpuSubtreeSq8LeafExecutor,
    dense_sq8: bool,
    padded_dim: usize,
    sm72_plus: bool,
    exact_mode: bool,
) -> AnnResult<u32> {
    if requested == PiPNNGpuSubtreeSq8LeafExecutor::Auto {
        return Ok(GPU_PERSISTENT_SQ8_LEAF_EXECUTOR_AUTO);
    }
    let forced_supported =
        dense_sq8 && padded_dim != 0 && padded_dim % 16 == 0 && sm72_plus && exact_mode;
    if !forced_supported {
        return Err(AnnError::log_index_error(format!(
            "GPU subtree SQ8 leaf executor '{requested}' requires dense SQ8, non-zero 16-aligned padded_dim, SM72+, no rerank, and no audit (dense_sq8={dense_sq8}, padded_dim={padded_dim}, sm72_plus={sm72_plus}, exact_mode={exact_mode})"
        )));
    }
    Ok(match requested {
        PiPNNGpuSubtreeSq8LeafExecutor::Auto => GPU_PERSISTENT_SQ8_LEAF_EXECUTOR_AUTO,
        PiPNNGpuSubtreeSq8LeafExecutor::WarpDp4a => GPU_PERSISTENT_SQ8_LEAF_EXECUTOR_WARP_DP4A,
        PiPNNGpuSubtreeSq8LeafExecutor::Wmma => GPU_PERSISTENT_SQ8_LEAF_EXECUTOR_WMMA,
    })
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn resolve_sq8_d0_assignment_kernel(
    requested: PiPNNGpuSubtreeSq8D0AssignmentKernel,
    padded_dim: usize,
    compute_capability_major: usize,
    compute_capability_minor: usize,
) -> AnnResult<PiPNNGpuSubtreeSq8D0AssignmentKernel> {
    let sm72_plus = compute_capability_major > 7
        || (compute_capability_major == 7 && compute_capability_minor >= 2);
    let wmma_eligible = sm72_plus && padded_dim != 0 && padded_dim % 16 == 0;

    match requested {
        PiPNNGpuSubtreeSq8D0AssignmentKernel::Auto if wmma_eligible => {
            Ok(PiPNNGpuSubtreeSq8D0AssignmentKernel::WmmaBatch)
        }
        PiPNNGpuSubtreeSq8D0AssignmentKernel::Auto => {
            Ok(PiPNNGpuSubtreeSq8D0AssignmentKernel::TiledScalar)
        }
        PiPNNGpuSubtreeSq8D0AssignmentKernel::TiledScalar => {
            Ok(PiPNNGpuSubtreeSq8D0AssignmentKernel::TiledScalar)
        }
        PiPNNGpuSubtreeSq8D0AssignmentKernel::WmmaBatch if wmma_eligible => {
            Ok(PiPNNGpuSubtreeSq8D0AssignmentKernel::WmmaBatch)
        }
        PiPNNGpuSubtreeSq8D0AssignmentKernel::WmmaBatch => Err(AnnError::log_index_error(format!(
            "SQ8 D0 WMMA batch requires SM72+ and a non-zero padded dimension divisible by 16, got compute capability {compute_capability_major}.{compute_capability_minor} padded_dim={padded_dim}"
        ))),
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_turboquant_leaf_rerank_mode_code(params: &PiPNNParams) -> u32 {
    if params.gpu_subtree_turboquant_cascade_survivor_cap > 0 {
        GPU_PERSISTENT_LEAF_DCO_RERANK_EXACT
    } else {
        GPU_PERSISTENT_LEAF_DCO_RERANK_NONE
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_turboquant_leaf_survivors(k: usize, params: &PiPNNParams) -> u32 {
    let requested = if params.gpu_subtree_turboquant_cascade_survivor_cap > 0 {
        params.gpu_subtree_turboquant_cascade_survivor_cap
    } else {
        k
    };
    requested.max(k).min(GPU_PERSISTENT_LEAF_DCO_MAX_SURVIVORS) as u32
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_turboquant_adaptive_survivor_threshold(params: &PiPNNParams) -> u32 {
    if params.gpu_subtree_turboquant_cascade_survivor_cap == 0
        || params.gpu_subtree_turboquant_adaptive_survivor_threshold == 0
        || params.gpu_subtree_turboquant_adaptive_survivor_low_cap == 0
    {
        return 0;
    }
    params
        .gpu_subtree_turboquant_adaptive_survivor_threshold
        .min(u32::MAX as usize) as u32
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_turboquant_adaptive_survivor_low_cap(params: &PiPNNParams) -> u32 {
    if params.gpu_subtree_turboquant_cascade_survivor_cap == 0
        || params.gpu_subtree_turboquant_adaptive_survivor_threshold == 0
        || params.gpu_subtree_turboquant_adaptive_survivor_low_cap == 0
    {
        return 0;
    }
    params
        .gpu_subtree_turboquant_adaptive_survivor_low_cap
        .min(GPU_PERSISTENT_LEAF_DCO_MAX_SURVIVORS) as u32
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn validate_persistent_leaf_dco_config(
    params: &PiPNNParams,
    partition_only: bool,
) -> AnnResult<()> {
    if partition_only || !params.gpu_subtree_leaf_dco_mode.is_enabled() {
        return Ok(());
    }
    let leaf_dco_backend_supported = match params.gpu_subtree_leaf_dco_mode {
        PiPNNGpuSubtreeDcoMode::WmmaFilter | PiPNNGpuSubtreeDcoMode::RabitqSplitFilter => {
            params.gpu_subtree_leaf_topk_backend
                == PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32
        }
        _ => {
            params.gpu_subtree_leaf_topk_backend
                == PiPNNGpuSubtreeLeafTopKBackend::PersistentTiledGemmFp32
        }
    };
    if !leaf_dco_backend_supported {
        return Err(AnnError::log_index_error(
            "GPU subtree leaf top-k DCO prefix-projection/ddc-res require persistent-tiled-gemm-fp32; wmma-filter/rabitq-split-filter require persistent-wmma-tf32"
                .to_string(),
        ));
    }
    if !matches!(
        params.gpu_subtree_leaf_dco_mode,
        PiPNNGpuSubtreeDcoMode::PrefixProjection
            | PiPNNGpuSubtreeDcoMode::DdcRes
            | PiPNNGpuSubtreeDcoMode::WmmaFilter
            | PiPNNGpuSubtreeDcoMode::RabitqSplitFilter
    ) {
        return Err(AnnError::log_index_error(format!(
            "GPU subtree leaf top-k DCO mode '{}' is parsed but not implemented as an explicit leaf filter; use none, prefix-projection, ddc-res, wmma-filter, or rabitq-split-filter. Dense-i8 RabitQ+ WMMA is selected with gpu_subtree_rabitq_plus_mode=build, not leaf_dco_mode=rabitq-wmma-filter",
            params.gpu_subtree_leaf_dco_mode
        )));
    }
    if params.gpu_subtree_leaf_dco_mode == PiPNNGpuSubtreeDcoMode::DdcRes {
        if params.gpu_subtree_leaf_dco_rerank_mode != PiPNNGpuSubtreeDcoRerankMode::Exact {
            return Err(AnnError::log_index_error(
                "GPU subtree leaf top-k ddc-res DCO requires exact rerank mode".to_string(),
            ));
        }
        if params.gpu_subtree_leaf_dco_ddc_res_pca_matrix.is_none() {
            return Err(AnnError::log_index_error(
                "GPU subtree leaf top-k ddc-res DCO requires a ResInfer PCA matrix sidecar"
                    .to_string(),
            ));
        }
        if !params.gpu_subtree_leaf_dco_ddc_res_projected_input {
            return Err(AnnError::log_index_error(
                "GPU subtree leaf top-k ddc-res DCO requires PCA-projected input data".to_string(),
            ));
        }
        if params.gpu_subtree_leaf_dco_proj_dim != 0 {
            return Err(AnnError::log_index_error(
                "GPU subtree leaf top-k ddc-res DCO uses ddc_res_base_dim, not proj_dim"
                    .to_string(),
            ));
        }
        if params.gpu_subtree_leaf_dco_ddc_res_base_dim == 0 {
            return Err(AnnError::log_index_error(
                "GPU subtree leaf top-k ddc-res DCO requires base_dim > 0".to_string(),
            ));
        }
        if !params.gpu_subtree_leaf_dco_ddc_res_sigma_count.is_finite()
            || params.gpu_subtree_leaf_dco_ddc_res_sigma_count <= 0.0
        {
            return Err(AnnError::log_index_error(
                "GPU subtree leaf top-k ddc-res DCO requires finite sigma_count > 0".to_string(),
            ));
        }
    }
    if params.gpu_subtree_leaf_dco_mode == PiPNNGpuSubtreeDcoMode::PrefixProjection
        && params.gpu_subtree_leaf_dco_proj_dim == 0
    {
        return Err(AnnError::log_index_error(
            "GPU subtree leaf top-k prefix-projection DCO requires proj_dim > 0".to_string(),
        ));
    }
    if params.gpu_subtree_leaf_dco_mode == PiPNNGpuSubtreeDcoMode::PrefixProjection
        && params.gpu_subtree_leaf_dco_survivors == 0
    {
        return Err(AnnError::log_index_error(
            "GPU subtree leaf top-k prefix-projection DCO requires survivors > 0".to_string(),
        ));
    }
    if params.gpu_subtree_leaf_dco_mode == PiPNNGpuSubtreeDcoMode::PrefixProjection
        && params.gpu_subtree_leaf_dco_survivors > GPU_PERSISTENT_LEAF_DCO_MAX_SURVIVORS
    {
        return Err(AnnError::log_index_error(format!(
            "GPU subtree leaf top-k prefix-projection DCO currently supports at most {GPU_PERSISTENT_LEAF_DCO_MAX_SURVIVORS} survivors"
        )));
    }
    if params.gpu_subtree_leaf_dco_mode == PiPNNGpuSubtreeDcoMode::WmmaFilter {
        if params.gpu_subtree_leaf_dco_survivors == 0 {
            return Err(AnnError::log_index_error(
                "GPU subtree leaf top-k SQ-int8 WMMA filter requires survivors > 0".to_string(),
            ));
        }
        if params.gpu_subtree_leaf_dco_survivors > GPU_PERSISTENT_LEAF_DCO_MAX_SURVIVORS {
            return Err(AnnError::log_index_error(format!(
                "GPU subtree leaf top-k SQ-int8 WMMA filter currently supports at most {GPU_PERSISTENT_LEAF_DCO_MAX_SURVIVORS} survivors"
            )));
        }
        if params.gpu_subtree_leaf_dco_proj_dim != 0 {
            return Err(AnnError::log_index_error(
                "GPU subtree leaf top-k SQ-int8 WMMA filter does not use proj_dim".to_string(),
            ));
        }
    }
    if params.gpu_subtree_leaf_dco_mode == PiPNNGpuSubtreeDcoMode::RabitqSplitFilter {
        if params.gpu_subtree_leaf_dco_survivors == 0 {
            return Err(AnnError::log_index_error(
                "GPU subtree leaf top-k RabitQ-Library split filter requires survivors > 0"
                    .to_string(),
            ));
        }
        if params.gpu_subtree_leaf_dco_survivors > GPU_PERSISTENT_LEAF_DCO_MAX_SURVIVORS {
            return Err(AnnError::log_index_error(format!(
                "GPU subtree leaf top-k RabitQ-Library split filter currently supports at most {GPU_PERSISTENT_LEAF_DCO_MAX_SURVIVORS} survivors"
            )));
        }
        if params.gpu_subtree_leaf_dco_proj_dim != 0 {
            return Err(AnnError::log_index_error(
                "GPU subtree leaf top-k RabitQ-Library split filter uses fixed 1bit+7bit boosting and does not use proj_dim"
                    .to_string(),
            ));
        }
        if params.gpu_subtree_rabitq_plus_bits != 8 {
            return Err(AnnError::log_index_error(format!(
                "GPU subtree leaf top-k RabitQ-Library split filter currently supports gpu_subtree_rabitq_plus_bits=8 (1bit+7bit), got {}",
                params.gpu_subtree_rabitq_plus_bits
            )));
        }
        if params.gpu_subtree_rabitq_plus_rotator
            != super::params::PiPNNGpuSubtreeRabitqPlusRotator::FhtKac
        {
            return Err(AnnError::log_index_error(format!(
                "GPU subtree leaf top-k RabitQ-Library split filter requires fht_kac rotator, got {}",
                params.gpu_subtree_rabitq_plus_rotator.as_str()
            )));
        }
        if params.gpu_subtree_rabitq_plus_sidecar_prefix.is_none() {
            return Err(AnnError::log_index_error(
                "GPU subtree leaf top-k RabitQ-Library split filter requires a split sidecar prefix"
                    .to_string(),
            ));
        }
    }
    Ok(())
}

#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) fn validate_gpu_subtree_assignment_backend_supported(
    backend: PiPNNGpuSubtreeAssignmentBackend,
) -> AnnResult<()> {
    persistent_assignment_operator_code(backend).map(|_| ())
}

#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) fn estimate_gpu_resident_subtree_device_bytes(
    resident_rows: usize,
    dim: usize,
) -> usize {
    resident_rows
        .saturating_mul(dim.saturating_mul(std::mem::size_of::<f32>()))
        .saturating_add(resident_rows.saturating_mul(std::mem::size_of::<u32>()))
        .saturating_add(resident_rows.saturating_mul(std::mem::size_of::<f32>()))
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn estimate_gpu_resident_subtree_device_bytes_for_params(
    resident_rows: usize,
    dim: usize,
    params: &PiPNNParams,
) -> usize {
    if params.gpu_subtree_sq_wmma_mode != PiPNNGpuSubtreeSqWmmaMode::Build {
        return estimate_gpu_resident_subtree_device_bytes(resident_rows, dim);
    }

    let padded_dim = dim.div_ceil(SQ_INT8_DEFAULT_K_ALIGN) * SQ_INT8_DEFAULT_K_ALIGN;
    let code_row_bytes = if params.gpu_subtree_sq_native_int4 {
        padded_dim.div_ceil(2)
    } else {
        padded_dim
    };
    resident_rows.saturating_mul(
        code_row_bytes
            .saturating_add(std::mem::size_of::<u32>())
            .saturating_add(std::mem::size_of::<f32>())
            .saturating_add(std::mem::size_of::<f32>()),
    )
}

#[cfg(any(feature = "pipnn_cuda", test))]
const PERSISTENT_LEAF_HISTOGRAM_BUCKETS: [usize; 13] =
    [1, 2, 4, 8, 16, 32, 64, 96, 128, 192, 256, 384, usize::MAX];
#[cfg(any(feature = "pipnn_cuda", test))]
const PERSISTENT_TOPK_TILE_HISTOGRAM_BUCKETS: [usize; 13] =
    [1, 2, 3, 4, 5, 6, 8, 12, 16, 24, 32, 64, usize::MAX];

#[cfg(any(feature = "pipnn_cuda", test))]
#[derive(Clone, Debug, serde::Serialize)]
pub(crate) struct PersistentLeafHistogramRecord<'a> {
    pub(crate) record_type: &'a str,
    pub(crate) source: &'a str,
    pub(crate) b_strategy: &'a str,
    pub(crate) resident_rows: usize,
    pub(crate) dim: usize,
    pub(crate) k: usize,
    pub(crate) tile_rows: usize,
    pub(crate) leaf_count: usize,
    pub(crate) leaf_rows: usize,
    pub(crate) topk_pops: usize,
    pub(crate) topk_claims: usize,
    pub(crate) topk_empty_polls: usize,
    pub(crate) leaf_pushes: usize,
    pub(crate) partition_pops: usize,
    pub(crate) partition_claims: usize,
    pub(crate) partition_empty_polls: usize,
    pub(crate) partition_frontier_end: usize,
    pub(crate) partition_level_rounds: usize,
    pub(crate) active_wait_cycles: usize,
    pub(crate) active_work_ticks: usize,
    pub(crate) active_work_trips: usize,
    pub(crate) elastic_role_switches: usize,
    pub(crate) partition_helped_topk_tiles: usize,
    pub(crate) topk_helped_large_tiles: usize,
    pub(crate) queue_overflow_flags: u32,
    pub(crate) kernel_event_ms: f64,
    pub(crate) leaf_size_bucket_bounds: Vec<usize>,
    pub(crate) leaf_size_bucket_counts: Vec<usize>,
    pub(crate) topk_tile_bucket_bounds: Vec<usize>,
    pub(crate) topk_tile_bucket_counts: Vec<usize>,
    pub(crate) partial_tile_count: usize,
    pub(crate) full_tile_count: usize,
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_leaf_size_bucket_index(size: usize) -> usize {
    PERSISTENT_LEAF_HISTOGRAM_BUCKETS
        .iter()
        .position(|&upper| size <= upper)
        .unwrap_or(PERSISTENT_LEAF_HISTOGRAM_BUCKETS.len().saturating_sub(1))
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_topk_tile_bucket_index(tile_count: usize) -> usize {
    PERSISTENT_TOPK_TILE_HISTOGRAM_BUCKETS
        .iter()
        .position(|&upper| tile_count <= upper)
        .unwrap_or(
            PERSISTENT_TOPK_TILE_HISTOGRAM_BUCKETS
                .len()
                .saturating_sub(1),
        )
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_histogram_bucket_bounds() -> Vec<usize> {
    PERSISTENT_LEAF_HISTOGRAM_BUCKETS.to_vec()
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_topk_tile_bucket_bounds() -> Vec<usize> {
    PERSISTENT_TOPK_TILE_HISTOGRAM_BUCKETS.to_vec()
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn build_persistent_leaf_histogram_record<'a>(
    source: &'a str,
    b_strategy: &'a str,
    resident_rows: usize,
    dim: usize,
    k: usize,
    tile_rows: usize,
    leaf_sizes: &[u64],
    profile: &GpuSubtreeTopKProfile,
) -> PersistentLeafHistogramRecord<'a> {
    let effective_tile_rows = tile_rows.max(1);
    let mut leaf_size_bucket_counts = vec![0; PERSISTENT_LEAF_HISTOGRAM_BUCKETS.len()];
    let mut topk_tile_bucket_counts = vec![0; PERSISTENT_LEAF_HISTOGRAM_BUCKETS.len()];
    let mut computed_topk_pops = 0usize;
    let mut partial_tile_count = 0usize;
    let mut full_tile_count = 0usize;
    for &raw_size in leaf_sizes {
        let size = usize::try_from(raw_size).unwrap_or(usize::MAX);
        leaf_size_bucket_counts[persistent_leaf_size_bucket_index(size)] += 1;
        let tile_count = size.div_ceil(effective_tile_rows);
        topk_tile_bucket_counts[persistent_topk_tile_bucket_index(tile_count)] += 1;
        computed_topk_pops = computed_topk_pops.saturating_add(tile_count);
        full_tile_count = full_tile_count.saturating_add(size / effective_tile_rows);
        if size % effective_tile_rows != 0 {
            partial_tile_count += 1;
        }
    }
    let leaf_rows = leaf_sizes.iter().fold(0usize, |sum, &size| {
        sum.saturating_add(usize::try_from(size).unwrap_or(usize::MAX))
    });

    PersistentLeafHistogramRecord {
        record_type: "persistent-leaf-histogram",
        source,
        b_strategy,
        resident_rows,
        dim,
        k,
        tile_rows: effective_tile_rows,
        leaf_count: leaf_sizes.len(),
        leaf_rows,
        topk_pops: computed_topk_pops,
        topk_claims: profile.persistent_topk_claims,
        topk_empty_polls: profile.persistent_topk_empty_polls,
        leaf_pushes: profile.persistent_leaf_pushes,
        partition_pops: profile.persistent_partition_pops,
        partition_claims: profile.persistent_partition_claims,
        partition_empty_polls: profile.persistent_partition_empty_polls,
        partition_frontier_end: profile.persistent_partition_frontier_end,
        partition_level_rounds: profile.persistent_partition_level_rounds,
        active_wait_cycles: profile.persistent_active_wait_cycles,
        active_work_ticks: profile.persistent_active_work_ticks,
        active_work_trips: profile.persistent_active_work_trips,
        elastic_role_switches: profile.persistent_elastic_role_switches,
        partition_helped_topk_tiles: profile.persistent_partition_helped_topk_tiles,
        topk_helped_large_tiles: profile.persistent_topk_helped_large_tiles,
        queue_overflow_flags: profile.persistent_queue_overflow_flags,
        kernel_event_ms: profile.resident_topk_kernel_event_wall.as_secs_f64() * 1000.0,
        leaf_size_bucket_bounds: persistent_histogram_bucket_bounds(),
        leaf_size_bucket_counts,
        topk_tile_bucket_bounds: persistent_topk_tile_bucket_bounds(),
        topk_tile_bucket_counts,
        partial_tile_count,
        full_tile_count,
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn persistent_leaf_histogram_record_json(record: &PersistentLeafHistogramRecord<'_>) -> String {
    serde_json::to_string(record).expect("persistent leaf histogram record should serialize")
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn append_persistent_leaf_histogram_record(
    path: &std::path::Path,
    record: &PersistentLeafHistogramRecord<'_>,
) -> AnnResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).map_err(|err| {
            AnnError::log_index_error(format!(
                "Failed to create persistent leaf histogram output directory {}: {err}",
                parent.display()
            ))
        })?;
    }
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .map_err(|err| {
            AnnError::log_index_error(format!(
                "Failed to open persistent leaf histogram output {}: {err}",
                path.display()
            ))
        })?;
    use std::io::Write;
    writeln!(file, "{}", persistent_leaf_histogram_record_json(record)).map_err(|err| {
        AnnError::log_index_error(format!(
            "Failed to write persistent leaf histogram output {}: {err}",
            path.display()
        ))
    })
}

#[cfg(any(feature = "pipnn_cuda", test))]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) struct GpuPersistentSubtreePlan {
    pub(crate) attempted: bool,
    pub(crate) supported: bool,
    pub(crate) partition_worker_blocks: usize,
    pub(crate) topk_worker_blocks: usize,
    pub(crate) max_queue_nodes: usize,
    pub(crate) max_queue_rows: usize,
    pub(crate) max_leaf_count: usize,
    pub(crate) max_leaf_rows: usize,
    pub(crate) leaf_min: usize,
    pub(crate) leaf_target: usize,
    pub(crate) leaf_max: usize,
    pub(crate) leaf_tile_rows: usize,
    pub(crate) large_scratch_rows: usize,
    pub(crate) large_assignment_slots: usize,
    pub(crate) large_child_slots: usize,
    pub(crate) effective_root_fanout: usize,
    pub(crate) effective_deeper_fanout: usize,
    pub(crate) fanout_amplification: usize,
    pub(crate) fallback_reason_flags: u32,
    pub(crate) overflow_flags: u32,
    pub(crate) small_node_limit: usize,
    pub(crate) scalar_large_node_limit: usize,
    pub(crate) required_bytes: usize,
    pub(crate) resident_device_bytes: usize,
    pub(crate) device_admission_required_bytes: usize,
    pub(crate) device_admission_budget_bytes: usize,
    pub(crate) budget_bytes: usize,
    pub(crate) tessa_capture_enabled: bool,
    pub(crate) tessa_capture_member_words: usize,
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn tessa_capture_member_words(resident_rows: usize) -> Option<usize> {
    let cells_per_row_bin = TESSA_ASSIGNMENT_LEADER_BINS.checked_mul(TESSA_ASSIGNMENT_BIN_LIMIT)?;
    let per_leader_bin = TESSA_CAPTURE_SMALL_ROW_CAPACITY
        .checked_add(TESSA_CAPTURE_MEDIUM_ROW_CAPACITY)?
        .checked_add(resident_rows)?;
    cells_per_row_bin.checked_mul(per_leader_bin)
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn tessa_capture_workspace_bytes(resident_rows: usize) -> Option<usize> {
    let member_words = tessa_capture_member_words(resident_rows)?;
    TESSA_CAPTURE_ASSIGNMENT_CELLS
        .checked_mul(std::mem::size_of::<u32>())?
        .checked_add(TESSA_CAPTURE_ASSIGNMENT_CELLS.checked_mul(std::mem::size_of::<u64>())?)?
        .checked_add(
            TESSA_CAPTURE_ASSIGNMENT_SLOTS
                .checked_mul(2)?
                .checked_mul(std::mem::size_of::<u64>())?,
        )?
        .checked_add(
            TESSA_CAPTURE_ASSIGNMENT_SLOTS
                .checked_mul(TESSA_CAPTURE_ASSIGNMENT_METADATA_WORDS)?
                .checked_mul(std::mem::size_of::<u32>())?,
        )?
        .checked_add(member_words.checked_mul(std::mem::size_of::<u32>())?)?
        .checked_add(
            TESSA_CAPTURE_ASSIGNMENT_SLOTS
                .checked_mul(GPU_QUEUE_LEADER_STRIDE)?
                .checked_mul(std::mem::size_of::<u32>())?,
        )
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn gpu_persistent_worker_blocks_for_capacity(capacity: usize) -> usize {
    match capacity {
        0..=8 => 1,
        9..=16 => 2,
        17..=512 => 4,
        _ => capacity.div_ceil(512).clamp(8, 128),
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn cap_gpu_persistent_worker_blocks_with_limit(
    partition: usize,
    topk: usize,
    max_grid_blocks: usize,
) -> (usize, usize) {
    let partition = partition.max(1);
    let topk = topk.max(1);
    let total = partition.saturating_add(topk);
    if total <= max_grid_blocks {
        return (partition, topk);
    }
    let cap = max_grid_blocks.max(2);
    let mut capped_partition = partition.saturating_mul(cap) / total;
    capped_partition = capped_partition.clamp(1, cap - 1);
    let capped_topk = cap - capped_partition;
    (capped_partition, capped_topk.max(1))
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn cap_gpu_persistent_worker_blocks(partition: usize, topk: usize) -> (usize, usize) {
    cap_gpu_persistent_worker_blocks_with_limit(partition, topk, GPU_PERSISTENT_MAX_GRID_BLOCKS)
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn default_gpu_persistent_worker_split_with_limit(max_grid_blocks: usize) -> (usize, usize) {
    let cap = max_grid_blocks.max(2);
    (1, cap - 1)
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn gpu_persistent_worker_split_from_raw(
    raw: Option<&str>,
    _partition: usize,
    _topk: usize,
    max_grid_blocks: usize,
) -> AnnResult<(usize, usize)> {
    let Some(raw) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(default_gpu_persistent_worker_split_with_limit(
            max_grid_blocks,
        ));
    };
    let delimiter = if raw.contains(':') {
        ':'
    } else if raw.contains(',') {
        ','
    } else {
        return Err(AnnError::log_index_config_error(
            "SHEAR_PIPNN_PERSISTENT_WORKER_SPLIT".to_string(),
            "expected 'partition:topk' or 'partition,topk'".to_string(),
        ));
    };
    let mut parts = raw.split(delimiter);
    let partition_raw = parts.next().unwrap_or_default().trim();
    let topk_raw = parts.next().unwrap_or_default().trim();
    if parts.next().is_some() || partition_raw.is_empty() || topk_raw.is_empty() {
        return Err(AnnError::log_index_config_error(
            "SHEAR_PIPNN_PERSISTENT_WORKER_SPLIT".to_string(),
            "expected exactly two positive integer fields".to_string(),
        ));
    }
    let partition_override = partition_raw.parse::<usize>().map_err(|err| {
        AnnError::log_index_config_error(
            "SHEAR_PIPNN_PERSISTENT_WORKER_SPLIT".to_string(),
            format!("failed to parse partition worker count '{partition_raw}': {err}"),
        )
    })?;
    let topk_override = topk_raw.parse::<usize>().map_err(|err| {
        AnnError::log_index_config_error(
            "SHEAR_PIPNN_PERSISTENT_WORKER_SPLIT".to_string(),
            format!("failed to parse top-k worker count '{topk_raw}': {err}"),
        )
    })?;
    if partition_override == 0 || topk_override == 0 {
        return Err(AnnError::log_index_config_error(
            "SHEAR_PIPNN_PERSISTENT_WORKER_SPLIT".to_string(),
            "partition and top-k worker counts must be positive".to_string(),
        ));
    }
    let total = partition_override.saturating_add(topk_override);
    if total > max_grid_blocks.max(1) {
        return Err(AnnError::log_index_config_error(
            "SHEAR_PIPNN_PERSISTENT_WORKER_SPLIT".to_string(),
            format!(
                "explicit worker split {partition_override}:{topk_override} exceeds runtime grid cap {max_grid_blocks}"
            ),
        ));
    }
    Ok((partition_override, topk_override))
}

#[cfg(feature = "pipnn_cuda")]
fn gpu_persistent_worker_split_override_env() -> AnnResult<Option<String>> {
    match std::env::var("SHEAR_PIPNN_PERSISTENT_WORKER_SPLIT") {
        Ok(value) => Ok(Some(value)),
        Err(std::env::VarError::NotPresent) => Ok(None),
        Err(err) => Err(AnnError::log_index_config_error(
            "SHEAR_PIPNN_PERSISTENT_WORKER_SPLIT".to_string(),
            format!("environment value is not valid UTF-8: {err}"),
        )),
    }
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn gpu_persistent_subtree_max_leaders_per_node(params: &PiPNNParams) -> usize {
    // The persistent D1+ device queue has a fixed per-node leader slot array.
    // Root D0 can still use the larger dataset-level max_leaders contract.
    params.max_leaders.max(1).min(GPU_QUEUE_LEADER_STRIDE)
}

#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) fn gpu_persistent_subtree_max_leaders_for_params(params: &PiPNNParams) -> usize {
    gpu_persistent_subtree_max_leaders_per_node(params)
}

#[cfg(not(any(feature = "pipnn_cuda", test)))]
pub(crate) fn gpu_persistent_subtree_max_leaders_for_params(params: &PiPNNParams) -> usize {
    params.max_leaders.max(1)
}

#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) fn plan_gpu_persistent_subtree(
    resident_rows: usize,
    leaf_knn: usize,
    max_leaders_per_node: usize,
    max_fanout: usize,
    budget_bytes: Option<usize>,
    params: &PiPNNParams,
) -> GpuPersistentSubtreePlan {
    let mut plan = GpuPersistentSubtreePlan {
        attempted: true,
        supported: false,
        partition_worker_blocks: 1,
        topk_worker_blocks: 1,
        max_queue_nodes: resident_rows.max(1),
        max_queue_rows: resident_rows.max(1).saturating_mul(4096),
        max_leaf_count: resident_rows.max(1),
        max_leaf_rows: resident_rows,
        leaf_min: GPU_PERSISTENT_LEAF_MIN,
        leaf_target: GPU_PERSISTENT_LEAF_TARGET,
        leaf_max: GPU_PERSISTENT_LEAF_MAX.max(params.c_max.max(1)),
        leaf_tile_rows: params.gpu_subtree_persistent_leaf_tile_rows.max(1),
        large_scratch_rows: resident_rows.max(1),
        large_assignment_slots: resident_rows
            .max(1)
            .saturating_mul(max_fanout.max(1).min(4)),
        large_child_slots: GPU_QUEUE_LEADER_STRIDE,
        effective_root_fanout: max_fanout.max(1),
        effective_deeper_fanout: 1,
        fanout_amplification: max_fanout.max(1),
        fallback_reason_flags: 0,
        overflow_flags: 0,
        small_node_limit: 4096,
        scalar_large_node_limit: GPU_PERSISTENT_SCALAR_LARGE_NODE_LIMIT,
        required_bytes: 0,
        resident_device_bytes: 0,
        device_admission_required_bytes: 0,
        device_admission_budget_bytes: usize::MAX,
        budget_bytes: budget_bytes.unwrap_or(usize::MAX),
        tessa_capture_enabled: params.gpu_subtree_tessa_capture_dir.is_some(),
        tessa_capture_member_words: 0,
    };
    let persistent_fanout = max_fanout.max(1);
    let effective_fanout = max_fanout.max(1).min(4);
    plan.effective_root_fanout = effective_fanout;
    plan.effective_deeper_fanout = 1;
    plan.fanout_amplification = effective_fanout;
    plan.max_queue_nodes = resident_rows
        .max(1)
        .saturating_mul(plan.fanout_amplification)
        .saturating_add(resident_rows.max(1).div_ceil(plan.leaf_min.max(1)))
        .max(1);
    plan.max_queue_rows = resident_rows
        .max(1)
        .saturating_mul(plan.fanout_amplification)
        .saturating_mul(GPU_PERSISTENT_ROW_ARENA_FRONTIER_MULTIPLIER)
        .max(resident_rows.max(1));
    plan.max_leaf_rows = resident_rows.saturating_mul(plan.fanout_amplification);
    let semantic_leaf_count = plan
        .max_leaf_rows
        .max(1)
        .div_ceil(plan.leaf_min.max(1))
        .saturating_mul(8)
        .max(1);
    let staged_col_task_build = params.gpu_subtree_rabitq_plus_mode
        == PiPNNGpuSubtreeRabitqPlusMode::Build
        || params.gpu_subtree_sq_wmma_mode == PiPNNGpuSubtreeSqWmmaMode::Build;
    let max_col_tasks_per_tile = if staged_col_task_build {
        plan.leaf_max.max(1).div_ceil(128).max(1)
    } else {
        1
    };
    let max_tile_descriptors = plan
        .max_leaf_rows
        .max(1)
        .div_ceil(plan.leaf_tile_rows.max(1))
        .saturating_mul(8)
        .saturating_mul(max_col_tasks_per_tile)
        .max(1);
    plan.max_leaf_count = semantic_leaf_count.max(max_tile_descriptors);
    plan.large_scratch_rows = resident_rows
        .max(1)
        .saturating_mul(plan.fanout_amplification);
    plan.large_assignment_slots = resident_rows.max(1).saturating_mul(effective_fanout);
    plan.large_child_slots = GPU_QUEUE_LEADER_STRIDE;
    plan.partition_worker_blocks = gpu_persistent_worker_blocks_for_capacity(plan.max_queue_nodes);
    let topk_worker_capacity = if plan.fanout_amplification > 1 {
        plan.max_leaf_count
            .saturating_mul(plan.fanout_amplification)
    } else {
        plan.max_leaf_count
    };
    plan.topk_worker_blocks = gpu_persistent_worker_blocks_for_capacity(topk_worker_capacity);
    let (partition_worker_blocks, topk_worker_blocks) =
        cap_gpu_persistent_worker_blocks(plan.partition_worker_blocks, plan.topk_worker_blocks);
    plan.partition_worker_blocks = partition_worker_blocks;
    plan.topk_worker_blocks = topk_worker_blocks;
    let persistent_queue_bytes = plan
        .max_queue_nodes
        .saturating_mul(7)
        .saturating_mul(std::mem::size_of::<u32>())
        .saturating_add(
            plan.max_queue_nodes
                .saturating_mul(2)
                .saturating_mul(std::mem::size_of::<u32>()),
        )
        .saturating_add(
            plan.max_queue_rows
                .saturating_mul(std::mem::size_of::<u32>()),
        )
        .saturating_add(
            plan.max_leaf_count
                .saturating_mul(8)
                .saturating_mul(std::mem::size_of::<u32>()),
        )
        .saturating_add(GPU_QUEUE_COUNTER_WORDS.saturating_mul(std::mem::size_of::<u64>()));
    let persistent_large_scratch_bytes = plan
        .large_scratch_rows
        .saturating_mul(4)
        .saturating_mul(std::mem::size_of::<u32>())
        .saturating_add(
            plan.large_child_slots
                .saturating_mul(4)
                .saturating_mul(std::mem::size_of::<u32>()),
        )
        .saturating_add(std::mem::size_of::<u32>());
    let persistent_layout_bytes = plan
        .max_leaf_rows
        .saturating_mul(2)
        .saturating_mul(std::mem::size_of::<u32>())
        .saturating_add(
            plan.max_leaf_rows
                .saturating_mul(std::mem::size_of::<u32>()),
        )
        .saturating_add(
            plan.max_leaf_count
                .saturating_mul(2)
                .saturating_mul(std::mem::size_of::<u64>()),
        );
    let persistent_output_bytes =
        estimate_compact_topk_dtoh_bytes(plan.max_leaf_rows, leaf_knn.min(32));
    plan.required_bytes = persistent_queue_bytes
        .saturating_add(persistent_large_scratch_bytes)
        .saturating_add(persistent_layout_bytes)
        .saturating_add(persistent_output_bytes);
    if plan.tessa_capture_enabled {
        match (
            tessa_capture_member_words(resident_rows),
            tessa_capture_workspace_bytes(resident_rows),
        ) {
            (Some(member_words), Some(capture_bytes)) => {
                plan.tessa_capture_member_words = member_words;
                plan.required_bytes = plan.required_bytes.saturating_add(capture_bytes);
            }
            _ => {
                plan.fallback_reason_flags |= GPU_PERSISTENT_FALLBACK_REASON_WORKSPACE;
                plan.overflow_flags |= GPU_QUEUE_OVERFLOW_WORKSPACE_BUDGET;
            }
        }
    }
    if resident_rows != 0 && budget_bytes.is_some_and(|budget| plan.required_bytes > budget) {
        plan.fallback_reason_flags |= GPU_PERSISTENT_FALLBACK_REASON_WORKSPACE;
        plan.overflow_flags |= GPU_QUEUE_OVERFLOW_WORKSPACE_BUDGET;
    }
    plan.device_admission_required_bytes = plan.required_bytes;
    if leaf_knn > 32 {
        plan.fallback_reason_flags |= GPU_PERSISTENT_FALLBACK_REASON_UNSUPPORTED_K;
        plan.overflow_flags |= GPU_QUEUE_OVERFLOW_LEAF_DESC;
    }
    if persistent_fanout > 4 {
        plan.fallback_reason_flags |= GPU_PERSISTENT_FALLBACK_REASON_UNSUPPORTED_FANOUT;
        plan.overflow_flags |= GPU_QUEUE_OVERFLOW_FANOUT_OVER_32;
    }
    if max_leaders_per_node > GPU_QUEUE_LEADER_STRIDE {
        plan.fallback_reason_flags |= GPU_PERSISTENT_FALLBACK_REASON_UNSUPPORTED_LEADERS;
        plan.overflow_flags |= GPU_QUEUE_OVERFLOW_LEADER;
    }
    plan.supported = plan.fallback_reason_flags == 0;
    plan
}

#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) fn plan_gpu_persistent_subtree_resident_admission(
    resident_rows: usize,
    dim: usize,
    leaf_knn: usize,
    max_leaders_per_node: usize,
    max_fanout: usize,
    workspace_budget_bytes: Option<usize>,
    device_budget_bytes: Option<usize>,
    params: &PiPNNParams,
) -> GpuPersistentSubtreePlan {
    let mut plan = plan_gpu_persistent_subtree(
        resident_rows,
        leaf_knn,
        max_leaders_per_node,
        max_fanout,
        workspace_budget_bytes,
        params,
    );
    plan.resident_device_bytes =
        estimate_gpu_resident_subtree_device_bytes_for_params(resident_rows, dim, params);
    plan.device_admission_required_bytes = plan
        .resident_device_bytes
        .saturating_add(plan.required_bytes);
    plan.device_admission_budget_bytes = device_budget_bytes.unwrap_or(usize::MAX);
    if resident_rows != 0
        && device_budget_bytes.is_some_and(|budget| plan.device_admission_required_bytes > budget)
    {
        plan.fallback_reason_flags |= GPU_PERSISTENT_FALLBACK_REASON_WORKSPACE;
        plan.overflow_flags |= GPU_QUEUE_OVERFLOW_WORKSPACE_BUDGET;
        plan.supported = false;
    }
    plan
}

#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) fn annotate_gpu_persistent_subtree_resident_diagnostics(
    mut plan: GpuPersistentSubtreePlan,
    resident_rows: usize,
    dim: usize,
    params: &PiPNNParams,
    device_budget_bytes: Option<usize>,
) -> GpuPersistentSubtreePlan {
    plan.resident_device_bytes =
        estimate_gpu_resident_subtree_device_bytes_for_params(resident_rows, dim, params);
    plan.device_admission_required_bytes = plan
        .resident_device_bytes
        .saturating_add(plan.required_bytes);
    plan.device_admission_budget_bytes = device_budget_bytes.unwrap_or(usize::MAX);
    plan
}

