#[cfg(any(feature = "pipnn_cuda", test))]
fn gpu_queue_root_seed(request: &GpuSubtreePartitionRequest<'_>, params: &PiPNNParams) -> u64 {
    params.random_seed
        ^ (request.depth as u64).wrapping_mul(0x9e3779b97f4a7c15)
        ^ (request.point_ids.len() as u64).rotate_left(17)
        ^ (request.parent_points as u64).rotate_left(7)
        ^ (request.min_recurse_size as u64).rotate_left(29)
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn pack_row_major_to_col_major(rows: usize, cols: usize, row_major: &[f32]) -> Vec<f32> {
    let mut col_major = vec![0.0f32; rows.saturating_mul(cols)];
    for row in 0..rows {
        for col in 0..cols {
            col_major[col * rows + row] = row_major[row * cols + col];
        }
    }
    col_major
}

#[cfg(any(feature = "pipnn_cuda", test))]
fn unpack_col_major_to_row_major(rows: usize, cols: usize, col_major: &[f32]) -> Vec<f32> {
    let mut row_major = vec![0.0f32; rows.saturating_mul(cols)];
    for row in 0..rows {
        for col in 0..cols {
            row_major[row * cols + col] = col_major[col * rows + row];
        }
    }
    row_major
}

#[cfg(feature = "pipnn_cuda")]
fn estimate_library_leaf_gemm_topk_workspace_bytes(rows: usize, dim: usize, k: usize) -> usize {
    let vector_bytes = rows
        .saturating_mul(dim)
        .saturating_mul(std::mem::size_of::<f32>());
    let gram_bytes = rows
        .saturating_mul(rows)
        .saturating_mul(std::mem::size_of::<f32>());
    vector_bytes
        .saturating_mul(2)
        .saturating_add(gram_bytes)
        .saturating_add(rows.saturating_mul(std::mem::size_of::<u32>()))
        .saturating_add(rows.saturating_mul(std::mem::size_of::<f32>()))
        .saturating_add(estimate_compact_topk_dtoh_bytes(rows, k))
}

#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) fn estimate_compact_topk_dtoh_bytes(rows: usize, k: usize) -> usize {
    rows.saturating_mul(k)
        .saturating_mul(std::mem::size_of::<u32>().saturating_add(std::mem::size_of::<f32>()))
}

#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) fn plan_compact_topk_l2_workspace(
    rows: usize,
    dim: usize,
    k: usize,
    budget_bytes: Option<usize>,
) -> Option<CompactTopKWorkspacePlan> {
    plan_compact_topk_l2_batch_workspace(rows, dim, k, 1, budget_bytes)
}

#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) fn plan_compact_topk_l2_batch_workspace(
    rows: usize,
    dim: usize,
    k: usize,
    leaf_count: usize,
    budget_bytes: Option<usize>,
) -> Option<CompactTopKWorkspacePlan> {
    let h2d_bytes = rows
        .saturating_mul(dim)
        .saturating_mul(std::mem::size_of::<f32>())
        .saturating_add(rows.saturating_mul(std::mem::size_of::<u32>()))
        .saturating_add(rows.saturating_mul(std::mem::size_of::<f32>()))
        .saturating_add(
            leaf_count
                .saturating_mul(2)
                .saturating_mul(std::mem::size_of::<u64>()),
        );
    let dtoh_bytes = estimate_compact_topk_dtoh_bytes(rows, k);
    let required_bytes = h2d_bytes.saturating_add(dtoh_bytes);
    let Some(budget_bytes) = budget_bytes else {
        return Some(CompactTopKWorkspacePlan {
            row_tile_rows: rows,
            h2d_bytes,
            dtoh_bytes,
            required_bytes,
            pressure: false,
        });
    };

    if required_bytes <= budget_bytes {
        return Some(CompactTopKWorkspacePlan {
            row_tile_rows: rows,
            h2d_bytes,
            dtoh_bytes,
            required_bytes,
            pressure: false,
        });
    }
    if h2d_bytes > budget_bytes {
        return None;
    }

    let per_output_row = estimate_compact_topk_dtoh_bytes(1, k).max(1);
    let row_tile_rows = ((budget_bytes - h2d_bytes) / per_output_row).min(rows);
    if row_tile_rows == 0 {
        return None;
    }
    let tile_dtoh_bytes = estimate_compact_topk_dtoh_bytes(row_tile_rows, k);
    Some(CompactTopKWorkspacePlan {
        row_tile_rows,
        h2d_bytes,
        dtoh_bytes,
        required_bytes: h2d_bytes.saturating_add(tile_dtoh_bytes),
        pressure: true,
    })
}

#[cfg(any(feature = "pipnn_cuda", test))]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct CompactTopKLeafBatchPlan {
    pub(crate) leaf_start: usize,
    pub(crate) leaf_end: usize,
    pub(crate) rows: usize,
    pub(crate) max_k: usize,
    pub(crate) workspace_plan: CompactTopKWorkspacePlan,
}

#[cfg(any(feature = "pipnn_cuda", test))]
pub(crate) fn plan_compact_topk_leaf_batches(
    leaf_sizes: &[usize],
    dim: usize,
    leaf_knn: usize,
    budget_bytes: Option<usize>,
) -> AnnResult<Vec<CompactTopKLeafBatchPlan>> {
    let mut batches = Vec::new();
    let mut leaf_start = 0usize;
    let mut rows = 0usize;
    let mut max_k = 0usize;
    let mut workspace_plan: Option<CompactTopKWorkspacePlan> = None;

    for (leaf_idx, &leaf_size) in leaf_sizes.iter().enumerate() {
        let k = leaf_knn.min(leaf_size.saturating_sub(1));
        if leaf_size <= 1 || k == 0 {
            return Err(AnnError::log_index_error(format!(
                "CUDA compact top-k leaf batch planner expects GPU-eligible leaves, got leaf_size={leaf_size} k={k}"
            )));
        }

        let candidate_rows = rows.saturating_add(leaf_size);
        let candidate_max_k = max_k.max(k);
        let candidate_leaf_count = leaf_idx + 1 - leaf_start;
        let candidate_plan = plan_compact_topk_l2_batch_workspace(
            candidate_rows,
            dim,
            candidate_max_k,
            candidate_leaf_count,
            budget_bytes,
        );

        match candidate_plan {
            Some(plan) if !plan.pressure => {
                rows = candidate_rows;
                max_k = candidate_max_k;
                workspace_plan = Some(plan);
            }
            _ if rows > 0 => {
                batches.push(CompactTopKLeafBatchPlan {
                    leaf_start,
                    leaf_end: leaf_idx,
                    rows,
                    max_k,
                    workspace_plan: workspace_plan.expect("non-empty compact top-k batch has plan"),
                });
                leaf_start = leaf_idx;

                let single_plan =
                    plan_compact_topk_l2_batch_workspace(leaf_size, dim, k, 1, budget_bytes);
                let Some(single_plan) = single_plan.filter(|plan| !plan.pressure) else {
                    let full_required_bytes =
                        plan_compact_topk_l2_batch_workspace(leaf_size, dim, k, 1, None)
                            .map(|plan| plan.required_bytes)
                            .unwrap_or(0);
                    return Err(AnnError::log_index_error(format!(
                        "CUDA compact top-k workspace budget is too small for one compact leaf batch: rows={leaf_size} dim={dim} k={k} leaves=1 required_bytes={full_required_bytes} budget_bytes={}",
                        budget_bytes.unwrap_or(0)
                    )));
                };
                rows = leaf_size;
                max_k = k;
                workspace_plan = Some(single_plan);
            }
            _ => {
                let full_required_bytes =
                    plan_compact_topk_l2_batch_workspace(leaf_size, dim, k, 1, None)
                        .map(|plan| plan.required_bytes)
                        .unwrap_or(0);
                return Err(AnnError::log_index_error(format!(
                    "CUDA compact top-k workspace budget is too small for one compact leaf batch: rows={leaf_size} dim={dim} k={k} leaves=1 required_bytes={full_required_bytes} budget_bytes={}",
                    budget_bytes.unwrap_or(0)
                )));
            }
        }
    }

    if rows > 0 {
        batches.push(CompactTopKLeafBatchPlan {
            leaf_start,
            leaf_end: leaf_sizes.len(),
            rows,
            max_k,
            workspace_plan: workspace_plan.expect("non-empty compact top-k batch has plan"),
        });
    }

    Ok(batches)
}

