#[derive(Clone, Copy, Debug)]
pub(crate) enum GpuSubtreeQuantizedDistanceKind {
    RabitqPlus,
    SqInt8,
    TurboQuantMse4,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) enum GpuSubtreeQuantizedCodeLayout {
    #[default]
    DenseI8,
    PackedS4,
}

impl GpuSubtreeQuantizedCodeLayout {
    #[inline]
    fn kernel_code(self) -> u32 {
        match self {
            Self::DenseI8 => 0,
            Self::PackedS4 => 1,
        }
    }
}

#[inline]
fn gpu_subtree_sq_native_int4_requested(params: &PiPNNParams) -> bool {
    params.gpu_subtree_sq_native_int4
}

#[inline]
fn gpu_subtree_sq_native_int4_required_layout() -> GpuSubtreeQuantizedCodeLayout {
    GpuSubtreeQuantizedCodeLayout::PackedS4
}

#[derive(Clone, Copy, Debug)]
pub(crate) struct GpuSubtreeQuantizedInput<'a> {
    pub(crate) distance_kind: GpuSubtreeQuantizedDistanceKind,
    pub(crate) global_ids: &'a [u32],
    pub(crate) codes: &'a [i8],
    pub(crate) deltas: &'a [f32],
    pub(crate) code_sums: &'a [f32],
    pub(crate) norms: &'a [f32],
    pub(crate) dim: usize,
    pub(crate) padded_dim: usize,
    pub(crate) code_layout: GpuSubtreeQuantizedCodeLayout,
    pub(crate) code_row_bytes: usize,
    pub(crate) bits: usize,
}

#[derive(Clone, Debug)]
pub(crate) struct OwnedGpuSubtreeQuantizedInput {
    pub(crate) distance_kind: GpuSubtreeQuantizedDistanceKind,
    pub(crate) global_ids: Arc<Vec<u32>>,
    pub(crate) codes: Arc<Vec<i8>>,
    pub(crate) deltas: Arc<Vec<f32>>,
    pub(crate) code_sums: Arc<Vec<f32>>,
    pub(crate) norms: Arc<Vec<f32>>,
    pub(crate) dim: usize,
    pub(crate) padded_dim: usize,
    pub(crate) code_layout: GpuSubtreeQuantizedCodeLayout,
    pub(crate) code_row_bytes: usize,
    pub(crate) bits: usize,
}

impl OwnedGpuSubtreeQuantizedInput {
    pub(crate) fn as_borrowed(&self) -> GpuSubtreeQuantizedInput<'_> {
        GpuSubtreeQuantizedInput {
            distance_kind: self.distance_kind,
            global_ids: self.global_ids.as_slice(),
            codes: self.codes.as_slice(),
            deltas: self.deltas.as_slice(),
            code_sums: self.code_sums.as_slice(),
            norms: self.norms.as_slice(),
            dim: self.dim,
            padded_dim: self.padded_dim,
            code_layout: self.code_layout,
            code_row_bytes: self.code_row_bytes,
            bits: self.bits,
        }
    }

    fn estimated_host_bytes(&self) -> usize {
        self.global_ids
            .capacity()
            .saturating_mul(std::mem::size_of::<u32>())
            .saturating_add(
                self.codes
                    .capacity()
                    .saturating_mul(std::mem::size_of::<i8>()),
            )
            .saturating_add(
                self.deltas
                    .capacity()
                    .saturating_mul(std::mem::size_of::<f32>()),
            )
            .saturating_add(
                self.code_sums
                    .capacity()
                    .saturating_mul(std::mem::size_of::<f32>()),
            )
            .saturating_add(
                self.norms
                    .capacity()
                    .saturating_mul(std::mem::size_of::<f32>()),
            )
    }
}

