    fn query_cuda_driver_version() -> AnnResult<i32> {
        let mut version = 0;
        unsafe { sys::cuDriverGetVersion(&mut version).result() }.map_err(|err| {
            AnnError::log_index_error(format!("Failed to query CUDA driver version: {err}"))
        })?;
        if version <= 0 {
            return Err(AnnError::log_index_error(format!(
                "CUDA driver version query returned nonpositive value {version}"
            )));
        }
        Ok(version)
    }

    #[cfg(target_os = "linux")]
    struct CudaRuntimeLibraryHandle(*mut libc::c_void);

    #[cfg(target_os = "linux")]
    impl Drop for CudaRuntimeLibraryHandle {
        fn drop(&mut self) {
            unsafe {
                libc::dlclose(self.0);
            }
        }
    }

    #[cfg(target_os = "linux")]
    fn take_dynamic_loader_error() -> Option<String> {
        let error = unsafe { libc::dlerror() };
        if error.is_null() {
            None
        } else {
            Some(
                unsafe { std::ffi::CStr::from_ptr(error) }
                    .to_string_lossy()
                    .into_owned(),
            )
        }
    }

    #[cfg(target_os = "linux")]
    fn query_cuda_runtime_version() -> AnnResult<i32> {
        type CudaRuntimeGetVersionFn = unsafe extern "C" fn(*mut libc::c_int) -> libc::c_int;

        const CANDIDATES: [&str; 4] = [
            "libcudart.so",
            "libcudart.so.13",
            "libcudart.so.12",
            "libcudart.so.11",
        ];
        const SYMBOL: &[u8] = b"cudaRuntimeGetVersion\0";

        let mut attempts = Vec::with_capacity(CANDIDATES.len());
        let mut loaded_any = false;
        for candidate in CANDIDATES {
            let candidate_c = std::ffi::CString::new(candidate)
                .expect("CUDA runtime library candidate must not contain NUL");
            let _ = take_dynamic_loader_error();
            let raw_handle =
                unsafe { libc::dlopen(candidate_c.as_ptr(), libc::RTLD_NOW | libc::RTLD_LOCAL) };
            if raw_handle.is_null() {
                let error = take_dynamic_loader_error()
                    .unwrap_or_else(|| "unknown dynamic loader error".to_string());
                attempts.push(format!("{candidate}: dlopen failed: {error}"));
                continue;
            }

            loaded_any = true;
            let handle = CudaRuntimeLibraryHandle(raw_handle);
            let _ = take_dynamic_loader_error();
            let raw_symbol = unsafe { libc::dlsym(handle.0, SYMBOL.as_ptr().cast()) };
            if let Some(error) = take_dynamic_loader_error() {
                attempts.push(format!(
                    "{candidate}: dlsym(cudaRuntimeGetVersion) failed: {error}"
                ));
                continue;
            }
            if raw_symbol.is_null() {
                attempts.push(format!(
                    "{candidate}: dlsym(cudaRuntimeGetVersion) returned null without an error"
                ));
                continue;
            }

            let get_runtime_version: CudaRuntimeGetVersionFn =
                unsafe { std::mem::transmute(raw_symbol) };
            let mut version: libc::c_int = 0;
            let status = unsafe { get_runtime_version(&mut version) };
            if status != 0 {
                attempts.push(format!(
                    "{candidate}: cudaRuntimeGetVersion returned status {status}"
                ));
                continue;
            }
            if version <= 0 {
                attempts.push(format!(
                    "{candidate}: cudaRuntimeGetVersion returned nonpositive version {version}"
                ));
                continue;
            }
            return Ok(version);
        }

        let attempted_candidates = CANDIDATES.join(", ");
        let details = attempts.join("; ");
        let summary = if loaded_any {
            "Failed to query a valid CUDA runtime version from loaded CUDA runtime libraries"
        } else {
            "Failed to load any CUDA runtime library"
        };
        Err(AnnError::log_index_error(format!(
            "{summary}; attempted candidates: [{attempted_candidates}]; details: {details}"
        )))
    }

    #[cfg(not(target_os = "linux"))]
    fn query_cuda_runtime_version() -> AnnResult<i32> {
        Err(AnnError::log_index_error(
            "CUDA runtime version lookup through libcudart is supported only on Linux".to_string(),
        ))
    }

    fn query_gpu_device_caps(
        context: &Arc<CudaContext>,
        device_id: usize,
    ) -> AnnResult<GpuDeviceCaps> {
        let checked_usize = |fact_name: &str, value: i32| {
            usize::try_from(value).map_err(|_| {
                AnnError::log_index_error(format!(
                    "CUDA {fact_name} query returned negative value {value}"
                ))
            })
        };
        let query_attribute =
            |attribute: sys::CUdevice_attribute, attribute_name: &str| -> AnnResult<usize> {
                let value = context.attribute(attribute).map_err(|err| {
                    AnnError::log_index_error(format!(
                        "Failed to query CUDA attribute {attribute_name}: {err}"
                    ))
                })?;
                checked_usize(attribute_name, value)
            };

        let device_name = context.name().map_err(|err| {
            AnnError::log_index_error(format!("Failed to query CUDA device name: {err}"))
        })?;
        let device_uuid = context
            .uuid()
            .map_err(|err| {
                AnnError::log_index_error(format!("Failed to query CUDA device UUID: {err}"))
            })?
            .bytes
            .iter()
            .map(|byte| format!("{:02x}", *byte as u8))
            .collect::<String>();
        let (compute_capability_major, compute_capability_minor) =
            context.compute_capability().map_err(|err| {
                AnnError::log_index_error(format!("Failed to query CUDA compute capability: {err}"))
            })?;
        let compute_capability_major =
            checked_usize("compute capability major", compute_capability_major)?;
        let compute_capability_minor =
            checked_usize("compute capability minor", compute_capability_minor)?;
        let sm_count = query_attribute(
            sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT,
            "CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT",
        )?;
        let warp_size = query_attribute(
            sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_WARP_SIZE,
            "CU_DEVICE_ATTRIBUTE_WARP_SIZE",
        )?;
        let max_threads_per_block = query_attribute(
            sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_MAX_THREADS_PER_BLOCK,
            "CU_DEVICE_ATTRIBUTE_MAX_THREADS_PER_BLOCK",
        )?;
        let max_threads_per_sm = query_attribute(
            sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_MAX_THREADS_PER_MULTIPROCESSOR,
            "CU_DEVICE_ATTRIBUTE_MAX_THREADS_PER_MULTIPROCESSOR",
        )?;
        let max_blocks_per_sm = query_attribute(
            sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_MAX_BLOCKS_PER_MULTIPROCESSOR,
            "CU_DEVICE_ATTRIBUTE_MAX_BLOCKS_PER_MULTIPROCESSOR",
        )?;
        let max_shared_bytes_per_block = query_attribute(
            sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN,
            "CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN",
        )?;
        let max_shared_bytes_per_sm = query_attribute(
            sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_MULTIPROCESSOR,
            "CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_MULTIPROCESSOR",
        )?;

        context.bind_to_thread().map_err(|err| {
            AnnError::log_index_error(format!(
                "Failed to bind CUDA context before device memory info query: {err}"
            ))
        })?;
        let (_free_hbm_bytes, total_hbm_bytes) = cuda_result::mem_get_info().map_err(|err| {
            AnnError::log_index_error(format!("Failed to query CUDA device memory info: {err}"))
        })?;
        let driver_version = query_cuda_driver_version()?;
        let runtime_version = query_cuda_runtime_version()?;

        Ok(GpuDeviceCaps {
            device_id,
            device_uuid,
            device_name,
            compute_capability_major,
            compute_capability_minor,
            sm_count,
            warp_size,
            max_threads_per_block,
            max_threads_per_sm,
            max_blocks_per_sm,
            max_shared_bytes_per_block,
            max_shared_bytes_per_sm,
            total_hbm_bytes,
            driver_version,
            runtime_version,
        })
    }

    fn trim_cuda_default_mempool_to_zero_for_stream(
        stream: &Arc<CudaStream>,
        label: &str,
    ) -> AnnResult<()> {
        stream.context().bind_to_thread().map_err(|err| {
            AnnError::log_index_error(format!(
                "CUDA context bind before trimming {label} mempool failed: {err}"
            ))
        })?;
        let mut pool = std::ptr::null_mut();
        unsafe {
            sys::cuDeviceGetDefaultMemPool(&mut pool, stream.context().cu_device())
                .result()
                .map_err(|err| {
                    AnnError::log_index_error(format!(
                        "CUDA default mempool lookup before trimming {label} failed: {err}"
                    ))
                })?;
            sys::cuMemPoolTrimTo(pool, 0).result().map_err(|err| {
                AnnError::log_index_error(format!(
                    "CUDA default mempool trim after releasing {label} failed: {err}"
                ))
            })?;
        }
        Ok(())
    }

    fn cuda_event_elapsed_duration(start: &CudaEvent, end: &CudaEvent) -> AnnResult<Duration> {
        let millis = start.elapsed_ms(end).map_err(|err| {
            AnnError::log_index_error(format!("CUDA event elapsed timing failed: {err}"))
        })?;
        Ok(Duration::from_secs_f64(f64::from(millis) / 1000.0))
    }

    fn persistent_subtree_nvrtc_arch(stream: &Arc<CudaStream>) -> AnnResult<Option<&'static str>> {
        let (major, minor) = stream.context().compute_capability().map_err(|err| {
            AnnError::log_index_error(format!(
                "Failed to query CUDA compute capability for persistent subtree kernel compilation: {err}"
            ))
        })?;
        let arch = match (major, minor) {
            (8, 0) => Some("compute_80"),
            (8, 6) => Some("compute_86"),
            (8, 7) => Some("compute_87"),
            (8, 9) => Some("compute_89"),
            (9, _) => Some("compute_90"),
            (major, _) if major > 9 => Some("compute_90"),
            _ => None,
        };
        Ok(arch)
    }

    fn persistent_subtree_runtime_grid_block_cap(stream: &Arc<CudaStream>) -> AnnResult<usize> {
        let sm_count = stream
            .context()
            .attribute(sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT)
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to query CUDA multiprocessor count for persistent subtree launch planning: {err}"
                ))
            })?;
        Ok((sm_count as usize)
            .max(1)
            .min(GPU_PERSISTENT_MAX_GRID_BLOCKS))
    }

    pub(super) fn persistent_subtree_nvrtc_include_paths() -> Vec<String> {
        let mut paths = Vec::new();
        let mut push_if_has_mma = |path: String| {
            if std::path::Path::new(&path).join("mma.h").is_file()
                && !paths.iter().any(|existing| existing == &path)
            {
                paths.push(path);
            }
        };

        for var in ["CUDA_HOME", "CUDA_PATH", "CUDA_ROOT"] {
            if let Ok(root) = std::env::var(var) {
                push_if_has_mma(format!("{root}/include"));
                push_if_has_mma(format!("{root}/targets/x86_64-linux/include"));
            }
        }
        push_if_has_mma("/usr/local/cuda/include".to_string());
        push_if_has_mma("/usr/local/cuda/targets/x86_64-linux/include".to_string());
        push_if_has_mma("/usr/local/cuda-13.0/include".to_string());
        push_if_has_mma("/usr/local/cuda-13.0/targets/x86_64-linux/include".to_string());
        paths
    }

