    fn cuda_host_assign_rows_to_nearest_centroids(
        rows_row_major: &[f32],
        rows: usize,
        dim: usize,
        centroids_row_major: &[f32],
    ) -> AnnResult<Vec<u32>> {
        if rows_row_major.len() != rows.saturating_mul(dim) {
            return Err(AnnError::log_index_error(format!(
                "CUDA residual RaBitQ leader shape mismatch: rows={} dim={} values={}",
                rows,
                dim,
                rows_row_major.len()
            )));
        }
        if centroids_row_major.is_empty() || centroids_row_major.len() % dim != 0 {
            return Err(AnnError::log_index_error(format!(
                "CUDA residual RaBitQ centroid shape mismatch: values={} dim={}",
                centroids_row_major.len(),
                dim
            )));
        }
        let centroid_count = centroids_row_major.len() / dim;
        let mut out = Vec::with_capacity(rows);
        for row in 0..rows {
            let row_values = &rows_row_major[row * dim..(row + 1) * dim];
            let mut best = 0usize;
            let mut best_dist = f32::INFINITY;
            for centroid_idx in 0..centroid_count {
                let centroid = &centroids_row_major[centroid_idx * dim..(centroid_idx + 1) * dim];
                let mut dist = 0.0_f32;
                for axis in 0..dim {
                    let diff = row_values[axis] - centroid[axis];
                    dist += diff * diff;
                }
                if dist < best_dist || (dist == best_dist && centroid_idx < best) {
                    best = centroid_idx;
                    best_dist = dist;
                }
            }
            out.push(best as u32);
        }
        Ok(out)
    }

    fn cuda_host_rabitq_residual_centroid_dots(
        centroids_row_major: &[f32],
        centroid_count: usize,
        dim: usize,
    ) -> AnnResult<Vec<f32>> {
        if centroids_row_major.len() != centroid_count.saturating_mul(dim) {
            return Err(AnnError::log_index_error(format!(
                "CUDA residual RaBitQ centroid-dot shape mismatch: values={} centroids={} dim={}",
                centroids_row_major.len(),
                centroid_count,
                dim
            )));
        }
        let mut centroid_dots = vec![0.0_f32; centroid_count.saturating_mul(centroid_count)];
        for left in 0..centroid_count {
            for right in 0..centroid_count {
                let mut dot = 0.0_f32;
                for axis in 0..dim {
                    dot += centroids_row_major[left * dim + axis]
                        * centroids_row_major[right * dim + axis];
                }
                centroid_dots[left * centroid_count + right] = dot;
            }
        }
        Ok(centroid_dots)
    }

    fn cuda_host_residualize_rows(
        rows_row_major: &[f32],
        centroid_ids: &[u32],
        centroids_row_major: &[f32],
        dim: usize,
    ) -> AnnResult<(Vec<f32>, Vec<f32>)> {
        let rows = centroid_ids.len();
        if rows_row_major.len() != rows.saturating_mul(dim) {
            return Err(AnnError::log_index_error(format!(
                "CUDA residual RaBitQ residualize shape mismatch: rows={} dim={} values={}",
                rows,
                dim,
                rows_row_major.len()
            )));
        }
        let centroid_count = centroids_row_major.len() / dim;
        let mut residuals = vec![0.0_f32; rows_row_major.len()];
        let mut original_norms = vec![0.0_f32; rows];
        for row in 0..rows {
            let centroid_id = centroid_ids[row] as usize;
            if centroid_id >= centroid_count {
                return Err(AnnError::log_index_error(format!(
                    "CUDA residual RaBitQ centroid id {} at row {} is outside centroid_count {}",
                    centroid_id, row, centroid_count
                )));
            }
            let centroid = &centroids_row_major[centroid_id * dim..(centroid_id + 1) * dim];
            let input = &rows_row_major[row * dim..(row + 1) * dim];
            let output = &mut residuals[row * dim..(row + 1) * dim];
            let mut norm = 0.0_f32;
            for axis in 0..dim {
                let value = input[axis];
                norm += value * value;
                output[axis] = value - centroid[axis];
            }
            original_norms[row] = norm;
        }
        Ok((residuals, original_norms))
    }

