    struct CudaCachedPinnedHostSlice<T> {
        ptr: *mut T,
        len: usize,
    }

    // CUDA owns and page-locks this allocation until Drop; moving the handle
    // between the copy and scatter threads does not move the allocation.
    unsafe impl<T: Send> Send for CudaCachedPinnedHostSlice<T> {}
    unsafe impl<T: Sync> Sync for CudaCachedPinnedHostSlice<T> {}

    impl<T> CudaCachedPinnedHostSlice<T> {
        fn allocate(context: &Arc<CudaContext>, len: usize, label: &str) -> AnnResult<Self> {
            context.bind_to_thread().map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to bind CUDA context for CPU-cacheable pinned {label}: {err}"
                ))
            })?;
            let bytes = len
                .checked_mul(std::mem::size_of::<T>())
                .ok_or_else(|| {
                    AnnError::log_index_error(format!(
                        "CPU-cacheable pinned CUDA {label} allocation size overflows: len={len} element_bytes={}",
                        std::mem::size_of::<T>()
                    ))
                })?;
            let ptr = if bytes == 0 {
                std::ptr::NonNull::<T>::dangling().as_ptr()
            } else {
                // Flags=0 deliberately keeps the host mapping CPU-cacheable.
                // cudarc::CudaContext::alloc_pinned uses WRITECOMBINED, which is
                // appropriate for H2D but makes the CPU scatter read path very slow.
                unsafe { cuda_result::malloc_host(bytes, 0) }
                    .map_err(|err| {
                        AnnError::log_index_error(format!(
                            "Failed to allocate CPU-cacheable pinned CUDA {label}: {err}"
                        ))
                    })?
                    .cast::<T>()
            };
            Ok(Self { ptr, len })
        }

        fn as_slice(&self) -> &[T] {
            // The copy worker synchronizes its payload event before publishing
            // the host slot, so no CUDA work can still be writing this range.
            unsafe { std::slice::from_raw_parts(self.ptr, self.len) }
        }

        fn as_mut_slice(&mut self) -> &mut [T] {
            // Allocation initialization and D2H submission have exclusive access.
            unsafe { std::slice::from_raw_parts_mut(self.ptr, self.len) }
        }
    }

    impl<T> Drop for CudaCachedPinnedHostSlice<T> {
        fn drop(&mut self) {
            if self.len != 0 {
                // A drop path cannot report an allocation teardown error.
                let _ = unsafe { cuda_result::free_host(self.ptr.cast()) };
            }
        }
    }

    impl<T> HostSlice<T> for CudaCachedPinnedHostSlice<T> {
        fn len(&self) -> usize {
            self.len
        }

        unsafe fn stream_synced_slice<'a>(
            &'a self,
            _stream: &'a CudaStream,
        ) -> (&'a [T], SyncOnDrop<'a>) {
            (self.as_slice(), SyncOnDrop::Sync(None))
        }

        unsafe fn stream_synced_mut_slice<'a>(
            &'a mut self,
            _stream: &'a CudaStream,
        ) -> (&'a mut [T], SyncOnDrop<'a>) {
            (self.as_mut_slice(), SyncOnDrop::Sync(None))
        }
    }

    struct CudaPinnedPersistentOutputSlot {
        capacity: PersistentOutputCapacity,
        counters: CudaCachedPinnedHostSlice<u64>,
        row_ids: CudaCachedPinnedHostSlice<u32>,
        leaf_starts: CudaCachedPinnedHostSlice<u64>,
        leaf_sizes: CudaCachedPinnedHostSlice<u64>,
        topk_ids: CudaCachedPinnedHostSlice<u32>,
        topk_dists: CudaCachedPinnedHostSlice<f32>,
        lune_witness_pivot_ranks: Option<CudaCachedPinnedHostSlice<u32>>,
        lune_witness_margins: Option<CudaCachedPinnedHostSlice<f32>>,
    }

    impl CudaPinnedPersistentOutputSlot {
        fn allocate(
            context: &Arc<CudaContext>,
            capacity: PersistentOutputCapacity,
        ) -> AnnResult<Self> {
            fn allocate_zeroed<T>(
                context: &Arc<CudaContext>,
                len: usize,
                label: &str,
            ) -> AnnResult<CudaCachedPinnedHostSlice<T>>
            where
                T: DeviceRepr + Copy + Default,
            {
                let mut pinned = CudaCachedPinnedHostSlice::<T>::allocate(context, len, label)?;
                pinned.as_mut_slice().fill(T::default());
                Ok(pinned)
            }

            let topk_len = capacity.max_leaf_rows.saturating_mul(capacity.k);
            Ok(Self {
                capacity,
                counters: allocate_zeroed(
                    context,
                    capacity.counter_words,
                    "persistent counter output",
                )?,
                row_ids: allocate_zeroed(
                    context,
                    capacity.max_leaf_rows,
                    "persistent row-id output",
                )?,
                leaf_starts: allocate_zeroed(
                    context,
                    capacity.max_leaf_count,
                    "persistent leaf-start output",
                )?,
                leaf_sizes: allocate_zeroed(
                    context,
                    capacity.max_leaf_count,
                    "persistent leaf-size output",
                )?,
                topk_ids: allocate_zeroed(context, topk_len, "persistent top-k id output")?,
                topk_dists: allocate_zeroed(context, topk_len, "persistent top-k distance output")?,
                lune_witness_pivot_ranks: capacity
                    .witness_enabled
                    .then(|| {
                        allocate_zeroed(context, topk_len, "persistent Lune witness pivot output")
                    })
                    .transpose()?,
                lune_witness_margins: capacity
                    .witness_enabled
                    .then(|| {
                        allocate_zeroed(context, topk_len, "persistent Lune witness margin output")
                    })
                    .transpose()?,
            })
        }
    }

