    fn persistent_profile_from_counter_header(
        ticket: &CudaPersistentLaunchTicket,
        counters: &[u64],
        last_gpu_completion_at: Instant,
        persistent_kernel_event_wall: Duration,
        persistent_total_wall: Duration,
    ) -> AnnResult<GpuSubtreeTopKProfile> {
        if counters.len() < GPU_QUEUE_COUNTER_WORDS {
            return Err(AnnError::log_index_error(format!(
                "CUDA persistent counter header is truncated: words={} expected={GPU_QUEUE_COUNTER_WORDS}",
                counters.len()
            )));
        }
        let overflow_flags = counters[7] as u32;
        let leaf_rows = counters[12] as usize;
        let leaf_count = counters[13] as usize;
        let persistent_leaf_row_amplification_x1000 = if ticket.resident_rows == 0 {
            0
        } else {
            leaf_rows.saturating_mul(1000) / ticket.resident_rows
        };
        let assignment_dco = GpuSubtreeAssignmentDcoTelemetry {
            nodes: counters[67] as usize,
            rows: counters[68] as usize,
            leader_pairs: counters[69] as usize,
            prefilter_pairs: counters[70] as usize,
            pruned_pairs: counters[71] as usize,
            survivor_pairs: counters[72] as usize,
            exact_pairs: counters[73] as usize,
            approx_output_pairs: counters[74] as usize,
            fallback_nodes: counters[75] as usize,
            overflow_nodes: counters[76] as usize,
            false_prune_audit_pairs: counters[77] as usize,
            false_prune_audit_misses: counters[78] as usize,
            metadata_bytes: 0,
            metadata_h2d_wall: Duration::ZERO,
        };
        let leaf_dco = GpuSubtreeLeafDcoTelemetry {
            leaf_count: counters[79] as usize,
            rows: counters[80] as usize,
            pair_count: counters[81] as usize,
            prefilter_pairs: counters[82] as usize,
            pruned_pairs: counters[83] as usize,
            survivor_pairs: counters[84] as usize,
            exact_pairs: counters[85] as usize,
            exact_stamp_pairs: counters[108] as usize,
            approx_output_pairs: counters[86] as usize,
            tile_prefilter_tiles: counters[87] as usize,
            tile_pruned_tiles: counters[88] as usize,
            tile_partial_tiles: counters[89] as usize,
            tile_full_exact_tiles: counters[90] as usize,
            exact_fallback_rows: counters[91] as usize,
            survivor_overflow_rows: counters[92] as usize,
            audit_only_pairs: counters[93] as usize,
            false_prune_audit_pairs: counters[94] as usize,
            false_prune_audit_misses: counters[95] as usize,
            metadata_bytes: 0,
            metadata_prepare_wall: Duration::ZERO,
            metadata_h2d_wall: Duration::ZERO,
            prefilter_clock_ticks: counters[96] as usize,
            exact_rerank_clock_ticks: counters[97] as usize,
            audit_clock_ticks: counters[98] as usize,
            tq_prefilter_clock_ticks: counters[126] as usize,
            tq_survivor_insert_clock_ticks: counters[127] as usize,
            tq_exact_rerank_clock_ticks: counters[128] as usize,
            tq_output_clock_ticks: counters[129] as usize,
            tile_started: counters[99] as usize,
            tile_done: counters[100] as usize,
            prefilter_row_started: counters[101] as usize,
            prefilter_row_done: counters[102] as usize,
            exact_rerank_row_started: counters[103] as usize,
            exact_rerank_row_done: counters[104] as usize,
            audit_row_started: counters[105] as usize,
            audit_row_done: counters[106] as usize,
            progress_heartbeat: counters[107] as usize,
            staged_tiles: counters[109] as usize,
            col_tasks_started: counters[110] as usize,
            col_tasks_done: counters[111] as usize,
            finalize_started: counters[112] as usize,
            finalize_done: counters[113] as usize,
            active_slots_max: counters[114] as usize,
            slot_wait_polls: counters[115] as usize,
            row_lock_spins: counters[116] as usize,
            staged_rows: counters[117] as usize,
            ..GpuSubtreeLeafDcoTelemetry::default()
        };
        let mut profile = GpuSubtreeTopKProfile {
            assignment_backend: ticket.params.gpu_subtree_assignment_backend,
            last_gpu_completion_at: Some(last_gpu_completion_at),
            persistent_attempt_count: 1,
            persistent_success_count: usize::from(overflow_flags == 0),
            persistent_fallback_count: 0,
            persistent_partition_worker_blocks: ticket.partition_worker_blocks,
            persistent_topk_worker_blocks: ticket.topk_worker_blocks,
            persistent_partition_pops: counters[8] as usize,
            persistent_leaf_pushes: counters[9] as usize,
            persistent_topk_pops: counters[10] as usize,
            persistent_partition_claims: counters[22] as usize,
            persistent_partition_empty_polls: counters[23] as usize,
            persistent_partition_frontier_end: counters[118] as usize,
            persistent_partition_level_rounds: counters[119] as usize,
            persistent_topk_claims: counters[24] as usize,
            persistent_topk_empty_polls: counters[25] as usize,
            persistent_done_cas_wins: counters[26] as usize,
            persistent_active_wait_cycles: counters[11] as usize,
            persistent_partition_busy_clocks: counters[120] as usize,
            persistent_partition_wait_clocks: counters[121] as usize,
            persistent_topk_busy_clocks: counters[122] as usize,
            persistent_topk_wait_clocks: counters[123] as usize,
            persistent_large_help_clocks: counters[124] as usize,
            persistent_topk_help_clocks: counters[125] as usize,
            persistent_partition_helped_topk_tiles: counters[63] as usize,
            persistent_topk_helped_large_tiles: counters[64] as usize,
            persistent_elastic_role_switches: counters[65] as usize,
            persistent_large_node_claims: counters[27] as usize,
            persistent_large_node_splits: counters[28] as usize,
            persistent_large_split_retries: counters[130] as usize,
            persistent_large_balanced_fallbacks: counters[131] as usize,
            persistent_large_node_rows: counters[29] as usize,
            persistent_large_node_max_rows: counters[30] as usize,
            persistent_large_node_empty_polls: counters[31] as usize,
            persistent_large_node_serialized_wait_cycles: counters[32] as usize,
            persistent_large_count_distance_clocks: counters[140] as usize,
            persistent_large_count_commit_clocks: counters[141] as usize,
            persistent_large_scatter_clocks: counters[142] as usize,
            persistent_large_publish_clocks: counters[143] as usize,
            persistent_large_ticket_batch_actual: ticket.launched_large_ticket_batch,
            persistent_large_ticket_range_claims: counters[144] as usize,
            persistent_large_physical_tiles: counters[145] as usize,
            persistent_large_sq8_dp4a_tiles: counters[146] as usize,
            persistent_large_sq8_wmma_tiles: counters[147] as usize,
            persistent_leaf_sq8_dp4a_tiles: counters[157] as usize,
            persistent_leaf_sq8_wmma_tiles: counters[158] as usize,
            persistent_leaf_row_owned_tasks: counters[148] as usize,
            persistent_leaf_staged_tasks: counters[149] as usize,
            persistent_leaf_score_clocks: counters[150] as usize,
            persistent_leaf_row_lock_merge_clocks: counters[151] as usize,
            persistent_topk_local_counter_flushes: counters[152] as usize,
            persistent_topk_idle_backoff_calls: counters[153] as usize,
            persistent_topk_idle_backoff_requested_ns: counters[154] as usize,
            persistent_topk_idle_leaf_resets: counters[155] as usize,
            persistent_topk_idle_large_resets: counters[156] as usize,
            persistent_queue_overflow_flags: overflow_flags,
            persistent_kernel_prepare_wall: ticket.persistent_kernel_prepare_wall,
            persistent_kernel_event_wall,
            persistent_total_wall,
            persistent_topk_rows: leaf_rows,
            persistent_leaf_count: leaf_count,
            persistent_effective_root_fanout: counters[17] as usize,
            persistent_effective_deeper_fanout: counters[18] as usize,
            persistent_fanout_assignment_slots: counters[19] as usize,
            persistent_replicated_rows: counters[20] as usize,
            persistent_unique_resident_rows: ticket.resident_rows,
            persistent_leaf_row_amplification_x1000,
            persistent_progress_epoch: counters[38] as usize,
            persistent_watchdog_last_epoch: counters[39] as usize,
            persistent_watchdog_stall_polls: counters[40] as usize,
            persistent_watchdog_trips: counters[41] as usize,
            persistent_active_work_ticks: counters[54] as usize,
            persistent_active_work_trips: counters[55] as usize,
            persistent_snapshot_partition_head: counters[42] as usize,
            persistent_snapshot_partition_tail: counters[43] as usize,
            persistent_snapshot_leaf_head: counters[44] as usize,
            persistent_snapshot_leaf_pushes: counters[45] as usize,
            persistent_snapshot_active_partition: counters[46] as usize,
            persistent_snapshot_active_topk: counters[47] as usize,
            persistent_snapshot_active_large: counters[132] as usize,
            persistent_snapshot_large_generation: counters[133] as usize,
            persistent_snapshot_large_phase: counters[134] as usize,
            persistent_snapshot_large_total_tiles: counters[135] as usize,
            persistent_snapshot_large_count_next: counters[136] as usize,
            persistent_snapshot_large_count_done: counters[137] as usize,
            persistent_snapshot_large_scatter_next: counters[138] as usize,
            persistent_snapshot_large_scatter_done: counters[139] as usize,
            persistent_snapshot_last_node_rows: counters[48] as usize,
            persistent_snapshot_last_node_depth: counters[49] as usize,
            persistent_snapshot_last_leaf_rows: counters[50] as usize,
            persistent_snapshot_large_lock: counters[51] as usize,
            persistent_snapshot_last_node_index: counters[52] as usize,
            persistent_snapshot_last_leaf_index: counters[53] as usize,
            persistent_leaf_size_min: if counters[36] == 0 {
                0
            } else {
                counters[33] as usize
            },
            persistent_leaf_size_max: counters[34] as usize,
            persistent_leaf_size_sum: counters[35] as usize,
            persistent_leaf_size_count: counters[36] as usize,
            persistent_leaf_target: ticket.plan.leaf_target,
            persistent_leaf_min: ticket.plan.leaf_min,
            persistent_leaf_max: ticket.effective_leaf_max,
            persistent_leaf_tile_rows: ticket.plan.leaf_tile_rows,
            resident_topk_kernel_event_wall: persistent_kernel_event_wall,
            workspace_peak_bytes: ticket.plan.required_bytes,
            workspace_budget_bytes: ticket.plan.budget_bytes,
            assignment_dco,
            leaf_dco,
            ..GpuSubtreeTopKProfile::default()
        };
        profile.refresh_aggregate_timings();
        Ok(profile)
    }

    struct CudaPersistentCopyMetadata {
        profile: GpuSubtreeTopKProfile,
        leaf_rows: usize,
        leaf_count: usize,
        leaf_task_count: usize,
        assignment_passes: usize,
        max_active_points: usize,
        k: usize,
        header_copy_wall: Duration,
        payload_event_wall: Duration,
        d2h_bytes: usize,
    }

    fn copy_persistent_output_to_pinned(
        copy_stream: &Arc<CudaStream>,
        job: &mut CudaPersistentCopyJob,
    ) -> AnnResult<CudaPersistentCopyMetadata> {
        let output = job.device_slot.as_ref().ok_or_else(|| {
            AnnError::log_index_error("CUDA persistent copy job lost its device slot".to_string())
        })?;
        let host = job.host_slot.as_mut().ok_or_else(|| {
            AnnError::log_index_error("CUDA persistent copy job lost its host slot".to_string())
        })?;
        copy_stream
            .wait(&job.ticket.kernel_end_event)
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "CUDA persistent copy stream wait for kernel failed: {err}"
                ))
            })?;

        let header_start_event = copy_stream
            .record_event(Some(sys::CUevent_flags::CU_EVENT_DEFAULT))
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to record CUDA persistent D2H header start event: {err}"
                ))
            })?;
        let counters = output.persistent_counters_dev.as_ref().ok_or_else(|| {
            AnnError::log_index_error(
                "CUDA persistent async output counter buffer is missing".to_string(),
            )
        })?;
        copy_stream
            .memcpy_dtoh(
                &counters.slice(0..GPU_QUEUE_COUNTER_WORDS),
                &mut host.counters,
            )
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to download CUDA persistent async counter header: {err}"
                ))
            })?;
        let header_end_event = copy_stream
            .record_event(Some(sys::CUevent_flags::CU_EVENT_DEFAULT))
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to record CUDA persistent D2H header end event: {err}"
                ))
            })?;
        header_end_event.synchronize().map_err(|err| {
            AnnError::log_index_error(format!(
                "Failed to wait for CUDA persistent D2H counter header: {err}"
            ))
        })?;
        let counters_host = host.counters.as_slice().to_vec();
        let header_copy_wall = cuda_event_elapsed_duration(&header_start_event, &header_end_event)?;
        let kernel_event_wall = cuda_event_elapsed_duration(
            &job.ticket.kernel_start_event,
            &job.ticket.kernel_end_event,
        )?;
        let mut profile = persistent_profile_from_counter_header(
            &job.ticket,
            &counters_host,
            Instant::now(),
            kernel_event_wall,
            job.ticket.total_start.elapsed(),
        )?;
        let overflow_flags = counters_host[7] as u32;
        if overflow_flags != 0 {
            return Err(AnnError::log_index_error(
                format_gpu_persistent_overflow_error(
                    job.ticket.resident_rows,
                    counters_host[14] as usize,
                    counters_host[15] as usize,
                    &profile,
                ),
            ));
        }
        if !job.ticket.download_outputs || job.ticket.partition_only {
            return Err(AnnError::log_index_error(
                "CUDA persistent async D2H accepts only fused output-producing tasks".to_string(),
            ));
        }

        let leaf_rows = counters_host[12] as usize;
        let leaf_count = counters_host[13] as usize;
        if leaf_rows > host.capacity.max_leaf_rows
            || leaf_count > host.capacity.max_leaf_count
            || job.ticket.k > host.capacity.k
        {
            return Err(AnnError::log_index_error(format!(
                "CUDA persistent async output exceeds admitted capacity: rows={leaf_rows}/{} leaves={leaf_count}/{} k={}/{}",
                host.capacity.max_leaf_rows,
                host.capacity.max_leaf_count,
                job.ticket.k,
                host.capacity.k,
            )));
        }
        let topk_len = leaf_rows.checked_mul(job.ticket.k).ok_or_else(|| {
            AnnError::log_index_error(format!(
                "CUDA persistent async top-k output length overflows: rows={leaf_rows} k={}",
                job.ticket.k
            ))
        })?;

        let payload_start_event = copy_stream
            .record_event(Some(sys::CUevent_flags::CU_EVENT_DEFAULT))
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to record CUDA persistent D2H payload start event: {err}"
                ))
            })?;
        copy_stream
            .memcpy_dtoh(
                &output
                    .row_ids_dev
                    .as_ref()
                    .ok_or_else(|| {
                        AnnError::log_index_error(
                            "CUDA persistent async row-id buffer is missing".to_string(),
                        )
                    })?
                    .slice(0..leaf_rows),
                &mut host.row_ids,
            )
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to download CUDA persistent async row ids: {err}"
                ))
            })?;
        copy_stream
            .memcpy_dtoh(
                &output
                    .leaf_starts_dev
                    .as_ref()
                    .ok_or_else(|| {
                        AnnError::log_index_error(
                            "CUDA persistent async leaf-start buffer is missing".to_string(),
                        )
                    })?
                    .slice(0..leaf_count),
                &mut host.leaf_starts,
            )
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to download CUDA persistent async leaf starts: {err}"
                ))
            })?;
        copy_stream
            .memcpy_dtoh(
                &output
                    .leaf_sizes_dev
                    .as_ref()
                    .ok_or_else(|| {
                        AnnError::log_index_error(
                            "CUDA persistent async leaf-size buffer is missing".to_string(),
                        )
                    })?
                    .slice(0..leaf_count),
                &mut host.leaf_sizes,
            )
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to download CUDA persistent async leaf sizes: {err}"
                ))
            })?;
        copy_stream
            .memcpy_dtoh(
                &output
                    .topk_ids_dev
                    .as_ref()
                    .ok_or_else(|| {
                        AnnError::log_index_error(
                            "CUDA persistent async top-k id buffer is missing".to_string(),
                        )
                    })?
                    .slice(0..topk_len),
                &mut host.topk_ids,
            )
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to download CUDA persistent async top-k ids: {err}"
                ))
            })?;
        copy_stream
            .memcpy_dtoh(
                &output
                    .topk_dists_dev
                    .as_ref()
                    .ok_or_else(|| {
                        AnnError::log_index_error(
                            "CUDA persistent async top-k distance buffer is missing".to_string(),
                        )
                    })?
                    .slice(0..topk_len),
                &mut host.topk_dists,
            )
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to download CUDA persistent async top-k distances: {err}"
                ))
            })?;
        if host.capacity.witness_enabled {
            let witness_ranks = output
                .lune_witness_pivot_ranks_dev
                .as_ref()
                .ok_or_else(|| {
                    AnnError::log_index_error(
                        "CUDA persistent async witness-rank buffer is missing".to_string(),
                    )
                })?;
            let witness_margins = output.lune_witness_margins_dev.as_ref().ok_or_else(|| {
                AnnError::log_index_error(
                    "CUDA persistent async witness-margin buffer is missing".to_string(),
                )
            })?;
            copy_stream
                .memcpy_dtoh(
                    &witness_ranks.slice(0..topk_len),
                    host.lune_witness_pivot_ranks.as_mut().ok_or_else(|| {
                        AnnError::log_index_error(
                            "CUDA persistent async pinned witness-rank buffer is missing"
                                .to_string(),
                        )
                    })?,
                )
                .map_err(|err| {
                    AnnError::log_index_error(format!(
                        "Failed to download CUDA persistent async witness ranks: {err}"
                    ))
                })?;
            copy_stream
                .memcpy_dtoh(
                    &witness_margins.slice(0..topk_len),
                    host.lune_witness_margins.as_mut().ok_or_else(|| {
                        AnnError::log_index_error(
                            "CUDA persistent async pinned witness-margin buffer is missing"
                                .to_string(),
                        )
                    })?,
                )
                .map_err(|err| {
                    AnnError::log_index_error(format!(
                        "Failed to download CUDA persistent async witness margins: {err}"
                    ))
                })?;
        }
        let payload_end_event = copy_stream
            .record_event(Some(sys::CUevent_flags::CU_EVENT_DEFAULT))
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to record CUDA persistent D2H payload end event: {err}"
                ))
            })?;
        payload_end_event.synchronize().map_err(|err| {
            AnnError::log_index_error(format!(
                "Failed to wait for CUDA persistent D2H payload: {err}"
            ))
        })?;
        let payload_event_wall =
            cuda_event_elapsed_duration(&payload_start_event, &payload_end_event)?;
        let last_gpu_completion_at = Instant::now();

        let row_ids = host.row_ids.as_slice();
        let leaf_starts = host.leaf_starts.as_slice();
        let leaf_sizes = host.leaf_sizes.as_slice();
        validate_persistent_leaf_topk_l2_batch_inputs(
            &row_ids[..leaf_rows],
            &leaf_starts[..leaf_count],
            &leaf_sizes[..leaf_count],
            leaf_rows,
            job.ticket.dim,
            job.ticket.resident_rows,
        )?;
        if leaf_count == 0 {
            profile.persistent_leaf_size_min = 0;
            profile.persistent_leaf_size_max = 0;
            profile.persistent_leaf_size_sum = 0;
            profile.persistent_leaf_size_count = 0;
        } else {
            profile.persistent_leaf_size_min =
                usize::try_from(leaf_sizes[..leaf_count].iter().copied().min().unwrap_or(0))
                    .map_err(|err| {
                        AnnError::log_index_error(format!(
                            "Invalid CUDA persistent async leaf size minimum: {err}"
                        ))
                    })?;
            profile.persistent_leaf_size_max =
                usize::try_from(leaf_sizes[..leaf_count].iter().copied().max().unwrap_or(0))
                    .map_err(|err| {
                        AnnError::log_index_error(format!(
                            "Invalid CUDA persistent async leaf size maximum: {err}"
                        ))
                    })?;
            profile.persistent_leaf_size_sum = leaf_rows;
            profile.persistent_leaf_size_count = leaf_count;
        }
        let d2h_bytes = leaf_rows
            .saturating_mul(std::mem::size_of::<u32>())
            .saturating_add(leaf_count.saturating_mul(2 * std::mem::size_of::<u64>()))
            .saturating_add(estimate_compact_topk_dtoh_bytes(leaf_rows, job.ticket.k))
            .saturating_add(GPU_QUEUE_COUNTER_WORDS.saturating_mul(std::mem::size_of::<u64>()))
            .saturating_add(usize::from(host.capacity.witness_enabled).saturating_mul(
                estimate_compact_lune_witness_dtoh_bytes(leaf_rows, job.ticket.k),
            ));
        profile.last_gpu_completion_at = Some(last_gpu_completion_at);
        profile.d2h_bytes = d2h_bytes;
        profile.topk_d2h_wall = payload_event_wall;
        profile.refresh_aggregate_timings();

        Ok(CudaPersistentCopyMetadata {
            profile,
            leaf_rows,
            leaf_count,
            leaf_task_count: counters_host[9] as usize,
            assignment_passes: counters_host[14] as usize,
            max_active_points: counters_host[15] as usize,
            k: job.ticket.k,
            header_copy_wall,
            payload_event_wall,
            d2h_bytes,
        })
    }

    impl CudaPersistentAsyncD2hSession {
        fn start(
            copy_stream: Arc<CudaStream>,
            capacity: PersistentOutputCapacity,
            max_input_rows: usize,
            dim: usize,
            padded_dim: usize,
            device_slots: [CudaPersistentOutputSlot; PERSISTENT_ASYNC_D2H_SLOT_COUNT],
            host_slots: [CudaPinnedPersistentOutputSlot; PERSISTENT_ASYNC_D2H_SLOT_COUNT],
            pinned_allocation_wall: Duration,
        ) -> AnnResult<Arc<Self>> {
            let (device_slot_tx, device_slot_rx) =
                mpsc::sync_channel(PERSISTENT_ASYNC_D2H_SLOT_COUNT);
            let (host_slot_tx, host_slot_rx) = mpsc::sync_channel(PERSISTENT_ASYNC_D2H_SLOT_COUNT);
            for slot in device_slots {
                device_slot_tx.send(slot).map_err(|_| {
                    AnnError::log_index_error(
                        "failed to initialize CUDA persistent device-slot ring".to_string(),
                    )
                })?;
            }
            for slot in host_slots {
                host_slot_tx.send(slot).map_err(|_| {
                    AnnError::log_index_error(
                        "failed to initialize CUDA persistent host-slot ring".to_string(),
                    )
                })?;
            }
            let (work_tx, work_rx) =
                mpsc::sync_channel::<CudaPersistentCopyJob>(PERSISTENT_ASYNC_D2H_SLOT_COUNT);
            let admission_profile = PersistentAsyncD2hProfile {
                requested: true,
                enabled: true,
                device_output_slots: PERSISTENT_ASYNC_D2H_SLOT_COUNT,
                device_output_slot_bytes: capacity.device_slot_bytes(),
                pinned_host_slots: PERSISTENT_ASYNC_D2H_SLOT_COUNT,
                pinned_host_slot_bytes: capacity.pinned_host_slot_bytes(),
                pinned_allocation_wall,
                ..PersistentAsyncD2hProfile::default()
            };
            let profile = Arc::new(Mutex::new(PersistentAsyncD2hProfile {
                requested: true,
                enabled: true,
                ..PersistentAsyncD2hProfile::default()
            }));
            let failure = Arc::new(Mutex::new(None::<String>));
            let worker_device_tx = device_slot_tx.clone();
            let worker_host_tx = host_slot_tx.clone();
            let worker_profile = Arc::clone(&profile);
            let worker_failure = Arc::clone(&failure);
            let worker = std::thread::Builder::new()
                .name("pipnn-persistent-d2h".to_string())
                .spawn(move || {
                    while let Ok(mut job) = work_rx.recv() {
                        if let Some(message) = worker_failure.lock().clone() {
                            let _ = job.ticket.kernel_end_event.synchronize();
                            if let Some(slot) = job.device_slot.take() {
                                let _ = worker_device_tx.send(slot);
                            }
                            if let Some(slot) = job.host_slot.take() {
                                let _ = worker_host_tx.send(slot);
                            }
                            let _ = job.completion_tx.send(Err(AnnError::log_index_error(
                                format!(
                                    "CUDA persistent async D2H sequence {} cancelled after prior failure: {message}",
                                    job.sequence
                                ),
                            )));
                            continue;
                        }

                        match copy_persistent_output_to_pinned(&copy_stream, &mut job) {
                            Ok(metadata) => {
                                if let Some(slot) = job.device_slot.take() {
                                    if worker_device_tx.send(slot).is_err() {
                                        let message =
                                            "CUDA persistent device-slot ring disconnected"
                                                .to_string();
                                        *worker_failure.lock() = Some(message.clone());
                                        let _ = job.completion_tx.send(Err(
                                            AnnError::log_index_error(message),
                                        ));
                                        continue;
                                    }
                                }
                                {
                                    let mut aggregate = worker_profile.lock();
                                    aggregate.header_copy_wall += metadata.header_copy_wall;
                                    aggregate.payload_event_wall += metadata.payload_event_wall;
                                    aggregate.d2h_bytes =
                                        aggregate.d2h_bytes.saturating_add(metadata.d2h_bytes);
                                }
                                let completion = CudaPersistentCopyCompletion {
                                    host_slot: job
                                        .host_slot
                                        .take()
                                        .expect("successful CUDA copy retains its host slot"),
                                    profile: metadata.profile,
                                    leaf_rows: metadata.leaf_rows,
                                    leaf_count: metadata.leaf_count,
                                    _leaf_task_count: metadata.leaf_task_count,
                                    assignment_passes: metadata.assignment_passes,
                                    max_active_points: metadata.max_active_points,
                                    k: metadata.k,
                                };
                                match job.completion_tx.send(Ok(completion)) {
                                    Ok(()) => {}
                                    Err(send_error) => {
                                        if let Ok(completion) = send_error.0 {
                                            let _ = worker_host_tx.send(completion.host_slot);
                                        }
                                    }
                                }
                            }
                            Err(err) => {
                                let message = err.to_string();
                                // A payload copy may have been enqueued before a later
                                // submission failed. Drain the copy stream before either
                                // page-locked or device storage can be recycled.
                                let _ = copy_stream.synchronize();
                                let _ = job.ticket.kernel_end_event.synchronize();
                                if let Some(slot) = job.device_slot.take() {
                                    let _ = worker_device_tx.send(slot);
                                }
                                if let Some(slot) = job.host_slot.take() {
                                    let _ = worker_host_tx.send(slot);
                                }
                                let mut failure = worker_failure.lock();
                                if failure.is_none() {
                                    *failure = Some(message);
                                }
                                let _ = job.completion_tx.send(Err(err));
                            }
                        }
                    }
                })
                .map_err(|err| {
                    AnnError::log_index_error(format!(
                        "failed to start CUDA persistent D2H worker: {err}"
                    ))
                })?;
            Ok(Arc::new(Self {
                capacity,
                max_input_rows,
                dim,
                padded_dim,
                device_slot_rx: Mutex::new(device_slot_rx),
                device_slot_tx,
                host_slot_rx: Mutex::new(host_slot_rx),
                host_slot_tx,
                work_tx: Mutex::new(Some(work_tx)),
                worker: Mutex::new(Some(worker)),
                next_sequence: AtomicUsize::new(0),
                admission_profile,
                profile,
                failure,
            }))
        }

        fn failure_error(&self) -> Option<AnnError> {
            self.failure.lock().as_ref().map(|message| {
                AnnError::log_index_error(format!(
                    "CUDA persistent async D2H session failed: {message}"
                ))
            })
        }

        fn acquire_slots(&self) -> AnnResult<CudaPersistentSlotPair> {
            if let Some(err) = self.failure_error() {
                return Err(err);
            }
            let device_wait_start = Instant::now();
            let device_slot = loop {
                if let Some(err) = self.failure_error() {
                    return Err(err);
                }
                match self
                    .device_slot_rx
                    .lock()
                    .recv_timeout(Duration::from_millis(50))
                {
                    Ok(slot) => break slot,
                    Err(mpsc::RecvTimeoutError::Timeout) => continue,
                    Err(mpsc::RecvTimeoutError::Disconnected) => {
                        return Err(AnnError::log_index_error(
                            "CUDA persistent device-slot ring disconnected".to_string(),
                        ));
                    }
                }
            };
            self.profile.lock().device_slot_wait_wall += device_wait_start.elapsed();

            let host_wait_start = Instant::now();
            let host_slot = loop {
                if let Some(err) = self.failure_error() {
                    let _ = self.device_slot_tx.send(device_slot);
                    return Err(err);
                }
                match self
                    .host_slot_rx
                    .lock()
                    .recv_timeout(Duration::from_millis(50))
                {
                    Ok(slot) => break slot,
                    Err(mpsc::RecvTimeoutError::Timeout) => continue,
                    Err(mpsc::RecvTimeoutError::Disconnected) => {
                        let _ = self.device_slot_tx.send(device_slot);
                        return Err(AnnError::log_index_error(
                            "CUDA persistent host-slot ring disconnected".to_string(),
                        ));
                    }
                }
            };
            self.profile.lock().host_slot_wait_wall += host_wait_start.elapsed();

            Ok(CudaPersistentSlotPair {
                sequence: self.next_sequence.fetch_add(1, Ordering::Relaxed),
                device_slot,
                host_slot,
            })
        }

        fn return_slots(&self, slots: CudaPersistentSlotPair) {
            let _ = self.device_slot_tx.send(slots.device_slot);
            let _ = self.host_slot_tx.send(slots.host_slot);
        }

        fn enqueue(
            &self,
            slots: CudaPersistentSlotPair,
            ticket: CudaPersistentLaunchTicket,
        ) -> AnnResult<mpsc::Receiver<AnnResult<CudaPersistentCopyCompletion>>> {
            if let Some(err) = self.failure_error() {
                self.return_slots(slots);
                return Err(err);
            }
            let work_tx = match self.work_tx.lock().as_ref().cloned() {
                Some(work_tx) => work_tx,
                None => {
                    let synchronize_error = ticket.kernel_end_event.synchronize().err();
                    self.return_slots(slots);
                    return Err(AnnError::log_index_error(synchronize_error.map_or_else(
                        || "CUDA persistent async D2H session is already closed".to_string(),
                        |err| {
                            format!(
                                "CUDA persistent async D2H session is already closed and kernel completion wait failed: {err}"
                            )
                        },
                    )));
                }
            };
            let (completion_tx, completion_rx) = mpsc::sync_channel(1);
            let job = CudaPersistentCopyJob {
                sequence: slots.sequence,
                ticket,
                device_slot: Some(slots.device_slot),
                host_slot: Some(slots.host_slot),
                completion_tx,
            };
            if let Err(send_error) = work_tx.send(job) {
                let mut job = send_error.0;
                let synchronize_error = job.ticket.kernel_end_event.synchronize().err();
                if let Some(slot) = job.device_slot.take() {
                    let _ = self.device_slot_tx.send(slot);
                }
                if let Some(slot) = job.host_slot.take() {
                    let _ = self.host_slot_tx.send(slot);
                }
                let message = synchronize_error.map_or_else(
                    || "CUDA persistent async D2H worker disconnected".to_string(),
                    |err| {
                        format!(
                            "CUDA persistent async D2H worker disconnected and kernel completion wait failed: {err}"
                        )
                    },
                );
                let mut failure = self.failure.lock();
                if failure.is_none() {
                    *failure = Some(message.clone());
                }
                return Err(AnnError::log_index_error(message));
            }
            Ok(completion_rx)
        }

        fn finish(&self) -> AnnResult<PersistentAsyncD2hProfile> {
            let drain_start = Instant::now();
            self.work_tx.lock().take();
            if let Some(worker) = self.worker.lock().take()
                && worker.join().is_err()
            {
                return Err(AnnError::log_index_error(
                    "CUDA persistent async D2H worker panicked".to_string(),
                ));
            }
            let mut profile = self.profile.lock().clone();
            profile.final_drain_wall += drain_start.elapsed();
            if let Some(err) = self.failure_error() {
                return Err(err);
            }
            Ok(profile)
        }
    }

