        fn refresh_persistent_subtree_compile_environment(
            &mut self,
            scheduler_mode: PiPNNGpuSubtreePersistentSchedulerMode,
        ) -> PersistentSubtreeCompileEnvironment {
            let current = PersistentSubtreeCompileEnvironment::current(scheduler_mode);
            if self.persistent_subtree_compile_environment != Some(current) {
                self.clear_persistent_subtree_function_cache();
                self.persistent_subtree_compile_environment = Some(current);
            }
            current
        }

        fn persistent_subtree_function(
            &mut self,
            wmma_diagnostics_enabled: bool,
            wmma_exec_diagnostics_enabled: bool,
            wmma_cta_shared_b_enabled: bool,
            leaf_wmma_topk_enabled: bool,
            assignment_dco_source_enabled: bool,
            leaf_dco_source_enabled: bool,
            leaf_sq_int8_wmma_source_enabled: bool,
            leaf_sq_int4_wmma_source_enabled: bool,
            leaf_sq_int8_scalar_diagnostic_source_enabled: bool,
            scheduler_mode: PiPNNGpuSubtreePersistentSchedulerMode,
        ) -> AnnResult<(Arc<CudaFunction>, GpuKernelCaps)> {
            let compile_environment =
                self.refresh_persistent_subtree_compile_environment(scheduler_mode);
            let compile_specialization = persistent_compile_specialization(
                wmma_diagnostics_enabled,
                wmma_exec_diagnostics_enabled,
                wmma_cta_shared_b_enabled,
                leaf_wmma_topk_enabled,
                assignment_dco_source_enabled,
                leaf_dco_source_enabled,
                leaf_sq_int8_wmma_source_enabled,
                leaf_sq_int4_wmma_source_enabled,
                leaf_sq_int8_scalar_diagnostic_source_enabled,
                compile_environment,
            );
            let nvrtc_arch = persistent_subtree_nvrtc_arch(&self.stream)?;
            let nvrtc_arch_label = nvrtc_arch.unwrap_or("nvrtc_default");
            // Leaf WMMA top-k is an opt-in diagnostic path. The default cached
            // persistent functions compile with that subpath disabled. Assignment
            // DCO is also compiled out by default so no-DCO runs keep the original
            // WMMA source shape.
            if self.persistent_subtree_leaf_wmma_topk_enabled != Some(leaf_wmma_topk_enabled)
                || self.persistent_subtree_assignment_dco_source_enabled
                    != Some(assignment_dco_source_enabled)
                || self.persistent_subtree_leaf_dco_source_enabled != Some(leaf_dco_source_enabled)
                || self.persistent_subtree_leaf_sq_int8_wmma_source_enabled
                    != Some(leaf_sq_int8_wmma_source_enabled)
                || self.persistent_subtree_leaf_sq_int4_wmma_source_enabled
                    != Some(leaf_sq_int4_wmma_source_enabled)
                || self.persistent_subtree_leaf_sq_int8_scalar_diagnostic_source_enabled
                    != Some(leaf_sq_int8_scalar_diagnostic_source_enabled)
            {
                self.clear_persistent_subtree_function_cache();
                self.persistent_subtree_leaf_wmma_topk_enabled = Some(leaf_wmma_topk_enabled);
                self.persistent_subtree_assignment_dco_source_enabled =
                    Some(assignment_dco_source_enabled);
                self.persistent_subtree_leaf_dco_source_enabled = Some(leaf_dco_source_enabled);
                self.persistent_subtree_leaf_sq_int8_wmma_source_enabled =
                    Some(leaf_sq_int8_wmma_source_enabled);
                self.persistent_subtree_leaf_sq_int4_wmma_source_enabled =
                    Some(leaf_sq_int4_wmma_source_enabled);
                self.persistent_subtree_leaf_sq_int8_scalar_diagnostic_source_enabled =
                    Some(leaf_sq_int8_scalar_diagnostic_source_enabled);
            }
            let needs_compile = match (
                wmma_cta_shared_b_enabled,
                wmma_diagnostics_enabled,
                wmma_exec_diagnostics_enabled,
            ) {
                (false, false, false) => self.persistent_subtree_function_default.is_none(),
                (false, true, false) => self.persistent_subtree_function_wmma_diag.is_none(),
                (false, false, true) => self.persistent_subtree_function_wmma_exec_diag.is_none(),
                (false, true, true) => self
                    .persistent_subtree_function_wmma_shape_exec_diag
                    .is_none(),
                (true, false, false) => self.persistent_subtree_function_cta_b_default.is_none(),
                (true, true, false) => self.persistent_subtree_function_cta_b_wmma_diag.is_none(),
                (true, false, true) => self
                    .persistent_subtree_function_cta_b_wmma_exec_diag
                    .is_none(),
                (true, true, true) => self
                    .persistent_subtree_function_cta_b_wmma_shape_exec_diag
                    .is_none(),
            };
            if needs_compile {
                let func = Arc::new(Self::load_persistent_subtree_function(
                    &self.stream,
                    nvrtc_arch,
                    wmma_diagnostics_enabled,
                    wmma_exec_diagnostics_enabled,
                    wmma_cta_shared_b_enabled,
                    leaf_wmma_topk_enabled,
                    assignment_dco_source_enabled,
                    leaf_dco_source_enabled,
                    leaf_sq_int8_wmma_source_enabled,
                    leaf_sq_int4_wmma_source_enabled,
                    leaf_sq_int8_scalar_diagnostic_source_enabled,
                    compile_environment,
                )?);
                let caps = query_gpu_kernel_caps(
                    func.as_ref(),
                    &self.hardware_adaptation_profile.device,
                    "gpu_persistent_subtree_topk",
                    nvrtc_arch_label,
                    compile_specialization.clone(),
                    256,
                    0,
                )?;
                self.hardware_adaptation_profile.upsert_kernel_caps(caps);
                match (
                    wmma_cta_shared_b_enabled,
                    wmma_diagnostics_enabled,
                    wmma_exec_diagnostics_enabled,
                ) {
                    (false, false, false) => self.persistent_subtree_function_default = Some(func),
                    (false, true, false) => self.persistent_subtree_function_wmma_diag = Some(func),
                    (false, false, true) => {
                        self.persistent_subtree_function_wmma_exec_diag = Some(func)
                    }
                    (false, true, true) => {
                        self.persistent_subtree_function_wmma_shape_exec_diag = Some(func)
                    }
                    (true, false, false) => {
                        self.persistent_subtree_function_cta_b_default = Some(func)
                    }
                    (true, true, false) => {
                        self.persistent_subtree_function_cta_b_wmma_diag = Some(func)
                    }
                    (true, false, true) => {
                        self.persistent_subtree_function_cta_b_wmma_exec_diag = Some(func)
                    }
                    (true, true, true) => {
                        self.persistent_subtree_function_cta_b_wmma_shape_exec_diag = Some(func)
                    }
                }
            }

            let slot = match (
                wmma_cta_shared_b_enabled,
                wmma_diagnostics_enabled,
                wmma_exec_diagnostics_enabled,
            ) {
                (false, false, false) => &self.persistent_subtree_function_default,
                (false, true, false) => &self.persistent_subtree_function_wmma_diag,
                (false, false, true) => &self.persistent_subtree_function_wmma_exec_diag,
                (false, true, true) => &self.persistent_subtree_function_wmma_shape_exec_diag,
                (true, false, false) => &self.persistent_subtree_function_cta_b_default,
                (true, true, false) => &self.persistent_subtree_function_cta_b_wmma_diag,
                (true, false, true) => &self.persistent_subtree_function_cta_b_wmma_exec_diag,
                (true, true, true) => &self.persistent_subtree_function_cta_b_wmma_shape_exec_diag,
            };
            let function = slot
                .as_ref()
                .expect("CUDA persistent subtree function initialized")
                .clone();
            let kernel_source_hash = persistent_kernel_source_hash();
            let caps = self
                .hardware_adaptation_profile
                .kernel_caps
                .iter()
                .find(|caps| {
                    caps.entrypoint == "gpu_persistent_subtree_topk"
                        && caps.kernel_source_hash == kernel_source_hash
                        && caps.nvrtc_arch == nvrtc_arch_label
                        && caps.compile_specialization == compile_specialization
                        && caps.block_threads == 256
                        && caps.dynamic_shared_bytes == 0
                })
                .cloned()
                .ok_or_else(|| {
                    AnnError::log_index_error(format!(
                        "Missing recorded gpu_persistent_subtree_topk capabilities at 256 threads for {nvrtc_arch_label} specialization {compile_specialization}"
                    ))
                })?;
            Ok((function, caps))
        }

        fn persistent_multileaf_replay_function(
            &mut self,
            wmma_cta_shared_b_enabled: bool,
        ) -> AnnResult<Arc<CudaFunction>> {
            let compile_environment = self.refresh_persistent_subtree_compile_environment(
                PiPNNGpuSubtreePersistentSchedulerMode::Baseline,
            );
            let leaf_wmma_topk_enabled = persistent_leaf_wmma_topk_enabled();
            if self.persistent_multileaf_replay_leaf_wmma_topk_enabled
                != Some(leaf_wmma_topk_enabled)
            {
                self.persistent_multileaf_replay_function_default = None;
                self.persistent_multileaf_replay_function_cta_b = None;
                self.persistent_multileaf_replay_leaf_wmma_topk_enabled =
                    Some(leaf_wmma_topk_enabled);
            }
            let slot = if wmma_cta_shared_b_enabled {
                &mut self.persistent_multileaf_replay_function_cta_b
            } else {
                &mut self.persistent_multileaf_replay_function_default
            };
            if slot.is_none() {
                *slot = Some(Arc::new(Self::load_persistent_subtree_named_function(
                    &self.stream,
                    false,
                    false,
                    wmma_cta_shared_b_enabled,
                    leaf_wmma_topk_enabled,
                    false,
                    false,
                    false,
                    false,
                    false,
                    compile_environment,
                    "gpu_persistent_subtree_topk_multileaf_replay",
                )?));
            }
            Ok(slot
                .as_ref()
                .expect("CUDA persistent multi-leaf replay function initialized")
                .clone())
        }

        fn persistent_topk_only_function(
            &mut self,
            wmma_diagnostics_enabled: bool,
            wmma_exec_diagnostics_enabled: bool,
            wmma_cta_shared_b_enabled: bool,
            leaf_wmma_topk_enabled: bool,
            leaf_dco_source_enabled: bool,
            leaf_sq_int8_wmma_source_enabled: bool,
            leaf_sq_int4_wmma_source_enabled: bool,
            leaf_sq_int8_scalar_diagnostic_source_enabled: bool,
        ) -> AnnResult<Arc<CudaFunction>> {
            let compile_environment = self.refresh_persistent_subtree_compile_environment(
                PiPNNGpuSubtreePersistentSchedulerMode::Baseline,
            );
            let key = (
                wmma_diagnostics_enabled,
                wmma_exec_diagnostics_enabled,
                wmma_cta_shared_b_enabled,
                leaf_wmma_topk_enabled,
                leaf_dco_source_enabled,
                leaf_sq_int8_wmma_source_enabled,
                leaf_sq_int4_wmma_source_enabled,
                leaf_sq_int8_scalar_diagnostic_source_enabled,
            );
            if self.persistent_topk_only_function_key != Some(key) {
                self.persistent_topk_only_function = None;
                self.persistent_topk_only_function_key = Some(key);
            }
            if self.persistent_topk_only_function.is_none() {
                self.persistent_topk_only_function =
                    Some(Arc::new(Self::load_persistent_subtree_named_function(
                        &self.stream,
                        wmma_diagnostics_enabled,
                        wmma_exec_diagnostics_enabled,
                        wmma_cta_shared_b_enabled,
                        leaf_wmma_topk_enabled,
                        false,
                        leaf_dco_source_enabled,
                        leaf_sq_int8_wmma_source_enabled,
                        leaf_sq_int4_wmma_source_enabled,
                        leaf_sq_int8_scalar_diagnostic_source_enabled,
                        compile_environment,
                        "gpu_persistent_subtree_topk_only",
                    )?));
            }
            Ok(self
                .persistent_topk_only_function
                .as_ref()
                .expect("CUDA persistent top-k-only function initialized")
                .clone())
        }

        fn clear_persistent_subtree_function_cache(&mut self) {
            self.persistent_subtree_function_default = None;
            self.persistent_subtree_function_wmma_diag = None;
            self.persistent_subtree_function_wmma_exec_diag = None;
            self.persistent_subtree_function_wmma_shape_exec_diag = None;
            self.persistent_subtree_function_cta_b_default = None;
            self.persistent_subtree_function_cta_b_wmma_diag = None;
            self.persistent_subtree_function_cta_b_wmma_exec_diag = None;
            self.persistent_subtree_function_cta_b_wmma_shape_exec_diag = None;
            self.persistent_topk_only_function = None;
            self.persistent_topk_only_function_key = None;
            self.persistent_multileaf_replay_function_default = None;
            self.persistent_multileaf_replay_function_cta_b = None;
            self.persistent_multileaf_replay_leaf_wmma_topk_enabled = None;
        }

        fn load_persistent_subtree_function(
            stream: &Arc<CudaStream>,
            arch: Option<&'static str>,
            wmma_diagnostics_enabled: bool,
            wmma_exec_diagnostics_enabled: bool,
            wmma_cta_shared_b_enabled: bool,
            leaf_wmma_topk_enabled: bool,
            assignment_dco_source_enabled: bool,
            leaf_dco_source_enabled: bool,
            leaf_sq_int8_wmma_source_enabled: bool,
            leaf_sq_int4_wmma_source_enabled: bool,
            leaf_sq_int8_scalar_diagnostic_source_enabled: bool,
            compile_environment: PersistentSubtreeCompileEnvironment,
        ) -> AnnResult<CudaFunction> {
            Self::load_persistent_subtree_named_function_with_arch(
                stream,
                arch,
                wmma_diagnostics_enabled,
                wmma_exec_diagnostics_enabled,
                wmma_cta_shared_b_enabled,
                leaf_wmma_topk_enabled,
                assignment_dco_source_enabled,
                leaf_dco_source_enabled,
                leaf_sq_int8_wmma_source_enabled,
                leaf_sq_int4_wmma_source_enabled,
                leaf_sq_int8_scalar_diagnostic_source_enabled,
                compile_environment,
                "gpu_persistent_subtree_topk",
            )
        }

        fn load_persistent_subtree_named_function(
            stream: &Arc<CudaStream>,
            wmma_diagnostics_enabled: bool,
            wmma_exec_diagnostics_enabled: bool,
            wmma_cta_shared_b_enabled: bool,
            leaf_wmma_topk_enabled: bool,
            assignment_dco_source_enabled: bool,
            leaf_dco_source_enabled: bool,
            leaf_sq_int8_wmma_source_enabled: bool,
            leaf_sq_int4_wmma_source_enabled: bool,
            _leaf_sq_int8_scalar_diagnostic_source_enabled: bool,
            compile_environment: PersistentSubtreeCompileEnvironment,
            function_name: &str,
        ) -> AnnResult<CudaFunction> {
            let arch = persistent_subtree_nvrtc_arch(stream)?;
            Self::load_persistent_subtree_named_function_with_arch(
                stream,
                arch,
                wmma_diagnostics_enabled,
                wmma_exec_diagnostics_enabled,
                wmma_cta_shared_b_enabled,
                leaf_wmma_topk_enabled,
                assignment_dco_source_enabled,
                leaf_dco_source_enabled,
                leaf_sq_int8_wmma_source_enabled,
                leaf_sq_int4_wmma_source_enabled,
                _leaf_sq_int8_scalar_diagnostic_source_enabled,
                compile_environment,
                function_name,
            )
        }

        fn load_persistent_subtree_named_function_with_arch(
            stream: &Arc<CudaStream>,
            arch: Option<&'static str>,
            wmma_diagnostics_enabled: bool,
            wmma_exec_diagnostics_enabled: bool,
            wmma_cta_shared_b_enabled: bool,
            leaf_wmma_topk_enabled: bool,
            assignment_dco_source_enabled: bool,
            leaf_dco_source_enabled: bool,
            leaf_sq_int8_wmma_source_enabled: bool,
            leaf_sq_int4_wmma_source_enabled: bool,
            _leaf_sq_int8_scalar_diagnostic_source_enabled: bool,
            compile_environment: PersistentSubtreeCompileEnvironment,
            function_name: &str,
        ) -> AnnResult<CudaFunction> {
            let mut options = vec!["--std=c++17".to_string()];
            if wmma_diagnostics_enabled {
                options.push("-DGPU_PERSISTENT_TOPK_WMMA_DIAGNOSTICS=1".to_string());
            }
            if wmma_exec_diagnostics_enabled {
                options.push("-DGPU_PERSISTENT_TOPK_WMMA_EXEC_DIAGNOSTICS=1".to_string());
            }
            if wmma_cta_shared_b_enabled {
                options.push("-DGPU_PERSISTENT_TOPK_WMMA_CTA_SHARED_B=1".to_string());
            }
            if leaf_wmma_topk_enabled {
                options.push("-DGPU_PERSISTENT_TOPK_WMMA_ENABLE_TOPK=1".to_string());
            }
            let wmma_debug_abort_after_tile_calls =
                compile_environment.wmma_debug_abort_after_tile_calls;
            if wmma_debug_abort_after_tile_calls > 0 {
                options.push(format!(
                    "-DGPU_PERSISTENT_TOPK_WMMA_DEBUG_ABORT_AFTER_TILE_CALLS={wmma_debug_abort_after_tile_calls}"
                ));
            }
            let wmma_debug_abort_after_k_slices =
                compile_environment.wmma_debug_abort_after_k_slices;
            if wmma_debug_abort_after_k_slices > 0 {
                options.push(format!(
                    "-DGPU_PERSISTENT_TOPK_WMMA_DEBUG_ABORT_AFTER_K_SLICES={wmma_debug_abort_after_k_slices}"
                ));
            }
            let wmma_debug_abort_after_topk_claims =
                compile_environment.wmma_debug_abort_after_topk_claims;
            if wmma_debug_abort_after_topk_claims > 0 {
                options.push(format!(
                    "-DGPU_PERSISTENT_TOPK_WMMA_DEBUG_ABORT_AFTER_TOPK_CLAIMS={wmma_debug_abort_after_topk_claims}"
                ));
            }
            if compile_environment.disable_topk_help_large {
                options.push("-DGPU_PERSISTENT_DISABLE_TOPK_HELP_LARGE=1".to_string());
            }
            match compile_environment.scheduler_mode {
                PiPNNGpuSubtreePersistentSchedulerMode::Baseline => {}
                PiPNNGpuSubtreePersistentSchedulerMode::LocalCounters => {
                    options.push("-DGPU_PERSISTENT_TOPK_LOCAL_COUNTERS=1".to_string());
                }
                PiPNNGpuSubtreePersistentSchedulerMode::LocalCountersBarrier => {
                    options.push("-DGPU_PERSISTENT_TOPK_LOCAL_COUNTERS=1".to_string());
                    options.push("-DGPU_PERSISTENT_TOPK_BARRIER_CLEANUP=1".to_string());
                }
                PiPNNGpuSubtreePersistentSchedulerMode::AdaptiveIdle => {
                    options.push("-DGPU_PERSISTENT_TOPK_LOCAL_COUNTERS=1".to_string());
                    options.push("-DGPU_PERSISTENT_TOPK_BARRIER_CLEANUP=1".to_string());
                    options.push("-DGPU_PERSISTENT_TOPK_IDLE_BACKOFF=1".to_string());
                }
                PiPNNGpuSubtreePersistentSchedulerMode::Auto => {
                    unreachable!("auto scheduler mode must resolve before NVRTC compilation")
                }
            }
            if assignment_dco_source_enabled {
                options.push("-DGPU_PERSISTENT_ASSIGNMENT_DCO_ENABLE=1".to_string());
            }
            if leaf_dco_source_enabled {
                options.push("-DGPU_PERSISTENT_LEAF_DCO_ENABLE=1".to_string());
            }
            if leaf_sq_int8_wmma_source_enabled {
                options.push("-DGPU_PERSISTENT_LEAF_SQ_INT8_WMMA_ENABLE=1".to_string());
            }
            if leaf_sq_int4_wmma_source_enabled {
                options.push("-DGPU_PERSISTENT_LEAF_SQ_INT4_WMMA_ENABLE=1".to_string());
            }
            let ptx = compile_ptx_with_opts(
                GPU_PERSISTENT_SUBTREE_KERNEL_SRC,
                CompileOptions {
                    arch,
                    include_paths: persistent_subtree_nvrtc_include_paths(),
                    options,
                    ..CompileOptions::default()
                },
            )
            .map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to compile CUDA persistent subtree kernel: {err}"
                ))
            })?;
            let module = stream.context().load_module(ptx).map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to load CUDA persistent subtree kernel: {err}"
                ))
            })?;
            module.load_function(function_name).map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to load CUDA persistent subtree function {function_name}: {err}"
                ))
            })
        }

        fn load_compact_topk_function(stream: &Arc<CudaStream>) -> AnnResult<CudaFunction> {
            let ptx = compile_ptx(COMPACT_TOPK_KERNEL_SRC).map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to compile CUDA compact top-k kernel with NVRTC: {err}"
                ))
            })?;
            let module = stream.context().load_module(ptx).map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to load CUDA compact top-k module: {err}"
                ))
            })?;
            module.load_function("leaf_l2_compact_topk").map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to load CUDA compact top-k function: {err}"
                ))
            })
        }

