        #[cfg(test)]
        pub(super) fn debug_run_quantized_partition_only_for_test(
            &self,
            request: &GpuSubtreePartitionRequest<'_>,
            quantized: GpuSubtreeQuantizedInput<'_>,
            params: &PiPNNParams,
        ) -> AnnResult<GpuSubtreeTopKResult> {
            let result = (|| {
                let mut engine = self.engine.lock();
                engine.release_compact_workspace()?;
                let (
                    _subtree_global_ids_h2d_wall,
                    _subtree_norms_h2d_wall,
                    _rabitq_plus_h2d_wall,
                    resident_metadata_h2d_bytes,
                    rabitq_plus_code_bytes,
                ) = engine.upload_quantized_resident_subtree(quantized)?;
                let resident_h2d_bytes =
                    resident_metadata_h2d_bytes.saturating_add(rabitq_plus_code_bytes);
                let (device_free_bytes, _device_total_bytes) =
                    engine.device_memory_info_after_sync()?;
                let persistent_plan = annotate_gpu_persistent_subtree_resident_diagnostics(
                    plan_gpu_persistent_subtree(
                        quantized.global_ids.len(),
                        params.leaf_knn,
                        gpu_persistent_subtree_max_leaders_per_node(params),
                        params.fanout_second.max(1),
                        Some(params.effective_gpu_workspace_budget_bytes()),
                        params,
                    ),
                    quantized.global_ids.len(),
                    quantized.dim,
                    params,
                    Some(device_free_bytes.saturating_add(resident_h2d_bytes)),
                );
                if !persistent_plan.supported {
                    return Err(AnnError::log_index_error(
                        format_gpu_persistent_unsupported_error(
                            quantized.global_ids.len(),
                            params,
                            &persistent_plan,
                        ),
                    ));
                }
                let persistent = engine.run_persistent_subtree_topk(
                    request,
                    params,
                    quantized.dim,
                    persistent_plan,
                    true,
                )?;
                if !gpu_persistent_result_succeeded(&persistent.profile) {
                    return Err(AnnError::log_index_error(
                        format_gpu_persistent_overflow_error(
                            quantized.global_ids.len(),
                            persistent.assignment_passes,
                            persistent.max_active_points,
                            &persistent.profile,
                        ),
                    ));
                }
                Ok(GpuSubtreeTopKResult {
                    compact_batches: Vec::new(),
                    assignment_passes: persistent.assignment_passes,
                    leaf_count: persistent.leaf_sizes.len(),
                    max_active_points: persistent.max_active_points,
                    profile: persistent.profile,
                })
            })();
            self.release_subtree_workspace_after(result)
        }

