    fn persistent_subtree_topk_kernel_source(source: &str) -> &str {
        source
            .split("extern \"C\" __global__ void gpu_persistent_subtree_topk(")
            .nth(1)
            .and_then(|tail| tail.split("\n\"#;").next())
            .expect("persistent subtree kernel source should be present")
    }

    #[test]
    #[ignore = "requires an NVIDIA GPU and CUDA driver"]
    #[cfg(feature = "pipnn_cuda")]
    fn cuda_device_caps_are_self_consistent() {
        let params = PiPNNParams::default();
        let backend = super::cuda_backend::CudaComputeBackend::new(0, &params).unwrap();
        let profile = backend.gpu_hardware_adaptation_profile().unwrap();

        assert_eq!(profile.device.device_id, 0);
        assert!(!profile.device.device_uuid.is_empty());
        assert!(!profile.device.device_name.is_empty());
        assert!(profile.device.sm_count > 0);
        assert_eq!(profile.device.warp_size, 32);
        assert!(profile.device.total_hbm_bytes > 0);
        assert!(profile.device.driver_version > 0);
        assert!(profile.device.runtime_version > 0);
    }

    #[test]
    #[ignore = "requires an NVIDIA GPU and CUDA driver"]
    #[cfg(feature = "pipnn_cuda")]
    fn cuda_legacy_persistent_kernel_caps_are_recorded() {
        let params = PiPNNParams::default();
        let backend = super::cuda_backend::CudaComputeBackend::new(0, &params).unwrap();
        backend
            .load_legacy_dco_enabled_fused_persistent_function_for_test()
            .unwrap();
        backend
            .load_legacy_dco_enabled_fused_persistent_function_for_test()
            .unwrap();
        let profile = backend.gpu_hardware_adaptation_profile().unwrap();
        let caps = profile
            .kernel_caps
            .iter()
            .find(|caps| {
                caps.entrypoint == "gpu_persistent_subtree_topk" && caps.block_threads == 256
            })
            .expect("default fused persistent-kernel caps should be recorded");

        assert_eq!(caps.kernel_source_hash.len(), 64);
        assert!(
            caps.kernel_source_hash
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
        );
        assert!(caps.nvrtc_arch.starts_with("compute_"));
        assert!(!caps.compile_specialization.is_empty());
        assert_eq!(caps.warps_per_cta, 8);
        assert!(caps.registers_per_thread > 0);
        assert!(caps.active_ctas_per_sm > 0);
        assert_eq!(caps.dynamic_shared_bytes, 0);
        assert_eq!(
            caps.resident_cta_cap,
            profile.device.sm_count * caps.active_ctas_per_sm
        );
    }

    #[test]
    fn gpu_legacy_persistent_launch_observation_records_exact_worker_split() {
        let mut profile = GpuHardwareAdaptationProfile::new(
            PiPNNGpuSubtreePolicy::Report,
            PiPNNGpuSubtreePolicy::Report,
            GpuDeviceCaps::default(),
        );
        let caps = GpuKernelCaps {
            entrypoint: "gpu_persistent_subtree_topk".to_string(),
            kernel_source_hash: "test-source".to_string(),
            nvrtc_arch: "compute_80".to_string(),
            compile_specialization: "test-specialization".to_string(),
            block_threads: 256,
            warps_per_cta: 8,
            registers_per_thread: 64,
            static_shared_bytes: 4096,
            dynamic_shared_bytes: 0,
            active_ctas_per_sm: 2,
            resident_cta_cap: 160,
        };

        super::record_legacy_persistent_launch_observation(&mut profile, &caps, 3, 5);

        let decision = &profile.decision;
        let plan = &decision.applied_plan;
        assert_eq!(plan.total_worker_ctas, 8);
        assert_eq!(plan.partition_worker_ctas, 3);
        assert_eq!(plan.topk_worker_ctas, 5);
        assert_eq!(plan.work_demand_ctas, 8);
        assert_eq!(plan.entrypoint, caps.entrypoint);
        assert_eq!(plan.block_threads, caps.block_threads);
        assert_eq!(plan.warps_per_cta, caps.warps_per_cta);
        assert_eq!(plan.resident_cta_cap, caps.resident_cta_cap);
        assert_eq!(decision.legacy_plan, decision.applied_plan);
        assert_eq!(decision.recommended_plan, None);
        assert_eq!(decision.applied_source, "legacy");
        assert_eq!(plan.plan_source, "legacy");
        assert_eq!(decision.reason, "legacy_observation_only");
        assert_eq!(plan.decision_reason, "legacy_observation_only");
        assert_eq!(plan.calibration_key, None);
    }

