    #[test]
    fn owned_gpu_subtree_quantized_input_clone_reuses_backing_allocations() {
        let owned = OwnedGpuSubtreeQuantizedInput {
            distance_kind: GpuSubtreeQuantizedDistanceKind::SqInt8,
            global_ids: Arc::new(vec![3, 7]),
            codes: Arc::new(vec![1, 2, 3, 4]),
            deltas: Arc::new(vec![0.5, 0.25]),
            code_sums: Arc::new(vec![10.0, 20.0]),
            norms: Arc::new(vec![4.0, 9.0]),
            dim: 2,
            padded_dim: 2,
            code_layout: GpuSubtreeQuantizedCodeLayout::DenseI8,
            code_row_bytes: 2,
            bits: 8,
        };
        let cloned = owned.clone();

        assert!(Arc::ptr_eq(&owned.global_ids, &cloned.global_ids));
        assert!(Arc::ptr_eq(&owned.codes, &cloned.codes));
        assert!(Arc::ptr_eq(&owned.deltas, &cloned.deltas));
        assert!(Arc::ptr_eq(&owned.code_sums, &cloned.code_sums));
        assert!(Arc::ptr_eq(&owned.norms, &cloned.norms));

        let borrowed = cloned.as_borrowed();
        assert_eq!(borrowed.global_ids, &[3, 7]);
        assert_eq!(borrowed.codes, &[1, 2, 3, 4]);
        assert_eq!(borrowed.deltas, &[0.5, 0.25]);
        assert_eq!(borrowed.code_sums, &[10.0, 20.0]);
        assert_eq!(borrowed.norms, &[4.0, 9.0]);
        assert_eq!(borrowed.code_row_bytes, 2);
    }

    #[test]
    fn backend_default_owned_submission_returns_ready_result() {
        let point_ids = vec![3, 7];
        let request = GpuSubtreePartitionRequest {
            point_ids: &point_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: point_ids.len(),
            adaptive_c_max: point_ids.len(),
            min_recurse_size: point_ids.len(),
            memory_budget_bytes: None,
        };
        let owned = OwnedGpuSubtreeQuantizedInput {
            distance_kind: GpuSubtreeQuantizedDistanceKind::SqInt8,
            global_ids: Arc::new(point_ids.clone()),
            codes: Arc::new(vec![1, 2, 3, 4]),
            deltas: Arc::new(vec![0.5, 0.25]),
            code_sums: Arc::new(vec![0.0; 2]),
            norms: Arc::new(vec![4.0, 9.0]),
            dim: 2,
            padded_dim: 2,
            code_layout: GpuSubtreeQuantizedCodeLayout::DenseI8,
            code_row_bytes: 2,
            bits: 8,
        };
        let backend = BackendResolutionPolicyStub {
            validation_error: None,
        };

        let submission = backend
            .submit_owned_quantized_subtree_l2_compact_topk(
                &request,
                owned,
                &PiPNNParams::default(),
            )
            .expect("default owned submission");

        match submission {
            GpuSubtreeTopKSubmission::Ready(result) => {
                assert_eq!(result.max_active_points, point_ids.len());
            }
            GpuSubtreeTopKSubmission::Deferred(_) => {
                panic!("default backend submission must remain synchronous")
            }
        }
    }

