    #[cfg(feature = "pipnn_cuda")]
    fn write_identity_ddc_res_pca_sidecar(path: &std::path::Path, dim: usize) {
        use std::io::Write;

        let mut file = std::fs::File::create(path).expect("create DDC_res PCA sidecar");
        let mut write_row = |row: &[f32]| {
            file.write_all(&(row.len() as u32).to_le_bytes())
                .expect("write fvecs dim");
            for &value in row {
                file.write_all(&value.to_le_bytes())
                    .expect("write fvecs value");
            }
        };
        write_row(&vec![0.0_f32; dim]);
        write_row(&vec![0.0_f32; dim]);
        write_row(&vec![1.0_f32; dim]);
        for row in 0..dim {
            let mut values = vec![0.0_f32; dim];
            values[row] = 1.0;
            write_row(&values);
        }
    }

