    #[cfg(feature = "pipnn_cuda")]
    struct SparseCudaSubtreePointStore {
        global_ids: Vec<u32>,
        data: Vec<f32>,
        dim: usize,
    }

    #[cfg(feature = "pipnn_cuda")]
    impl SparseCudaSubtreePointStore {
        fn from_fbin_rows(path: &str, global_ids: Vec<u32>) -> AnnResult<Self> {
            use std::io::{Read, Seek, SeekFrom};

            let mut file = std::fs::File::open(path).map_err(|err| {
                AnnError::log_index_error(format!("Failed to open sparse fbin {path}: {err}"))
            })?;
            let mut header = [0u8; 8];
            file.read_exact(&mut header).map_err(|err| {
                AnnError::log_index_error(format!(
                    "Failed to read sparse fbin header {path}: {err}"
                ))
            })?;
            let rows = u32::from_le_bytes(header[0..4].try_into().unwrap()) as usize;
            let dim = u32::from_le_bytes(header[4..8].try_into().unwrap()) as usize;
            let row_bytes = dim.checked_mul(std::mem::size_of::<f32>()).ok_or_else(|| {
                AnnError::log_index_error("Sparse fbin row byte size overflow".to_string())
            })?;
            let mut data = vec![0.0f32; global_ids.len().saturating_mul(dim)];
            let mut bytes = vec![0u8; row_bytes];
            for (row, &global_id) in global_ids.iter().enumerate() {
                if global_id as usize >= rows {
                    return Err(AnnError::log_index_error(format!(
                        "Sparse fbin global id {global_id} exceeds row count {rows}"
                    )));
                }
                let offset = 8u64
                    .checked_add((global_id as u64).saturating_mul(row_bytes as u64))
                    .ok_or_else(|| {
                        AnnError::log_index_error("Sparse fbin seek offset overflow".to_string())
                    })?;
                file.seek(SeekFrom::Start(offset)).map_err(|err| {
                    AnnError::log_index_error(format!(
                        "Failed to seek sparse fbin {path} to row {global_id}: {err}"
                    ))
                })?;
                file.read_exact(&mut bytes).map_err(|err| {
                    AnnError::log_index_error(format!(
                        "Failed to read sparse fbin {path} row {global_id}: {err}"
                    ))
                })?;
                let dst = row * dim;
                for axis in 0..dim {
                    let start = axis * std::mem::size_of::<f32>();
                    data[dst + axis] = f32::from_le_bytes(
                        bytes[start..start + std::mem::size_of::<f32>()]
                            .try_into()
                            .unwrap(),
                    );
                }
            }
            Ok(Self {
                global_ids,
                data,
                dim,
            })
        }

        fn row_for_global_id(&self, pid: u32) -> AnnResult<usize> {
            self.global_ids
                .binary_search(&pid)
                .map_err(|_| AnnError::log_index_error(format!("Sparse point id {pid} missing")))
        }
    }

    #[cfg(feature = "pipnn_cuda")]
    impl PointStore for SparseCudaSubtreePointStore {
        fn len(&self) -> usize {
            self.global_ids.len()
        }

        fn dim(&self) -> usize {
            self.dim
        }

        fn read_point_into(&self, pid: u32, out: &mut [f32]) -> AnnResult<()> {
            if out.len() != self.dim {
                return Err(AnnError::log_index_error(format!(
                    "Sparse point buffer width mismatch: got {} expected {}",
                    out.len(),
                    self.dim
                )));
            }
            let row = self.row_for_global_id(pid)?;
            let start = row * self.dim;
            out.copy_from_slice(&self.data[start..start + self.dim]);
            Ok(())
        }

        fn read_range_into(&self, start_pid: u32, count: usize, out: &mut [f32]) -> AnnResult<()> {
            if out.len() != count.saturating_mul(self.dim) {
                return Err(AnnError::log_index_error(format!(
                    "Sparse range buffer size mismatch: got {} expected {}",
                    out.len(),
                    count.saturating_mul(self.dim)
                )));
            }
            for row in 0..count {
                let dst = row * self.dim;
                self.read_point_into(start_pid + row as u32, &mut out[dst..dst + self.dim])?;
            }
            Ok(())
        }

        fn read_points_into(&self, ids: &[u32], out: &mut [f32]) -> AnnResult<()> {
            if out.len() != ids.len().saturating_mul(self.dim) {
                return Err(AnnError::log_index_error(format!(
                    "Sparse point matrix size mismatch: got {} expected {}",
                    out.len(),
                    ids.len().saturating_mul(self.dim)
                )));
            }
            for (row, &pid) in ids.iter().enumerate() {
                let dst = row * self.dim;
                self.read_point_into(pid, &mut out[dst..dst + self.dim])?;
            }
            Ok(())
        }
    }

    #[cfg(feature = "pipnn_cuda")]
    impl CountingCudaSubtreePointStore {
        fn new(rows: usize, dim: usize) -> Self {
            let data = (0..rows)
                .flat_map(|row| {
                    (0..dim).map(move |axis| {
                        let cluster = (row / 16) as f32;
                        let mixed = (row as u32)
                            .wrapping_mul(747_796_405)
                            .wrapping_add((axis as u32).wrapping_mul(2_891_336_453))
                            .rotate_left((axis % 17) as u32);
                        let jitter = (mixed & 0xffff) as f32 / 65_535.0;
                        if axis == 0 {
                            cluster * 30.0 + jitter
                        } else {
                            axis as f32 * 0.25 + jitter * 3.0
                        }
                    })
                })
                .collect();
            Self {
                data,
                rows,
                dim,
                batch_reads: AtomicUsize::new(0),
            }
        }

        fn batch_reads(&self) -> usize {
            self.batch_reads.load(Ordering::Relaxed)
        }
    }

    fn queue_shadow_test_vectors(rows: usize, dim: usize) -> Vec<f32> {
        let mut x = vec![0.0_f32; rows.saturating_mul(dim)];
        for row in 0..rows {
            let group = row % 8;
            for axis in 0..dim {
                x[row * dim + axis] =
                    group as f32 * 10.0 + (row / 8) as f32 * 0.1 + axis as f32 * 0.01;
            }
        }
        x
    }

