    fn parse_leaf_sq_int8_replay_specs(input: &str) -> Result<Vec<LeafSqInt8ReplaySpec>, String> {
        let mut specs = Vec::new();
        for raw_spec in input.split(|ch| matches!(ch, ';' | '\n')) {
            let raw_spec = raw_spec.trim();
            if raw_spec.is_empty() {
                continue;
            }
            let parts: Vec<_> = raw_spec.split('x').collect();
            if parts.len() != 5 {
                return Err(format!(
                    "invalid leaf SQ-int8 replay spec '{raw_spec}', expected row_countxtile_rowsxdimxkxsurvivors"
                ));
            }
            let parse_part = |idx: usize, label: &str| -> Result<usize, String> {
                let value = parts[idx].trim().parse::<usize>().map_err(|err| {
                    format!("invalid {label} in leaf SQ-int8 replay spec '{raw_spec}': {err}")
                })?;
                if value == 0 {
                    Err(format!("{label} must be non-zero in '{raw_spec}'"))
                } else {
                    Ok(value)
                }
            };
            specs.push(LeafSqInt8ReplaySpec {
                row_count: parse_part(0, "row_count")?,
                tile_rows: parse_part(1, "tile_rows")?,
                dim: parse_part(2, "dim")?,
                k: parse_part(3, "k")?,
                survivors: parse_part(4, "survivors")?,
            });
        }
        if specs.is_empty() {
            return Err("leaf SQ-int8 replay spec list is empty".to_string());
        }
        Ok(specs)
    }

