    #[cfg(feature = "pipnn_cuda")]
    fn parse_leaf_sq_int8_replay_rerank_modes(
        input: &str,
    ) -> Result<Vec<crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoRerankMode>, String> {
        use std::str::FromStr;

        let mut modes = Vec::new();
        for raw_mode in input.split(|ch| matches!(ch, ',' | ';' | '\n')) {
            let raw_mode = raw_mode.trim();
            if raw_mode.is_empty() {
                continue;
            }
            modes.push(
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoRerankMode::from_str(raw_mode)
                    .map_err(|err| format!("invalid leaf SQ-int8 replay rerank mode: {err}"))?,
            );
        }
        if modes.is_empty() {
            return Err("leaf SQ-int8 replay rerank mode list is empty".to_string());
        }
        Ok(modes)
    }

