    #[test]
    fn compact_topk_batch_from_leaf_gram_excludes_self_and_orders_ties_by_point_id() {
        let point_ids = [10, 20, 30];
        let norms = [1.0, 1.0, 1.0];
        let gram = [
            1.0, 0.75, 0.75, //
            0.75, 1.0, 0.5, //
            0.75, 0.5, 1.0,
        ];

        let batch =
            super::compact_topk_batch_from_leaf_gram(7, &point_ids, &norms, &gram, 3, 2).unwrap();

        assert_eq!(batch.leaf_id, 7);
        assert_eq!(batch.point_ids, point_ids);
        assert_eq!(batch.rows, 3);
        assert_eq!(batch.k, 2);
        assert_eq!(batch.topk_ids, vec![20, 30, 10, 30, 10, 20]);
        assert!(batch.topk_dists.iter().all(|dist| dist.is_finite()));
        for (row, &point_id) in point_ids.iter().enumerate() {
            let start = row * batch.k;
            assert!(!batch.topk_ids[start..start + batch.k].contains(&point_id));
        }
    }

