    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn gpu_persistent_topk_only_kernel_drains_existing_leaf_queue_without_partitioning() {
        let source = super::cuda_backend::GPU_PERSISTENT_SUBTREE_KERNEL_SRC;
        let rust_source = include_str!("compute_backend.rs");
        let kernel = source
            .split("extern \"C\" __global__ void gpu_persistent_subtree_topk_only")
            .nth(1)
            .and_then(|tail| {
                tail.split("extern \"C\" __global__ void gpu_persistent_subtree_topk")
                    .next()
            })
            .expect("top-k-only persistent kernel source should be present");

        assert!(
            kernel.contains("const unsigned int* leaf_queue")
                && kernel.contains("const unsigned int* leaf_row_ids")
                && kernel.contains("const unsigned long long* leaf_starts")
                && kernel.contains("const unsigned long long* leaf_sizes"),
            "top-k-only kernel must consume leaf metadata already produced by partition-only stage"
        );
        assert!(
            kernel.contains("const float* leaf_dco_weighted_query_square")
                && kernel.contains("const signed char* leaf_sq_int8_codes")
                && kernel.contains("const unsigned char* leaf_rabitq_split_batch")
                && kernel.contains("unsigned int* topk_row_locks")
                && kernel.contains("unsigned long long* wmma_diag_counters"),
            "top-k-only kernel ABI must keep the existing leaf DCO, quantized, RabitQ split, WMMA diagnostic, and row-lock inputs"
        );
        assert!(
            kernel.contains("gpu_persistent_counter_store(counters, P_DONE, 1ull)")
                && kernel.contains("gpu_persistent_counter_store(counters, P_OUTPUT_ROWS, (unsigned long long)leaf_rows)")
                && kernel.contains("gpu_persistent_counter_store(counters, P_LEAF_PUSHES, leaf_task_count)"),
            "top-k-only kernel should seed counters from stage-1 leaf metadata instead of running partition work"
        );
        assert!(
            kernel.contains("gpu_persistent_try_drain_leaf_tile_cta("),
            "top-k-only kernel must reuse the existing leaf tile drain helper"
        );
        assert!(
            !kernel.contains("P_INIT_OUTPUT_CLEAR_BLOCKS")
                && !kernel.contains("topk_ids[idx] = 0xffffffffu;")
                && !kernel.contains("gpu_persistent_counter_store(counters, P_INIT_DONE, 2ull);"),
            "top-k-only kernel must not use an in-kernel grid-wide output-clear barrier"
        );
        assert!(
            rust_source.contains("Failed to clear CUDA persistent top-k-only ids")
                && rust_source.contains("Failed to clear CUDA persistent top-k-only distances")
                && rust_source.contains("Failed to clear CUDA persistent top-k-only row locks"),
            "top-k-only output and row-lock clearing should be stream-ordered on the host before launch"
        );
        assert!(
            !kernel.contains("partition_queue")
                && !kernel.contains("gpu_persistent_process_node(")
                && !kernel.contains("gpu_persistent_process_large_task_cta("),
            "top-k-only kernel must not contain partition worker branches"
        );
    }

