    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn gpu_persistent_kernel_has_device_side_progress_watchdog_snapshot() {
        let source = super::cuda_backend::GPU_PERSISTENT_SUBTREE_KERNEL_SRC;
        assert!(
            source.contains("GPU_PERSISTENT_WATCHDOG_STALLED"),
            "persistent kernel must fail-return with a dedicated watchdog overflow flag instead of spinning forever"
        );
        assert!(
            source.contains("P_PROGRESS_EPOCH"),
            "persistent kernel must expose a monotonic progress epoch for device-side watchdog decisions"
        );
        assert!(
            source.contains("P_SNAPSHOT_PARTITION_HEAD"),
            "persistent kernel must publish partition queue snapshot counters before/while waiting"
        );
        assert!(
            source.contains("P_SNAPSHOT_LEAF_HEAD"),
            "persistent kernel must publish leaf queue snapshot counters before/while waiting"
        );
        assert!(
            source.contains("gpu_persistent_watchdog_tick(counters"),
            "persistent worker wait loops must invoke the device-side watchdog"
        );
        assert!(
            source.contains("gpu_persistent_mark_progress(counters);"),
            "persistent queue/leaf progress points must advance the progress epoch"
        );
        assert!(source.contains("P_SNAPSHOT_ACTIVE_LARGE"));
        assert!(source.contains("P_SNAPSHOT_LARGE_GENERATION"));
        assert!(source.contains("P_SNAPSHOT_LARGE_PHASE"));
        assert!(source.contains("P_SNAPSHOT_LARGE_TOTAL_TILES"));
        assert!(source.contains("P_SNAPSHOT_LARGE_COUNT_NEXT"));
        assert!(source.contains("P_SNAPSHOT_LARGE_COUNT_DONE"));
        assert!(source.contains("P_SNAPSHOT_LARGE_SCATTER_NEXT"));
        assert!(source.contains("P_SNAPSHOT_LARGE_SCATTER_DONE"));
        let watchdog = source
            .split("static __device__ void gpu_persistent_watchdog_tick(")
            .nth(1)
            .and_then(|tail| {
                tail.split("static __device__ bool gpu_persistent_active_work_tick(")
                    .next()
            })
            .expect("watchdog helper should exist");
        assert!(
            watchdog.contains("if (blockIdx.x != 0u || threadIdx.x != 0u)"),
            "watchdog poll counts must come from one persistent owner instead of scaling with idle helper CTAs"
        );
        assert!(!watchdog.contains(
            "P_ACTIVE_PARTITION) != 0ull\n        || gpu_persistent_counter_load(counters, P_ACTIVE_TOPK) != 0ull"
        ));
        assert!(source.contains("gpu_persistent_snapshot(counters, large_scratch_lock);"));
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn gpu_persistent_watchdog_trips_on_stable_active_large_and_accepts_done_progress() {
        let base = super::cuda_backend::GPU_PERSISTENT_SUBTREE_KERNEL_SRC
            .replace(
                "GPU_PERSISTENT_WATCHDOG_POLL_INTERVAL = 65536ull",
                "GPU_PERSISTENT_WATCHDOG_POLL_INTERVAL = 1ull",
            )
            .replace(
                "GPU_PERSISTENT_WATCHDOG_STALL_POLLS = 16777216ull",
                "GPU_PERSISTENT_WATCHDOG_STALL_POLLS = 4ull",
            );
        let new_watchdog = base.contains("P_SNAPSHOT_ACTIVE_LARGE");
        let harness = if new_watchdog {
            r#"
extern "C" __global__ void gpu_persistent_watchdog_contract_test(unsigned int* out) {
    __shared__ unsigned long long stalled[GPU_PERSISTENT_COUNTER_WORDS];
    __shared__ __align__(8) unsigned int stalled_task[GPU_PERSISTENT_LARGE_TASK_WORDS];
    for (unsigned int i = 0u; i < GPU_PERSISTENT_COUNTER_WORDS; ++i) stalled[i] = 0ull;
    for (unsigned int i = 0u; i < GPU_PERSISTENT_LARGE_TASK_WORDS; ++i) stalled_task[i] = 0u;
    stalled[P_ACTIVE_LARGE] = 1ull;
    stalled_task[L_PHASE] = GPU_PERSISTENT_LARGE_TASK_COUNT;
    stalled_task[L_GENERATION] = 9u;
    stalled_task[L_TOTAL_TILES] = 123u;
    gpu_persistent_large_ticket_store(stalled_task, L_COUNT_TICKET, 9u, 17u);
    gpu_persistent_large_ticket_store(stalled_task, L_SCATTER_TICKET, 9u, 0u);
    stalled_task[L_COUNT_DONE] = 8u;
    for (unsigned int i = 0u; i < 6u; ++i) {
        gpu_persistent_watchdog_tick(stalled, stalled_task);
        if (stalled[P_OVERFLOW_FLAGS] != 0ull) break;
    }
    out[0] = (unsigned int)stalled[P_OVERFLOW_FLAGS];
    out[1] = (unsigned int)stalled[P_WATCHDOG_TRIPS];
    out[2] = (unsigned int)stalled[P_SNAPSHOT_ACTIVE_LARGE];
    out[3] = (unsigned int)stalled[P_SNAPSHOT_LARGE_TOTAL_TILES];
    out[4] = (unsigned int)stalled[P_SNAPSHOT_LARGE_COUNT_NEXT];
    out[5] = (unsigned int)stalled[P_SNAPSHOT_LARGE_COUNT_DONE];

    __shared__ unsigned long long moving[GPU_PERSISTENT_COUNTER_WORDS];
    __shared__ __align__(8) unsigned int moving_task[GPU_PERSISTENT_LARGE_TASK_WORDS];
    for (unsigned int i = 0u; i < GPU_PERSISTENT_COUNTER_WORDS; ++i) moving[i] = 0ull;
    for (unsigned int i = 0u; i < GPU_PERSISTENT_LARGE_TASK_WORDS; ++i) moving_task[i] = 0u;
    moving[P_ACTIVE_LARGE] = 1ull;
    moving_task[L_PHASE] = GPU_PERSISTENT_LARGE_TASK_COUNT;
    moving_task[L_GENERATION] = 10u;
    moving_task[L_TOTAL_TILES] = 123u;
    gpu_persistent_large_ticket_store(moving_task, L_COUNT_TICKET, 10u, 17u);
    gpu_persistent_large_ticket_store(moving_task, L_SCATTER_TICKET, 10u, 0u);
    for (unsigned int i = 0u; i < 8u; ++i) {
        moving_task[L_COUNT_DONE] = i + 1u;
        gpu_persistent_watchdog_tick(moving, moving_task);
    }
    out[6] = (unsigned int)moving[P_OVERFLOW_FLAGS];
    out[7] = (unsigned int)moving[P_WATCHDOG_TRIPS];
}
"#
        } else {
            r#"
extern "C" __global__ void gpu_persistent_watchdog_contract_test(unsigned int* out) {
    __shared__ unsigned long long stalled[GPU_PERSISTENT_COUNTER_WORDS];
    for (unsigned int i = 0u; i < GPU_PERSISTENT_COUNTER_WORDS; ++i) stalled[i] = 0ull;
    stalled[P_ACTIVE_LARGE] = 1ull;
    for (unsigned int i = 0u; i < 6u; ++i) {
        gpu_persistent_watchdog_tick(stalled, 1u);
        if (stalled[P_OVERFLOW_FLAGS] != 0ull) break;
    }
    out[0] = (unsigned int)stalled[P_OVERFLOW_FLAGS];
    out[1] = (unsigned int)stalled[P_WATCHDOG_TRIPS];
    out[2] = 1u;
    out[3] = 123u;
    out[4] = 17u;
    out[5] = 8u;
    __shared__ unsigned long long moving[GPU_PERSISTENT_COUNTER_WORDS];
    for (unsigned int i = 0u; i < GPU_PERSISTENT_COUNTER_WORDS; ++i) moving[i] = 0ull;
    moving[P_ACTIVE_LARGE] = 1ull;
    for (unsigned int i = 0u; i < 8u; ++i) {
        gpu_persistent_watchdog_tick(moving, 1u);
    }
    out[6] = (unsigned int)moving[P_OVERFLOW_FLAGS];
    out[7] = (unsigned int)moving[P_WATCHDOG_TRIPS];
}
"#
        };
        let output = run_persistent_cuda_u32_harness(
            format!("{base}\n{harness}"),
            "gpu_persistent_watchdog_contract_test",
            8,
        );
        assert_eq!(output, vec![1 << 11, 1, 1, 123, 17, 8, 0, 0]);
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn gpu_persistent_watchdog_starts_after_root_work_is_published() {
        let source = super::cuda_backend::GPU_PERSISTENT_SUBTREE_KERNEL_SRC;
        let init_wait_start = source
            .find("while (gpu_persistent_counter_load(counters, P_INIT_DONE) == 0ull) {")
            .expect("persistent kernel must have an init wait loop");
        let worker_start = source[init_wait_start..]
            .find("    if (blockIdx.x < partition_worker_blocks) {")
            .expect("persistent kernel must enter partition workers after init wait")
            + init_wait_start;
        let init_wait = &source[init_wait_start..worker_start];
        assert!(
            !init_wait.contains("gpu_persistent_watchdog_tick"),
            "watchdog must not trip while block 0 is still publishing the initial root node"
        );
        assert!(
            source.contains(
                "gpu_persistent_mark_progress(counters);\n        gpu_persistent_counter_store(counters, P_INIT_DONE, 1ull);"
            ),
            "publishing the initial root node must advance the watchdog epoch before output-clear init_done state"
        );
        assert!(
            source.contains("gpu_persistent_counter_store(counters, P_INIT_DONE, 2ull);"),
            "worker CTAs must wait for the output-clear init_done state before producer/consumer work"
        );
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn gpu_persistent_large_node_has_active_work_budget_diagnostic() {
        let source = super::cuda_backend::GPU_PERSISTENT_SUBTREE_KERNEL_SRC;
        assert!(
            source.contains("GPU_PERSISTENT_ACTIVE_WORK_BUDGET"),
            "persistent diagnostics must keep the historical active-work bit named for profile compatibility"
        );
        assert!(
            source.contains("gpu_persistent_active_work_tick("),
            "large-node CTA work must keep active-work telemetry while partition workers are active"
        );
        assert!(
            source.contains("GPU_PERSISTENT_ACTIVE_WORK_BUDGET_MIN_ROWS = 1281u"),
            "active-work budget must cover dense-i8 RabitQ+ nodes above the configured Wiki10M leaf_max"
        );
        assert!(
            source.contains("GPU_PERSISTENT_ACTIVE_WORK_BUDGET_TICKS = 2048ull"),
            "active-work budget constant remains part of persistent-kernel diagnostics"
        );
        let tick_start = source
            .find("static __device__ bool gpu_persistent_active_work_tick(")
            .expect("active-work telemetry helper must exist");
        let tick_end = source[tick_start..]
            .find("static __device__ bool gpu_persistent_try_claim(")
            .expect("active-work helper must precede try_claim")
            + tick_start;
        let tick_body = &source[tick_start..tick_end];
        assert!(
            tick_body.contains("abort_on_budget != 0u"),
            "active-work budget abort must be opt-in rather than affecting the default exact path"
        );
        assert!(
            tick_body.contains(
                "atomicOr(&counters[P_OVERFLOW_FLAGS], GPU_PERSISTENT_ACTIVE_WORK_BUDGET)"
            ),
            "active-work budget helper must still be able to emit the historical diagnostic bit"
        );
        assert!(
            tick_body.contains("gpu_persistent_mark_progress(counters);"),
            "active-work telemetry must advance the progress epoch so long-running large nodes do not look idle"
        );
        assert!(
            !source.contains(
                "distance_source == GPU_PERSISTENT_DISTANCE_SOURCE_RABITQ_PLUS ? 1u : 0u"
            ),
            "dense-i8 RabitQ+ Assignment Work Tiling should advance large-task work without tripping the old active-work abort guard"
        );
    }

