    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn gpu_persistent_large_node_split_requires_meaningful_shrink() {
        let source = super::cuda_backend::GPU_PERSISTENT_SUBTREE_KERNEL_SRC;
        let meaningful_split = source
            .split("static __device__ bool gpu_persistent_meaningful_split(")
            .nth(1)
            .and_then(|tail| {
                tail.split("static __device__ void gpu_persistent_sort_unique")
                    .next()
            })
            .expect("meaningful split helper should exist");
        let large_task_emit = source
            .split("if (phase == GPU_PERSISTENT_LARGE_TASK_EMIT) {")
            .nth(1)
            .and_then(|tail| {
                tail.split("if (phase == GPU_PERSISTENT_LARGE_TASK_SCATTER) {")
                    .next()
            })
            .expect("large task emit phase should exist");
        assert!(meaningful_split.contains("parent_rows >> 5"));
        assert!(meaningful_split.contains("min_shrink < 32u"));
        assert!(
            source.contains("gpu_persistent_meaningful_split(n, max_child, terminal_limit)"),
            "inline and staged split attempts must reject near no-op child splits"
        );
        assert!(
            large_task_emit
                .contains("gpu_persistent_meaningful_split(point_len, max_child, terminal_limit)"),
            "staged large-task emit must reject pathological near-identity children"
        );
        assert!(
            large_task_emit.contains("gpu_persistent_sample_large_retry_leaders("),
            "staged large-task emit must resample leaders before giving up"
        );
        assert!(
            large_task_emit.contains("L_BALANCED_FALLBACK"),
            "staged large-task emit must switch to a guaranteed balanced split after retries"
        );
        assert!(
            !large_task_emit.contains("GPU_PERSISTENT_NO_PROGRESS_SPLIT"),
            "recoverable no-progress must not abort the persistent kernel"
        );
    }

