    #[test]
    fn gpu_persistent_scheduler_config_resolves_auto_and_validates_backoff() {
        use crate::algorithm::pipnn::PiPNNGpuSubtreePersistentSchedulerMode as Mode;

        let auto = super::resolve_gpu_persistent_scheduler_config(Mode::Auto, 350, 8).unwrap();
        assert_eq!(auto.actual_mode, Mode::Baseline);
        assert_eq!(auto.idle_backoff_ns, 0);
        for delay in [0, 350, 700, 1400] {
            let config =
                super::resolve_gpu_persistent_scheduler_config(Mode::AdaptiveIdle, delay, 8)
                    .unwrap();
            assert_eq!(config.actual_mode, Mode::AdaptiveIdle);
            assert_eq!(config.idle_backoff_ns, delay);
        }
        assert!(
            super::resolve_gpu_persistent_scheduler_config(Mode::AdaptiveIdle, 351, 8).is_err()
        );
        assert!(
            super::resolve_gpu_persistent_scheduler_config(Mode::AdaptiveIdle, 350, 6).is_err()
        );
    }

