    #[cfg(feature = "pipnn_cuda")]
    impl PointStore for CountingCudaSubtreePointStore {
        fn len(&self) -> usize {
            self.rows
        }

        fn dim(&self) -> usize {
            self.dim
        }

        fn read_point_into(&self, pid: u32, out: &mut [f32]) -> AnnResult<()> {
            let start = pid as usize * self.dim;
            out.copy_from_slice(&self.data[start..start + self.dim]);
            Ok(())
        }

        fn read_range_into(&self, start_pid: u32, count: usize, out: &mut [f32]) -> AnnResult<()> {
            for row in 0..count {
                let src_start = (start_pid as usize + row) * self.dim;
                let dst_start = row * self.dim;
                out[dst_start..dst_start + self.dim]
                    .copy_from_slice(&self.data[src_start..src_start + self.dim]);
            }
            Ok(())
        }

        fn read_points_into(&self, ids: &[u32], out: &mut [f32]) -> AnnResult<()> {
            for (row, &pid) in ids.iter().enumerate() {
                let src_start = pid as usize * self.dim;
                let dst_start = row * self.dim;
                out[dst_start..dst_start + self.dim]
                    .copy_from_slice(&self.data[src_start..src_start + self.dim]);
            }
            Ok(())
        }

        fn read_points_windowed_into_batch_stats(
            &self,
            ids: &[u32],
            out: &mut [f32],
            _options: &WindowedGatherOptions,
            _stats: &mut PointBatchStats,
        ) -> AnnResult<()> {
            self.batch_reads.fetch_add(1, Ordering::Relaxed);
            self.read_points_into(ids, out)
        }
    }

    fn build_dataset(rows: usize, dim: usize) -> crate::model::InmemDataset<f32> {
        let mut dataset = crate::model::InmemDataset::new(rows, 1.0, dim).unwrap();
        for row in 0..rows {
            let cluster = (row / 16) as f32;
            for axis in 0..dim {
                let offset = row * dim + axis;
                dataset.data[offset] = cluster * 30.0 + axis as f32 * 0.25 + row as f32 * 0.01;
            }
        }
        dataset
    }

