    #[test]
    fn compact_topk_workspace_estimate_uses_compact_output_not_full_matrix() {
        let rows = 4096;
        let dim = 128;
        let k = 10;

        let plan = plan_compact_topk_l2_workspace(rows, dim, k, None)
            .expect("default budget should fit this compact top-k workload");
        let full_matrix_bytes = rows * rows * std::mem::size_of::<f32>();

        assert_eq!(
            plan.dtoh_bytes,
            rows * k * (std::mem::size_of::<u32>() + std::mem::size_of::<f32>())
        );
        assert!(plan.required_bytes < full_matrix_bytes / 2);
        assert_eq!(plan.row_tile_rows, rows);
    }

    #[test]
    fn compact_topk_workspace_plan_shrinks_row_tile_to_fit_budget() {
        let rows = 1024;
        let dim = 64;
        let k = 8;
        let fixed_input_bytes = rows * dim * std::mem::size_of::<f32>()
            + rows * std::mem::size_of::<u32>()
            + rows * std::mem::size_of::<f32>()
            + 2 * std::mem::size_of::<u64>();
        let one_row_output_bytes = estimate_compact_topk_dtoh_bytes(1, k);
        let budget = fixed_input_bytes + one_row_output_bytes * 32;

        let plan = plan_compact_topk_l2_workspace(rows, dim, k, Some(budget))
            .expect("budget should fit a smaller row tile");

        assert!(plan.row_tile_rows > 0);
        assert!(plan.row_tile_rows < rows);
        assert!(plan.required_bytes <= budget);
    }

    #[test]
    fn compact_topk_leaf_batch_plan_splits_before_workspace_pressure() {
        let leaf_sizes = vec![128, 128, 128, 128];
        let dim = 64;
        let leaf_knn = 8;
        let two_leaf_budget = plan_compact_topk_l2_batch_workspace(256, dim, leaf_knn, 2, None)
            .expect("unbounded two-leaf compact top-k should have a plan")
            .required_bytes;
        let full_plan =
            plan_compact_topk_l2_batch_workspace(512, dim, leaf_knn, 4, Some(two_leaf_budget));
        assert!(full_plan.is_none() || full_plan.is_some_and(|plan| plan.pressure));

        let batches =
            plan_compact_topk_leaf_batches(&leaf_sizes, dim, leaf_knn, Some(two_leaf_budget))
                .expect("leaf planner should split the compact top-k work");

        assert_eq!(batches.len(), 2);
        assert_eq!(batches[0].leaf_start, 0);
        assert_eq!(batches[0].leaf_end, 2);
        assert_eq!(batches[0].rows, 256);
        assert_eq!(batches[0].max_k, leaf_knn);
        assert!(batches[0].workspace_plan.required_bytes <= two_leaf_budget);
        assert_eq!(batches[1].leaf_start, 2);
        assert_eq!(batches[1].leaf_end, 4);
        assert_eq!(batches[1].rows, 256);
        assert_eq!(batches[1].max_k, leaf_knn);
        assert!(batches[1].workspace_plan.required_bytes <= two_leaf_budget);
    }

