    #[test]
    fn gpu_persistent_subtree_plan_accepts_default_style_depth_aware_fanout() {
        let mut params = crate::algorithm::pipnn::PiPNNParams::default();
        params.fanout_top = 10;
        params.fanout_second = 3;

        let plan = super::plan_gpu_persistent_subtree(
            64,
            2,
            8,
            params.fanout_second.max(1),
            None,
            &params,
        );

        assert!(plan.attempted);
        assert!(plan.supported);
        assert_eq!(plan.fallback_reason_flags, 0);
        assert_eq!(plan.overflow_flags, 0);
        assert_eq!(plan.effective_root_fanout, 3);
        assert_eq!(plan.effective_deeper_fanout, 1);
        assert_eq!(plan.fanout_amplification, 3);
        assert!(
            plan.max_leaf_count >= 12,
            "leaf descriptor capacity must include a safety margin for CTA split leaves"
        );
        assert_eq!(plan.max_leaf_rows, 64 * 3);
        assert_eq!(plan.max_queue_nodes, 64 * 3 + 1);
        assert_eq!(
            plan.max_queue_rows,
            64 * 3 * super::GPU_PERSISTENT_ROW_ARENA_FRONTIER_MULTIPLIER,
            "persistent partition rows use a reusable active-frontier arena, not append-only depth history"
        );
    }

