    #[test]
    fn gpu_persistent_subtree_plan_caps_total_workers_for_persistent_barrier() {
        let mut params = crate::algorithm::pipnn::PiPNNParams::default();
        params.leaf_knn = 2;
        params.fanout_top = 6;
        params.fanout_second = 3;
        params.max_leaders = 1500;
        params.c_max = 1280;
        params.gpu_workspace_budget_bytes = 16 * 1024 * 1024 * 1024;

        let plan = super::plan_gpu_persistent_subtree(
            15_873,
            params.leaf_knn,
            super::gpu_persistent_subtree_max_leaders_for_params(&params),
            params.fanout_second.max(1),
            Some(params.effective_gpu_workspace_budget_bytes()),
            &params,
        );

        assert!(plan.supported, "{plan:?}");
        assert!(
            plan.partition_worker_blocks + plan.topk_worker_blocks
                <= super::GPU_PERSISTENT_MAX_GRID_BLOCKS,
            "persistent kernel uses a software init barrier across the whole grid, so every CTA must be able to start: {plan:?}"
        );
        assert!(plan.partition_worker_blocks > 0);
        assert!(plan.topk_worker_blocks > 0);
    }

