    #[test]
    fn gpu_persistent_subtree_plan_reserves_staged_col_tasks_for_sq_wmma_build() {
        let mut params = crate::algorithm::pipnn::PiPNNParams::default();
        params.leaf_knn = 2;
        params.c_max = 640;
        params.fanout_second = 1;
        params.max_leaders = 2;
        params.gpu_subtree_sq_wmma_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeSqWmmaMode::Build;
        params.gpu_workspace_budget_bytes = 16 * 1024 * 1024 * 1024;

        let plan = super::plan_gpu_persistent_subtree(
            640,
            params.leaf_knn,
            params.max_leaders,
            params.fanout_second.max(1),
            Some(params.effective_gpu_workspace_budget_bytes()),
            &params,
        );

        let row_tile_capacity = plan
            .max_leaf_rows
            .max(1)
            .div_ceil(plan.leaf_tile_rows.max(1));
        let staged_col_capacity = plan.leaf_max.max(1).div_ceil(128).max(1);
        let expected_descriptor_capacity = row_tile_capacity
            .saturating_mul(8)
            .saturating_mul(staged_col_capacity);

        assert!(plan.supported, "{plan:?}");
        assert!(
            plan.max_leaf_count >= expected_descriptor_capacity,
            "SQ+WMMA build can publish row-tile x staged-column leaf_queue descriptors in two-stage mode: {plan:?}, expected_descriptor_capacity={expected_descriptor_capacity}"
        );
    }

    #[test]
    fn gpu_persistent_subtree_plan_rejects_large_subtree_only_when_workspace_exceeds_budget() {
        let mut params = crate::algorithm::pipnn::PiPNNParams::default();
        params.leaf_knn = 2;
        params.fanout_second = 2;
        params.max_leaders = 64;

        let resident_rows = 12_288;
        let unbounded_plan = super::plan_gpu_persistent_subtree(
            resident_rows,
            params.leaf_knn,
            params.max_leaders,
            params.fanout_second.max(1),
            None,
            &params,
        );
        assert!(unbounded_plan.supported, "{unbounded_plan:?}");
        assert!(unbounded_plan.required_bytes > 0);

        let fitting_plan = super::plan_gpu_persistent_subtree(
            resident_rows,
            params.leaf_knn,
            params.max_leaders,
            params.fanout_second.max(1),
            Some(64 * 1024 * 1024),
            &params,
        );

        assert!(fitting_plan.attempted);
        assert!(fitting_plan.supported, "{fitting_plan:?}");
        assert!(fitting_plan.required_bytes <= fitting_plan.budget_bytes);

        let exact_budget_plan = super::plan_gpu_persistent_subtree(
            resident_rows,
            params.leaf_knn,
            params.max_leaders,
            params.fanout_second.max(1),
            Some(unbounded_plan.required_bytes),
            &params,
        );
        assert!(exact_budget_plan.supported, "{exact_budget_plan:?}");
        assert_eq!(
            exact_budget_plan.required_bytes,
            unbounded_plan.required_bytes
        );
        assert_eq!(
            exact_budget_plan.budget_bytes,
            unbounded_plan.required_bytes
        );

        let plan = super::plan_gpu_persistent_subtree(
            resident_rows,
            params.leaf_knn,
            params.max_leaders,
            params.fanout_second.max(1),
            Some(unbounded_plan.required_bytes - 1),
            &params,
        );

        assert!(plan.attempted);
        assert!(!plan.supported);
        assert!(plan.required_bytes > plan.budget_bytes);
        assert_ne!(
            plan.fallback_reason_flags & super::GPU_PERSISTENT_FALLBACK_REASON_WORKSPACE,
            0
        );
        assert_eq!(
            plan.fallback_reason_flags & super::GPU_PERSISTENT_FALLBACK_REASON_LARGE_SUBTREE,
            0
        );
        assert_ne!(
            plan.overflow_flags & super::GPU_QUEUE_OVERFLOW_WORKSPACE_BUDGET,
            0
        );
    }

