    #[test]
    fn cuda_persistent_subtree_leaf_queue_represents_topk_tiles_not_single_cta_leaves() {
        let source = include_str!("compute_backend.rs");
        let kernel = persistent_subtree_topk_kernel_source(source);
        let push_leaf = source
            .split("static __device__ void gpu_persistent_push_leaf")
            .nth(1)
            .and_then(|tail| {
                tail.split("static __device__ bool gpu_persistent_alloc_partition_rows")
                    .next()
            })
            .expect("persistent leaf producer source should be present");
        let drain_leaf_tile = source
            .split("static __device__ bool gpu_persistent_try_drain_leaf_tile_cta")
            .nth(1)
            .and_then(|tail| {
                tail.split("static __device__ bool gpu_persistent_alloc_partition_rows")
                    .next()
            })
            .expect("persistent leaf tile consumer source should be present");

        assert!(
            source.contains("GPU_PERSISTENT_LEAF_TILE_ROWS"),
            "persistent top-k should expose a query-row tile size so one semantic leaf can be consumed by multiple CTAs"
        );
        assert!(
            push_leaf.contains("unsigned int leaf_tile_rows"),
            "persistent leaf producer should receive runtime top-k tile rows"
        );
        assert!(
            !push_leaf.contains("row_count + GPU_PERSISTENT_LEAF_TILE_ROWS - 1u"),
            "persistent leaf producer should not hard-code top-k tile rows"
        );
        assert!(
            source.contains("GPU_PERSISTENT_LEAF_WORDS = 8ull"),
            "leaf queue descriptors should include tile and column-task fields, not only row_start,row_count,leaf_id,ready"
        );
        assert!(
            source.contains("static __device__ void gpu_persistent_compute_topk_leaf_tile_cta"),
            "persistent kernel source should define one leaf query-row tile helper"
        );
        assert!(
            drain_leaf_tile.contains("gpu_persistent_compute_topk_leaf_tile_cta("),
            "leaf tile consumer should call the query-row tile helper"
        );
        assert!(
            kernel.contains("gpu_persistent_try_drain_leaf_tile_cta("),
            "top-k worker should drain one leaf query-row tile per CTA"
        );
        assert!(
            push_leaf.contains("desc[3] = tile_offset"),
            "leaf queue producer should publish per-tile offsets"
        );
        assert!(
            push_leaf.contains("desc[4] = tile_rows"),
            "leaf queue producer should publish per-tile row counts"
        );
        assert!(
            !kernel.contains("static __device__ void gpu_persistent_compute_topk_leaf("),
            "persistent top-k should not keep a whole-semantic-leaf execution helper"
        );
    }

    #[test]
    fn cuda_persistent_subtree_source_exposes_device_topk_operator_dispatch() {
        let source = include_str!("compute_backend.rs");
        let kernel = persistent_subtree_topk_kernel_source(source);
        let drain_leaf_tile = source
            .split("static __device__ bool gpu_persistent_try_drain_leaf_tile_cta")
            .nth(1)
            .and_then(|tail| {
                tail.split("static __device__ bool gpu_persistent_alloc_partition_rows")
                    .next()
            })
            .expect("persistent leaf tile consumer source should be present");

        assert!(
            source.contains("GPU_PERSISTENT_TOPK_OPERATOR_CUSTOM_FP32 = 0u"),
            "persistent kernel source should define the default custom FP32 operator code"
        );
        assert!(
            source.contains("GPU_PERSISTENT_TOPK_OPERATOR_TILED_GEMM_FP32 = 1u"),
            "persistent kernel source should define the tiled GEMM FP32 operator code"
        );
        assert!(
            source.contains("GPU_PERSISTENT_TOPK_OPERATOR_CUVS_BRUTEFORCE_FP32 = 2u"),
            "persistent kernel source should define the cuVS-style brute-force FP32 operator code"
        );
        assert!(
            source.contains("GPU_PERSISTENT_TOPK_OPERATOR_WMMA_TF32 = 3u"),
            "persistent kernel source should define the WMMA TF32 operator code"
        );
        assert!(
            source.contains("gpu_persistent_compute_topk_leaf_tile_cta_tiled_gemm_fp32"),
            "persistent kernel source should define a device-side tiled GEMM FP32 worker"
        );
        assert!(
            source.contains("gpu_persistent_compute_topk_leaf_tile_cta_cuvs_bruteforce_fp32"),
            "persistent kernel source should define a device-side cuVS-style brute-force worker"
        );
        assert!(
            source.contains("gpu_persistent_compute_topk_leaf_tile_cta_wmma_tf32"),
            "persistent kernel source should define a device-side WMMA TF32 worker"
        );
        assert!(
            drain_leaf_tile.contains("unsigned int topk_operator"),
            "leaf tile consumer should receive a runtime top-k operator selector"
        );
        assert!(
            drain_leaf_tile
                .contains("topk_operator == GPU_PERSISTENT_TOPK_OPERATOR_TILED_GEMM_FP32"),
            "leaf tile consumer should dispatch tiled GEMM FP32 inside the persistent kernel"
        );
        assert!(
            drain_leaf_tile
                .contains("topk_operator == GPU_PERSISTENT_TOPK_OPERATOR_CUVS_BRUTEFORCE_FP32"),
            "leaf tile consumer should dispatch cuVS-style brute force inside the persistent kernel"
        );
        assert!(
            drain_leaf_tile.contains("topk_operator == GPU_PERSISTENT_TOPK_OPERATOR_WMMA_TF32"),
            "leaf tile consumer should dispatch WMMA TF32 inside the persistent kernel"
        );
        assert!(
            kernel.contains("unsigned int topk_operator"),
            "persistent kernel should accept the top-k operator selector as a launch argument"
        );
        assert!(
            kernel.contains("gpu_persistent_try_drain_leaf_tile_cta(")
                && kernel.contains("topk_operator"),
            "persistent top-k workers should pass the selector into the leaf tile consumer"
        );
    }

