    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_wmma_tf32_defaults_to_per_warp_b() {
        static ENV_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
        let _guard = ENV_LOCK.lock().unwrap();

        let old_cta_shared = std::env::var_os("SHEAR_PIPNN_WMMA_CTA_SHARED_B");
        let old_per_warp = std::env::var_os("SHEAR_PIPNN_WMMA_PER_WARP_B");

        unsafe {
            std::env::remove_var("SHEAR_PIPNN_WMMA_CTA_SHARED_B");
            std::env::remove_var("SHEAR_PIPNN_WMMA_PER_WARP_B");
        }

        assert!(
            !super::cuda_backend::persistent_wmma_cta_shared_b_enabled(),
            "unset WMMA B staging env should use per-warp-B by default; CTA-shared-B is diagnostic opt-in"
        );

        unsafe {
            match old_cta_shared {
                Some(value) => std::env::set_var("SHEAR_PIPNN_WMMA_CTA_SHARED_B", value),
                None => std::env::remove_var("SHEAR_PIPNN_WMMA_CTA_SHARED_B"),
            }
            match old_per_warp {
                Some(value) => std::env::set_var("SHEAR_PIPNN_WMMA_PER_WARP_B", value),
                None => std::env::remove_var("SHEAR_PIPNN_WMMA_PER_WARP_B"),
            }
        }
    }

