    #[test]
    fn persistent_topk_operator_code_maps_implemented_persistent_modes() {
        assert_eq!(
            super::persistent_topk_operator_code(
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentCustom
            )
            .unwrap(),
            Some(super::GPU_PERSISTENT_TOPK_OPERATOR_CUSTOM_FP32)
        );
        assert_eq!(
            super::persistent_topk_operator_code(
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentTiledGemmFp32
            )
            .unwrap(),
            Some(super::GPU_PERSISTENT_TOPK_OPERATOR_TILED_GEMM_FP32)
        );
        assert_eq!(
            super::persistent_topk_operator_code(
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::CuvsBruteforce
            )
            .unwrap(),
            Some(super::GPU_PERSISTENT_TOPK_OPERATOR_CUVS_BRUTEFORCE_FP32)
        );
        assert_eq!(
            super::persistent_topk_operator_code(
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32
            )
            .unwrap(),
            Some(super::GPU_PERSISTENT_TOPK_OPERATOR_WMMA_TF32)
        );

        let blockselect_err = super::persistent_topk_operator_code(
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentBlockselectFp32,
        )
        .unwrap_err()
        .to_string();
        assert!(blockselect_err.contains("persistent-blockselect-fp32"));
        assert!(blockselect_err.contains("not implemented yet"));
    }

