    #[test]
    fn persistent_leaf_rabitq_split_filter_requires_1bit_7bit_fht_kac() {
        let mut params = crate::algorithm::pipnn::params::PiPNNParams::default();
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_dco_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoMode::RabitqSplitFilter;
        params.gpu_subtree_leaf_dco_survivors = 16;
        params.gpu_subtree_rabitq_plus_bits = 8;
        params.gpu_subtree_rabitq_plus_rotator =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeRabitqPlusRotator::FhtKac;
        params.gpu_subtree_rabitq_plus_sidecar_prefix =
            Some(std::path::PathBuf::from("/tmp/wiki.rabitq8split"));
        super::validate_persistent_leaf_dco_config(&params, false).unwrap();

        let mut bad_bits = params.clone();
        bad_bits.gpu_subtree_rabitq_plus_bits = 7;
        let err = super::validate_persistent_leaf_dco_config(&bad_bits, false)
            .unwrap_err()
            .to_string();
        assert!(err.contains("1bit+7bit"));

        let mut bad_rotator = params.clone();
        bad_rotator.gpu_subtree_rabitq_plus_rotator =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeRabitqPlusRotator::None;
        let err = super::validate_persistent_leaf_dco_config(&bad_rotator, false)
            .unwrap_err()
            .to_string();
        assert!(err.contains("fht_kac"));
    }

