    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_assignment_operator_is_kernel_wired() {
        let source = super::cuda_backend::GPU_PERSISTENT_SUBTREE_KERNEL_SRC;
        let kernel = source
            .split("extern \"C\" __global__ void gpu_persistent_subtree_topk(")
            .nth(1)
            .expect("persistent subtree kernel should exist");
        let small_node = source
            .split("static __device__ void gpu_persistent_process_node")
            .nth(1)
            .and_then(|tail| {
                tail.split("static __device__ void gpu_persistent_process_large_node")
                    .next()
            })
            .expect("small-node process helper should exist");
        let large_node = source
            .split("static __device__ void gpu_persistent_process_large_node")
            .nth(1)
            .and_then(|tail| {
                tail.split("static __device__ void gpu_persistent_large_best_slots4")
                    .next()
            })
            .expect("large-node process helper should exist");
        let large_best = source
            .split("static __device__ void gpu_persistent_large_best_slots4")
            .nth(1)
            .and_then(|tail| {
                tail.split("static __device__ bool gpu_persistent_process_large_task_cta")
                    .next()
            })
            .expect("large-task assignment helper should exist");
        let rust_source = include_str!("compute_backend.rs");

        assert!(source.contains("GPU_PERSISTENT_ASSIGNMENT_OPERATOR_CURRENT = 0u"));
        assert!(source.contains("GPU_PERSISTENT_ASSIGNMENT_OPERATOR_TILED_GEMM_FP32 = 1u"));
        assert!(source.contains("GPU_PERSISTENT_ASSIGNMENT_OPERATOR_CUVS_BRUTEFORCE_FP32 = 2u"));
        assert!(source.contains("GPU_PERSISTENT_ASSIGNMENT_OPERATOR_WMMA_TF32 = 3u"));
        assert!(source.contains("gpu_persistent_assignment_best_slots4"));
        assert!(kernel.contains("unsigned int assignment_operator"));
        assert!(small_node.contains("unsigned int assignment_operator"));
        assert!(large_node.contains("unsigned int assignment_operator"));
        assert!(large_best.contains("unsigned int assignment_operator"));
        assert!(small_node.contains("gpu_persistent_assignment_best_slots4"));
        assert!(large_node.contains("gpu_persistent_assignment_best_slots4"));
        assert!(large_best.contains("gpu_persistent_assignment_best_slots4"));
        assert!(rust_source.contains("assignment_operator_u32"));
        assert!(rust_source.contains("params.gpu_subtree_assignment_backend"));
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_assignment_dco_projection_is_kernel_wired() {
        let source = super::cuda_backend::GPU_PERSISTENT_SUBTREE_KERNEL_SRC;
        let rust_source = include_str!("compute_backend.rs");
        let kernel = source
            .split("extern \"C\" __global__ void gpu_persistent_subtree_topk(")
            .nth(1)
            .expect("persistent subtree kernel should exist");
        let helper = source
            .split("static __device__ void gpu_persistent_assignment_best_slots4_dco_enabled")
            .nth(1)
            .and_then(|tail| {
                tail.split("static __device__ float gpu_persistent_adaptive_psamp_fraction")
                    .next()
            })
            .expect("assignment helper should exist");
        let dispatcher = source
            .split("static __device__ void gpu_persistent_large_task_compute_tile_slots4")
            .nth(1)
            .and_then(|tail| {
                tail.split("static __device__ bool gpu_persistent_process_large_task_cta")
                    .next()
            })
            .expect("large-task assignment dispatcher should exist");
        let wmma_fast_worker = source
            .split("static __device__ void gpu_persistent_large_task_wmma_tf32_best_slots4")
            .nth(1)
            .and_then(|tail| {
                tail.split(
                    "static __device__ void gpu_persistent_large_task_wmma_tf32_quantized_dco_best_slots4",
                )
                .next()
            })
            .expect("no-DCO WMMA assignment worker should exist");
        assert!(source.contains("GPU_PERSISTENT_ASSIGNMENT_DCO_PREFIX_PROJECTION = 1u"));
        assert!(source.contains("GPU_PERSISTENT_ASSIGNMENT_DCO_QUANTIZED = 2u"));
        assert!(source.contains("GPU_PERSISTENT_ASSIGNMENT_DCO_ENABLE"));
        assert!(source.contains("GPU_PERSISTENT_ASSIGNMENT_DCO_MAX_SURVIVORS = 32u"));
        assert!(source.contains("GPU_PERSISTENT_ASSIGNMENT_WMMA_DCO_MAX_SURVIVORS = 4u"));
        assert!(source.contains("P_ASSIGNMENT_DCO_PREFILTER_PAIRS"));
        assert!(source.contains("P_ASSIGNMENT_DCO_FALSE_PRUNE_AUDIT_MISSES"));
        assert!(kernel.contains("unsigned int assignment_dco_mode"));
        assert!(kernel.contains("unsigned int assignment_dco_rerank_mode"));
        assert!(kernel.contains("unsigned int assignment_dco_proj_dim"));
        assert!(kernel.contains("unsigned int assignment_dco_survivors"));
        assert!(kernel.contains("unsigned int assignment_dco_audit"));
        assert!(source.contains("gpu_persistent_assignment_projected_l2"));
        assert!(source.contains("gpu_persistent_assignment_quantized_projected_l2"));
        assert!(source.contains("gpu_persistent_assignment_quantized_projected_norm"));
        assert!(source.contains("gpu_persistent_assignment_quantized_value"));
        assert!(source.contains("#if GPU_PERSISTENT_ASSIGNMENT_DCO_ENABLE"));
        assert!(helper.contains("survivor_dist[GPU_PERSISTENT_ASSIGNMENT_DCO_MAX_SURVIVORS]"));
        assert!(!wmma_fast_worker.contains("assignment_dco_mode"));
        assert!(!wmma_fast_worker.contains("gpu_persistent_assignment_quantized_value"));
        assert!(
            helper.contains(
                "assignment_dco_rerank_mode == GPU_PERSISTENT_ASSIGNMENT_DCO_RERANK_NONE"
            )
        );
        assert!(helper.contains("P_ASSIGNMENT_DCO_EXACT_PAIRS"));
        assert!(helper.contains("P_ASSIGNMENT_DCO_APPROX_OUTPUT_PAIRS"));
        assert!(helper.contains("P_ASSIGNMENT_DCO_FALSE_PRUNE_AUDIT_PAIRS"));
        assert!(
            dispatcher.contains("assignment_dco_mode == GPU_PERSISTENT_ASSIGNMENT_DCO_NONE")
                && dispatcher.contains("gpu_persistent_large_task_wmma_tf32_best_slots4")
                && dispatcher.contains("gpu_persistent_large_best_slots4"),
            "no-DCO WMMA should stay on the fast worker, while quantized and other DCO modes should use the common survivor/rerank helper until the dedicated quantized WMMA worker is resource-safe"
        );
        assert!(rust_source.contains("assignment_dco_mode_u32"));
        assert!(rust_source.contains("assignment_dco_source_enabled"));
        assert!(rust_source.contains("-DGPU_PERSISTENT_ASSIGNMENT_DCO_ENABLE=1"));
        assert!(rust_source.contains("params.gpu_subtree_assignment_dco_mode"));
        assert!(rust_source.contains(".arg(&assignment_dco_mode_u32)"));
        assert!(rust_source.contains("assignment_dco: GpuSubtreeAssignmentDcoTelemetry"));
    }

