    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_kernel_nvrtc_compiles_scheduler_modes() {
        let include_paths = super::cuda_backend::persistent_subtree_nvrtc_include_paths();
        assert!(
            !include_paths.is_empty(),
            "CUDA include path with mma.h is required for scheduler-mode NVRTC checks"
        );
        for (mode, mode_options) in [
            ("baseline", Vec::<String>::new()),
            (
                "local-counters",
                vec!["-DGPU_PERSISTENT_TOPK_LOCAL_COUNTERS=1".to_string()],
            ),
            (
                "local-counters-barrier",
                vec![
                    "-DGPU_PERSISTENT_TOPK_LOCAL_COUNTERS=1".to_string(),
                    "-DGPU_PERSISTENT_TOPK_BARRIER_CLEANUP=1".to_string(),
                ],
            ),
            (
                "adaptive-idle",
                vec![
                    "-DGPU_PERSISTENT_TOPK_LOCAL_COUNTERS=1".to_string(),
                    "-DGPU_PERSISTENT_TOPK_BARRIER_CLEANUP=1".to_string(),
                    "-DGPU_PERSISTENT_TOPK_IDLE_BACKOFF=1".to_string(),
                ],
            ),
        ] {
            let mut options = vec!["--std=c++17".to_string()];
            options.extend(mode_options);
            cudarc::nvrtc::compile_ptx_with_opts(
                super::cuda_backend::GPU_PERSISTENT_SUBTREE_KERNEL_SRC,
                cudarc::nvrtc::CompileOptions {
                    arch: Some("compute_80"),
                    include_paths: include_paths.clone(),
                    options,
                    ..cudarc::nvrtc::CompileOptions::default()
                },
            )
            .unwrap_or_else(|err| panic!("persistent scheduler mode {mode} must compile: {err}"));
        }
    }

