    #[test]
    #[ignore = "loads the persistent SQ native-int4 CUDA module on device 0"]
    fn cuda_persistent_subtree_kernel_loads_with_sq_native_int4_on_device() {
        let context = cudarc::driver::CudaContext::new(0).expect("CUDA device 0 context");
        let (major, minor) = context
            .compute_capability()
            .expect("CUDA device 0 compute capability");
        let arch = match (major, minor) {
            (8, 0) => "compute_80",
            (8, 6) => "compute_86",
            (8, 7) => "compute_87",
            (8, 9) => "compute_89",
            (9, _) => "compute_90",
            (major, _) if major > 9 => "compute_90",
            other => panic!(
                "persistent SQ native-int4 device-load test requires SM80+, got {}.{}",
                other.0, other.1
            ),
        };
        let ptx = cudarc::nvrtc::compile_ptx_with_opts(
            super::cuda_backend::GPU_PERSISTENT_SUBTREE_KERNEL_SRC,
            cudarc::nvrtc::CompileOptions {
                arch: Some(arch),
                include_paths: super::cuda_backend::persistent_subtree_nvrtc_include_paths(),
                options: vec![
                    "--std=c++17".to_string(),
                    "-DGPU_PERSISTENT_LEAF_DCO_ENABLE=1".to_string(),
                    "-DGPU_PERSISTENT_LEAF_SQ_INT4_WMMA_ENABLE=1".to_string(),
                ],
                ..cudarc::nvrtc::CompileOptions::default()
            },
        )
        .expect(
            "persistent subtree SQ native-int4 CUDA source should compile with runtime options",
        );
        if let Ok(path) = std::env::var("SHEAR_PIPNN_DUMP_PERSISTENT_PTX") {
            std::fs::write(&path, ptx.to_src()).expect("write persistent SQ native-int4 PTX dump");
        }
        let module = context
            .load_module(ptx)
            .expect("persistent subtree SQ native-int4 PTX should load on device");
        module
            .load_function("gpu_persistent_subtree_topk")
            .expect("persistent subtree top-k function should load");
    }

