    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_rabitq_split_short_ex_child_local_topk_matches_cpu_reference() {
        let header = RabitqResidualPayloadHeader {
            rows: 4,
            dim: 4,
            padded_dim: 4,
            centroid_count: 1,
            code_row_bytes: 4,
        };
        let mut dense = RabitqResidualPayloadStore::new(header).unwrap();
        dense
            .set_centroids_row_major(&[0.0, 0.0, 0.0, 0.0])
            .unwrap();
        dense
            .write_shard(&RabitqResidualShardPayload {
                global_ids: vec![0, 1, 2, 3],
                centroid_ids: vec![0, 0, 0, 0],
                codes: vec![
                    0, 1, 2, 3, //
                    1, 2, 3, 4, //
                    8, 7, 6, 5, //
                    -1, -2, -3, -4,
                ],
                residual_norms: vec![1.0, 2.0, 3.0, 4.0],
                scales: vec![1.0, 1.0, 1.0, 1.0],
                code_sums: vec![6.0, 10.0, 26.0, -10.0],
                original_norms: vec![1.0, 2.0, 3.0, 4.0],
                code_row_bytes: 4,
            })
            .unwrap();
        let split = RabitqResidualSplitPayloadStore::from_dense_payload(&dense).unwrap();
        let child_ids = [0_u32, 1, 2, 3];
        let (expected_ids, expected_dists) =
            resident_rabitq_split_short_ex_topk_reference(&split, &child_ids, 2, 3).unwrap();
        let Ok(backend) = super::cuda_backend::CudaComputeBackend::new(0, &PiPNNParams::default())
        else {
            eprintln!("CUDA device 0 unavailable; skipping split short/ex smoke");
            return;
        };

        let (batch, _, _, _, _) = backend
            .run_child_local_rabitq_split_short_ex_topk_for_test(&split, &child_ids, 2, Some(3))
            .unwrap();

        assert_eq!(batch.topk_ids, expected_ids);
        for (actual, expected) in batch.topk_dists.iter().zip(expected_dists) {
            assert!(
                (actual - expected).abs() <= 1.0e-4,
                "actual={actual} expected={expected}"
            );
        }
    }

