    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_turboquant_rerank_gates_global_id_load_before_survivor_insert() {
        let source = super::cuda_backend::GPU_PERSISTENT_SUBTREE_KERNEL_SRC;
        let turboquant_filter = source
            .split(
                "static __device__ void gpu_persistent_compute_topk_leaf_tile_cta_turboquant_mse4",
            )
            .nth(1)
            .and_then(|tail| {
                tail.split("static __device__ bool gpu_persistent_try_drain_leaf_tile_cta")
                    .next()
            })
            .expect("TurboQuant-MSE4 leaf filter source should be present");

        let gate_offset = turboquant_filter
            .find("gpu_persistent_leaf_survivor_may_beat_worst_by_distance_fp32(")
            .expect("TQ rerank prefilter should gate global-id loads by distance first");
        let global_id_offset = turboquant_filter
            .find("unsigned int global_j = resident_global_ids[local_j];")
            .expect("TQ rerank still needs global ids for stable tie handling");
        assert!(
            gate_offset < global_id_offset,
            "TQ rerank should avoid loading global ids for candidates that cannot enter survivor set"
        );
        assert!(source.contains("gpu_persistent_leaf_insert_survivor_unsorted_fp32"));
        assert!(turboquant_filter.contains("gpu_persistent_leaf_insert_survivor_unsorted_fp32"));
        assert!(!turboquant_filter.contains(
            "gpu_persistent_leaf_insert_survivor_fp32(\n                        approx_dist"
        ));
    }

