    fn plan_rabitq_d0_tiled_assign_rejects_invalid_shapes() {
        assert!(super::plan_rabitq_d0_tiled_assign(10, 8, 4, 0, 8, 4).is_err());
        assert!(super::plan_rabitq_d0_tiled_assign(10, 8, 4, 4, 0, 4).is_err());
        assert!(super::plan_rabitq_d0_tiled_assign(10, 8, 4, 4, 8, 0).is_err());
        assert!(super::plan_rabitq_d0_tiled_assign(10, 8, 4, 4, 8, 3).is_err());
    }

