    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_two_stage_wmma_tf32_matches_fused_for_synthetic_subtree() {
        let rows = 129;
        let dim = 3;
        let mut dataset = InmemDataset::new(rows, 1.0, dim).expect("dataset");
        dataset
            .data
            .copy_from_slice(&queue_shadow_test_vectors(rows, dim));
        let store = InmemDatasetPointStore::new(&dataset, rows);
        let point_ids: Vec<u32> = (0..rows as u32).collect();
        let mut params = PiPNNParams::default();
        params.leaf_knn = 2;
        params.c_min = 4;
        params.c_max = 128;
        params.max_depth = 6;
        params.max_leaders = 6;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.psamp_fraction = 1.0;
        params.gpu_workspace_budget_bytes = 64 * 1024 * 1024;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &point_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: rows,
            adaptive_c_max: 128,
            min_recurse_size: 32,
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };
        let backend = super::cuda_backend::build_cuda_backend(0, &params).expect("CUDA backend");

        let fused = backend
            .process_subtree_l2_compact_topk(&store, &request, &params)
            .expect("fused persistent subtree top-k");
        let mut two_stage_params = params.clone();
        two_stage_params.gpu_subtree_execution_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeExecutionMode::TwoStage;
        let two_stage = backend
            .process_subtree_l2_compact_topk(&store, &request, &two_stage_params)
            .expect("two-stage persistent subtree top-k");

        assert_eq!(two_stage.compact_batches.len(), fused.compact_batches.len());
        for (actual, expected) in two_stage
            .compact_batches
            .iter()
            .zip(fused.compact_batches.iter())
        {
            assert_eq!(actual.point_ids, expected.point_ids);
            assert_eq!(actual.rows, expected.rows);
            assert_eq!(actual.k, expected.k);
            assert_eq!(actual.topk_ids, expected.topk_ids);
            assert_eq!(actual.topk_dists, expected.topk_dists);
        }
        assert_eq!(two_stage.profile.persistent_attempt_count, 1);
        assert_eq!(two_stage.profile.persistent_success_count, 1);
        assert_eq!(two_stage.profile.persistent_fallback_count, 0);
        assert_eq!(two_stage.profile.persistent_queue_overflow_flags, 0);
        assert!(
            two_stage.profile.partition_only_kernel_event_wall > Duration::ZERO,
            "profile={:?}",
            two_stage.profile
        );
        assert!(
            two_stage.profile.partition_only_total_wall > Duration::ZERO,
            "profile={:?}",
            two_stage.profile
        );
        assert!(
            two_stage.profile.resident_topk_kernel_event_wall > Duration::ZERO,
            "profile={:?}",
            two_stage.profile
        );
        assert_eq!(
            two_stage.profile.persistent_leaf_pushes,
            two_stage.profile.persistent_topk_pops
        );
        assert_eq!(
            two_stage.profile.persistent_leaf_count,
            fused.profile.persistent_leaf_count
        );
        assert_eq!(
            two_stage.profile.persistent_topk_rows,
            fused.profile.persistent_topk_rows
        );
    }

