    #[cfg(feature = "pipnn_cuda")]
    fn run_cuda_persistent_subtree_assignment_backend(
        assignment_backend: crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend,
    ) {
        let rows = 32usize;
        let dim = 8usize;
        let mut dataset = InmemDataset::new(rows, 1.0, dim).expect("dataset");
        for row in 0..rows {
            for axis in 0..dim {
                let mixed = (row as u32)
                    .wrapping_mul(1_664_525)
                    .wrapping_add((axis as u32).wrapping_mul(1_013_904_223))
                    .rotate_left(((row + axis) % 19) as u32);
                dataset.data[row * dim + axis] =
                    ((mixed & 0xffff) as f32 / 65_535.0) + row as f32 * 0.000_137;
            }
        }
        let store = InmemDatasetPointStore::new(&dataset, rows);
        let mut params = PiPNNParams::default();
        params.leaf_knn = 2;
        params.c_min = 4;
        params.c_max = 8;
        params.max_depth = 6;
        params.max_leaders = 4;
        params.fanout_top = 1;
        params.fanout_second = 2;
        params.psamp_fraction = 1.0;
        params.gpu_workspace_budget_bytes = 128 * 1024 * 1024;
        params.gpu_subtree_assignment_backend = assignment_backend;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentCustom;
        let point_ids: Vec<u32> = (0..rows as u32).collect();
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &point_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: rows,
            adaptive_c_max: 8,
            min_recurse_size: 16,
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };
        let backend =
            super::cuda_backend::CudaComputeBackend::new(0, &params).expect("CUDA backend");

        let result = backend
            .process_subtree_l2_compact_topk(&store, &request, &params)
            .unwrap_or_else(|err| {
                panic!("persistent assignment backend {assignment_backend} should run: {err}")
            });

        assert_eq!(result.profile.assignment_backend, assignment_backend);
        assert_eq!(
            result.profile.leaf_topk_backend,
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentCustom
        );
        assert_eq!(result.profile.persistent_attempt_count, 1);
        assert_eq!(result.profile.persistent_success_count, 1);
        assert_eq!(result.profile.persistent_fallback_count, 0);
        assert_eq!(result.profile.persistent_queue_overflow_flags, 0);
        assert!(result.assignment_passes > 0);
        assert!(result.profile.persistent_fanout_assignment_slots >= rows);
        assert!(result.profile.persistent_replicated_rows >= rows);
        assert!(result.profile.persistent_partition_pops > 0);
        assert!(result.profile.persistent_leaf_pushes > 0);
        assert_eq!(result.profile.assignment_kernel_wall, Duration::ZERO);
        assert_eq!(result.profile.assignment_d2h_wall, Duration::ZERO);
        assert_eq!(
            result
                .compact_batches
                .iter()
                .map(|batch| batch.rows)
                .sum::<usize>(),
            result.profile.persistent_topk_rows
        );
        assert_eq!(
            result.compact_batches.len(),
            result.profile.persistent_leaf_count
        );
        assert!(result.profile.persistent_topk_rows >= rows);
        for batch in &result.compact_batches {
            let expected = compute_leaf_topk_l2_cpu_shadow(&store, &batch.point_ids, &params)
                .expect("CPU shadow for fixed-assignment persistent leaf")
                .0;
            assert_eq!(batch.point_ids, expected.point_ids);
            assert_eq!(batch.rows, expected.rows);
            assert_eq!(batch.k, expected.k);
            assert_eq!(batch.topk_ids, expected.topk_ids);
            assert_eq!(batch.topk_dists, expected.topk_dists);
        }
    }

