    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_rabitq_plus_build_runs_quantized_only_resident_pipeline() {
        let rows = 64usize;
        let dim = 16usize;
        let x_row_major = synthetic_leaf_replay_vectors(rows, dim);
        let norms: Vec<f32> = x_row_major
            .chunks(dim)
            .map(|row| row.iter().map(|&value| value * value).sum())
            .collect();
        let global_ids: Vec<u32> = (0..rows as u32).collect();
        let rabitq_plus = crate::algorithm::pipnn::dco_rabitq::quantize_rabitq_plus_matrix(
            &x_row_major,
            rows,
            dim,
            8,
            crate::algorithm::pipnn::dco_rabitq::RABITQ_DEFAULT_K_ALIGN,
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeRabitqPlusRotator::FhtKac,
            123,
        )
        .expect("dense-i8 RabitQ+ quantization should succeed");
        let quantized = GpuSubtreeQuantizedInput {
            distance_kind: GpuSubtreeQuantizedDistanceKind::RabitqPlus,
            global_ids: &global_ids,
            codes: &rabitq_plus.codes,
            deltas: &rabitq_plus.deltas,
            code_sums: &rabitq_plus.code_sums,
            norms: &norms,
            dim,
            padded_dim: rabitq_plus.padded_dim,
            code_layout: GpuSubtreeQuantizedCodeLayout::DenseI8,
            code_row_bytes: rabitq_plus.padded_dim,
            bits: rabitq_plus.total_bits,
        };
        let mut params = PiPNNParams::default();
        params.random_seed = 123;
        params.leaf_knn = 2;
        params.c_min = rows;
        params.c_max = rows;
        params.max_depth = 1;
        params.max_leaders = 2;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.psamp_fraction = 1.0;
        params.gpu_workspace_budget_bytes = 128 * 1024 * 1024;
        params.gpu_subtree_assignment_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        params.gpu_subtree_rabitq_plus_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeRabitqPlusMode::Build;
        params.gpu_subtree_rabitq_plus_bits = 8;
        params.gpu_subtree_rabitq_plus_rotator =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeRabitqPlusRotator::FhtKac;
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &global_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: rows,
            adaptive_c_max: rows,
            min_recurse_size: rows,
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };
        let backend =
            super::cuda_backend::CudaComputeBackend::new(0, &params).expect("CUDA backend");

        let result = backend
            .process_quantized_subtree_l2_compact_topk(&request, quantized, &params)
            .unwrap_or_else(|err| {
                panic!("dense-i8 RabitQ+ quantized-only subtree should run: {err}")
            });

        assert_eq!(result.profile.persistent_success_count, 1);
        assert!(!result.compact_batches.is_empty());
        assert!(
            result
                .compact_batches
                .iter()
                .map(|batch| batch.rows)
                .sum::<usize>()
                > 0
        );
        let expected_metadata_bytes =
            rows * std::mem::size_of::<u32>() + rows * std::mem::size_of::<f32>();
        let expected_code_bytes = rabitq_plus.codes.len() * std::mem::size_of::<i8>()
            + rows * std::mem::size_of::<f32>()
            + rows * std::mem::size_of::<f32>();
        assert_eq!(
            result.profile.resident_h2d_bytes,
            expected_metadata_bytes + expected_code_bytes
        );
        assert_eq!(result.profile.rabitq_plus_code_bytes, expected_code_bytes);
        assert_eq!(result.profile.subtree_vector_h2d_wall, Duration::ZERO);
        assert_eq!(
            result.profile.raw_resident_h2d_bytes_saved_estimate,
            rows * dim * std::mem::size_of::<f32>()
        );
        assert_eq!(result.profile.leaf_dco.exact_fallback_rows, 0);
        assert_eq!(result.profile.rabitq_plus_rows, rows);
        assert_eq!(result.profile.rabitq_plus_padded_dim, dim);
        assert!(result.profile.rabitq_plus_code_bytes >= rows * dim);
        assert!(result.profile.rabitq_plus_h2d_wall >= Duration::ZERO);
        assert!(result.profile.rabitq_plus_kernel_event_wall >= Duration::ZERO);
        assert!(
            result
                .compact_batches
                .iter()
                .all(|batch| batch.k == params.leaf_knn)
        );
        assert!(
            result
                .compact_batches
                .iter()
                .flat_map(|batch| batch.topk_ids.iter())
                .any(|&id| id != u32::MAX)
        );
    }

