    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_turboquant_build_runs_low_dim_no_rerank_resident_pipeline() {
        let rows = 64usize;
        let dim = 16usize;
        let x_row_major = synthetic_leaf_replay_vectors(rows, dim);
        let global_ids: Vec<u32> = (0..rows as u32).collect();
        let turboquant = crate::algorithm::pipnn::dco_turboquant::quantize_turboquant_mse4_matrix(
            &x_row_major,
            rows,
            dim,
            4,
            123,
        )
        .expect("TurboQuant-MSE4 quantization should succeed");
        let zero_side_terms = vec![0.0_f32; rows];
        let quantized = GpuSubtreeQuantizedInput {
            distance_kind: GpuSubtreeQuantizedDistanceKind::TurboQuantMse4,
            global_ids: &global_ids,
            codes: &turboquant.codes,
            deltas: &zero_side_terms,
            code_sums: &zero_side_terms,
            norms: &turboquant.norms,
            dim,
            padded_dim: dim,
            code_layout: GpuSubtreeQuantizedCodeLayout::PackedS4,
            code_row_bytes: turboquant.code_bytes_per_row,
            bits: 4,
        };
        let mut params = PiPNNParams::default();
        params.random_seed = 123;
        params.leaf_knn = 2;
        params.c_min = rows;
        params.c_max = rows;
        params.max_depth = 1;
        params.max_leaders = 2;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.psamp_fraction = 1.0;
        params.gpu_workspace_budget_bytes = 128 * 1024 * 1024;
        params.gpu_subtree_assignment_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        params.gpu_subtree_turboquant_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeTurboQuantMode::Build;
        params.gpu_subtree_turboquant_bits = 4;
        params.gpu_subtree_turboquant_seed = 123;
        params.gpu_subtree_turboquant_cascade_low_dim = 8;
        params.gpu_subtree_turboquant_cascade_survivor_cap = 0;
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &global_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: rows,
            adaptive_c_max: rows,
            min_recurse_size: rows,
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };
        let Ok(backend) = super::cuda_backend::CudaComputeBackend::new(0, &params) else {
            eprintln!("CUDA device 0 unavailable; skipping TurboQuant-MSE4 resident smoke");
            return;
        };

        let result = backend
            .process_quantized_subtree_l2_compact_topk(&request, quantized, &params)
            .unwrap_or_else(|err| {
                panic!("TurboQuant-MSE4 quantized-only subtree should run: {err}")
            });

        let expected_metadata_bytes =
            rows * std::mem::size_of::<u32>() + rows * std::mem::size_of::<f32>();
        let expected_code_bytes = turboquant.codes.len() * std::mem::size_of::<i8>()
            + rows * std::mem::size_of::<f32>()
            + rows * std::mem::size_of::<f32>();
        assert_eq!(result.profile.persistent_success_count, 1);
        assert_eq!(
            result.profile.resident_h2d_bytes,
            expected_metadata_bytes + expected_code_bytes
        );
        assert_eq!(result.profile.turboquant_rows, rows);
        assert_eq!(result.profile.turboquant_padded_dim, dim);
        assert_eq!(result.profile.turboquant_code_bytes, expected_code_bytes);
        assert_eq!(result.profile.turboquant_cascade_low_dim, 8);
        assert_eq!(result.profile.turboquant_cascade_survivor_cap, 0);
        assert_eq!(result.profile.rabitq_plus_rows, 0);
        assert_eq!(result.profile.sq_wmma_rows, 0);
        assert_eq!(result.profile.subtree_vector_h2d_wall, Duration::ZERO);
        assert_eq!(
            result.profile.raw_resident_h2d_bytes_saved_estimate,
            rows * dim * std::mem::size_of::<f32>()
        );
        assert_eq!(result.profile.leaf_dco.exact_fallback_rows, 0);
        assert!(
            result
                .compact_batches
                .iter()
                .all(|batch| batch.k == params.leaf_knn)
        );
        assert!(
            result
                .compact_batches
                .iter()
                .flat_map(|batch| batch.topk_ids.iter())
                .any(|&id| id != u32::MAX)
        );
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_turboquant_low_dim_matches_cpu_reference() {
        let Ok(backend) = super::cuda_backend::CudaComputeBackend::new(0, &PiPNNParams::default())
        else {
            eprintln!("CUDA device 0 unavailable; skipping TurboQuant-MSE4 low-D parity smoke");
            return;
        };
        let dim = 1024usize;
        let k = 3usize;

        for (rows, low_dim) in [(16usize, 128usize), (64, 128), (128, 256)] {
            let x_row_major = synthetic_leaf_replay_vectors(rows, dim);
            let global_ids: Vec<u32> = (0..rows as u32).collect();
            let turboquant =
                crate::algorithm::pipnn::dco_turboquant::quantize_turboquant_mse4_matrix(
                    &x_row_major,
                    rows,
                    dim,
                    4,
                    321,
                )
                .expect("TurboQuant-MSE4 quantization should succeed");
            let zero_side_terms = vec![0.0_f32; rows];
            let quantized = GpuSubtreeQuantizedInput {
                distance_kind: GpuSubtreeQuantizedDistanceKind::TurboQuantMse4,
                global_ids: &global_ids,
                codes: &turboquant.codes,
                deltas: &zero_side_terms,
                code_sums: &zero_side_terms,
                norms: &turboquant.norms,
                dim,
                padded_dim: dim,
                code_layout: GpuSubtreeQuantizedCodeLayout::PackedS4,
                code_row_bytes: turboquant.code_bytes_per_row,
                bits: 4,
            };
            let mut params = PiPNNParams::default();
            params.random_seed = 321;
            params.leaf_knn = k;
            params.c_min = rows;
            params.c_max = rows;
            params.max_depth = 1;
            params.max_leaders = 2;
            params.fanout_top = 1;
            params.fanout_second = 1;
            params.psamp_fraction = 1.0;
            params.gpu_workspace_budget_bytes = 128 * 1024 * 1024;
            params.gpu_subtree_assignment_backend =
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
            params.gpu_subtree_leaf_topk_backend =
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
            params.gpu_subtree_turboquant_mode =
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeTurboQuantMode::Build;
            params.gpu_subtree_turboquant_bits = 4;
            params.gpu_subtree_turboquant_seed = 321;
            params.gpu_subtree_turboquant_cascade_low_dim = low_dim;
            let request = super::GpuSubtreePartitionRequest {
                point_ids: &global_ids,
                root_leader_ids: None,
                depth: 1,
                parent_points: rows,
                adaptive_c_max: rows,
                min_recurse_size: rows,
                memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
            };

            let result = backend
                .process_quantized_subtree_l2_compact_topk(&request, quantized, &params)
                .unwrap_or_else(|err| {
                    panic!(
                        "TurboQuant-MSE4 low-D quantized-only subtree should run for rows={rows} low_dim={low_dim}: {err}"
                    )
                });

            assert_eq!(
                result
                    .compact_batches
                    .iter()
                    .map(|batch| batch.rows)
                    .sum::<usize>(),
                rows
            );
            for batch in &result.compact_batches {
                for (row, &point_id) in batch.point_ids.iter().enumerate() {
                    let actual = &batch.topk_ids[row * k..(row + 1) * k];
                    let mut expected = Vec::with_capacity(batch.rows.saturating_sub(1));
                    let lhs = point_id as usize;
                    let lhs_code = &turboquant.codes[lhs * turboquant.code_bytes_per_row
                        ..(lhs + 1) * turboquant.code_bytes_per_row];
                    for &candidate_id in &batch.point_ids {
                        if candidate_id == point_id {
                            continue;
                        }
                        let rhs = candidate_id as usize;
                        let rhs_code = &turboquant.codes[rhs * turboquant.code_bytes_per_row
                            ..(rhs + 1) * turboquant.code_bytes_per_row];
                        let dist =
                            crate::algorithm::pipnn::dco_turboquant::turboquant_mse4_approx_l2_low_dim(
                                lhs_code,
                                turboquant.norms[lhs],
                                rhs_code,
                                turboquant.norms[rhs],
                                dim,
                                low_dim,
                            );
                        expected.push((dist, candidate_id));
                    }
                    expected.sort_by(|left, right| {
                        crate::algorithm::pipnn::stable_distance_order(
                            left.0, left.1, right.0, right.1,
                        )
                    });
                    for slot in 0..k {
                        assert_eq!(
                            actual[slot], expected[slot].1,
                            "rows={rows} low_dim={low_dim} point_id={point_id} slot={slot}"
                        );
                    }
                }
            }
        }
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_turboquant_rerank_matches_cpu_reference() {
        let rows = 64usize;
        let dim = 1024usize;
        let k = 3usize;
        let low_dim = 128usize;
        let survivor_cap = 8usize;
        let x_row_major = synthetic_leaf_replay_vectors(rows, dim);
        let global_ids: Vec<u32> = (0..rows as u32).collect();
        let turboquant = crate::algorithm::pipnn::dco_turboquant::quantize_turboquant_mse4_matrix(
            &x_row_major,
            rows,
            dim,
            4,
            777,
        )
        .expect("TurboQuant-MSE4 quantization should succeed");
        let zero_side_terms = vec![0.0_f32; rows];
        let quantized = GpuSubtreeQuantizedInput {
            distance_kind: GpuSubtreeQuantizedDistanceKind::TurboQuantMse4,
            global_ids: &global_ids,
            codes: &turboquant.codes,
            deltas: &zero_side_terms,
            code_sums: &zero_side_terms,
            norms: &turboquant.norms,
            dim,
            padded_dim: dim,
            code_layout: GpuSubtreeQuantizedCodeLayout::PackedS4,
            code_row_bytes: turboquant.code_bytes_per_row,
            bits: 4,
        };
        let mut params = PiPNNParams::default();
        params.random_seed = 777;
        params.leaf_knn = k;
        params.c_min = rows;
        params.c_max = rows;
        params.max_depth = 1;
        params.max_leaders = 2;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.psamp_fraction = 1.0;
        params.gpu_workspace_budget_bytes = 128 * 1024 * 1024;
        params.gpu_subtree_assignment_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        params.gpu_subtree_turboquant_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeTurboQuantMode::Build;
        params.gpu_subtree_turboquant_bits = 4;
        params.gpu_subtree_turboquant_seed = 777;
        params.gpu_subtree_turboquant_cascade_low_dim = low_dim;
        params.gpu_subtree_turboquant_cascade_survivor_cap = survivor_cap;
        let Ok(backend) = super::cuda_backend::CudaComputeBackend::new(0, &params) else {
            eprintln!("CUDA device 0 unavailable; skipping TurboQuant-MSE4 rerank parity smoke");
            return;
        };
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &global_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: rows,
            adaptive_c_max: rows,
            min_recurse_size: rows,
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };

        let result = backend
            .process_quantized_subtree_l2_compact_topk(&request, quantized, &params)
            .unwrap_or_else(|err| panic!("TurboQuant-MSE4 rerank subtree should run: {err}"));

        assert_eq!(result.profile.turboquant_cascade_low_dim, low_dim);
        assert_eq!(result.profile.turboquant_cascade_survivor_cap, survivor_cap);
        assert!(result.profile.leaf_dco.exact_pairs > 0);
        for batch in &result.compact_batches {
            for (row, &point_id) in batch.point_ids.iter().enumerate() {
                let actual = &batch.topk_ids[row * k..(row + 1) * k];
                let lhs = point_id as usize;
                let lhs_code = &turboquant.codes[lhs * turboquant.code_bytes_per_row
                    ..(lhs + 1) * turboquant.code_bytes_per_row];
                let mut low_candidates = Vec::with_capacity(batch.rows.saturating_sub(1));
                for &candidate_id in &batch.point_ids {
                    if candidate_id == point_id {
                        continue;
                    }
                    let rhs = candidate_id as usize;
                    let rhs_code = &turboquant.codes[rhs * turboquant.code_bytes_per_row
                        ..(rhs + 1) * turboquant.code_bytes_per_row];
                    let low_dist =
                        crate::algorithm::pipnn::dco_turboquant::turboquant_mse4_approx_l2_low_dim(
                            lhs_code,
                            turboquant.norms[lhs],
                            rhs_code,
                            turboquant.norms[rhs],
                            dim,
                            low_dim,
                        );
                    low_candidates.push((low_dist, candidate_id));
                }
                low_candidates.sort_by(|left, right| {
                    crate::algorithm::pipnn::stable_distance_order(left.0, left.1, right.0, right.1)
                });
                let mut reranked = Vec::with_capacity(survivor_cap);
                for &(_, candidate_id) in low_candidates.iter().take(survivor_cap) {
                    let rhs = candidate_id as usize;
                    let rhs_code = &turboquant.codes[rhs * turboquant.code_bytes_per_row
                        ..(rhs + 1) * turboquant.code_bytes_per_row];
                    let full_dist =
                        crate::algorithm::pipnn::dco_turboquant::turboquant_mse4_approx_l2(
                            lhs_code,
                            turboquant.norms[lhs],
                            rhs_code,
                            turboquant.norms[rhs],
                            dim,
                        );
                    reranked.push((full_dist, candidate_id));
                }
                reranked.sort_by(|left, right| {
                    crate::algorithm::pipnn::stable_distance_order(left.0, left.1, right.0, right.1)
                });
                for slot in 0..k {
                    assert_eq!(
                        actual[slot], reranked[slot].1,
                        "point_id={point_id} slot={slot}"
                    );
                }
            }
        }
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_sq_wmma_build_runs_quantized_only_resident_pipeline() {
        let rows = 64usize;
        let dim = 16usize;
        let x_row_major = synthetic_leaf_replay_vectors(rows, dim);
        let global_ids: Vec<u32> = (0..rows as u32).collect();
        let sq = crate::algorithm::pipnn::dco_sq_int8::quantize_sq_int8_matrix(
            &x_row_major,
            rows,
            dim,
            crate::algorithm::pipnn::dco_sq_int8::SQ_INT8_DEFAULT_K_ALIGN,
        )
        .expect("SQ-int8 quantization should succeed");
        let code_sums = vec![0.0_f32; rows];
        let quantized = GpuSubtreeQuantizedInput {
            distance_kind: GpuSubtreeQuantizedDistanceKind::SqInt8,
            global_ids: &global_ids,
            codes: &sq.codes,
            deltas: &sq.scales,
            code_sums: &code_sums,
            norms: &sq.norms,
            dim,
            padded_dim: sq.padded_dim,
            code_layout: GpuSubtreeQuantizedCodeLayout::DenseI8,
            code_row_bytes: sq.padded_dim,
            bits: 8,
        };
        let mut params = PiPNNParams::default();
        params.random_seed = 123;
        params.leaf_knn = 2;
        params.c_min = rows;
        params.c_max = rows;
        params.max_depth = 1;
        params.max_leaders = 2;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.psamp_fraction = 1.0;
        params.gpu_workspace_budget_bytes = 128 * 1024 * 1024;
        params.gpu_subtree_assignment_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        params.gpu_subtree_sq_wmma_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeSqWmmaMode::Build;
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &global_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: rows,
            adaptive_c_max: rows,
            min_recurse_size: rows,
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };
        let backend =
            super::cuda_backend::CudaComputeBackend::new(0, &params).expect("CUDA backend");

        let fused = backend
            .process_quantized_subtree_l2_compact_topk(&request, quantized, &params)
            .unwrap_or_else(|err| panic!("SQ+WMMA quantized-only subtree should run: {err}"));
        let owned = OwnedGpuSubtreeQuantizedInput {
            distance_kind: GpuSubtreeQuantizedDistanceKind::SqInt8,
            global_ids: Arc::new(global_ids.clone()),
            codes: Arc::new(sq.codes.clone()),
            deltas: Arc::new(sq.scales.clone()),
            code_sums: Arc::new(code_sums.clone()),
            norms: Arc::new(sq.norms.clone()),
            dim,
            padded_dim: sq.padded_dim,
            code_layout: GpuSubtreeQuantizedCodeLayout::DenseI8,
            code_row_bytes: sq.padded_dim,
            bits: 8,
        };
        let deferred = match backend
            .submit_owned_quantized_subtree_l2_compact_topk(&request, owned, &params)
            .expect("deferred SQ+WMMA submission")
        {
            GpuSubtreeTopKSubmission::Deferred(deferred) => deferred,
            GpuSubtreeTopKSubmission::Ready(_) => {
                panic!("CUDA owned submission must defer host scatter")
            }
        };
        assert!(deferred.estimated_host_bytes > 0);
        let deferred_result = deferred.scatter.finish().expect("deferred scatter");
        assert_eq!(
            deferred_result.compact_batches.len(),
            fused.compact_batches.len()
        );
        for (actual, expected) in deferred_result
            .compact_batches
            .iter()
            .zip(fused.compact_batches.iter())
        {
            assert_eq!(actual.point_ids, expected.point_ids);
            assert_eq!(actual.rows, expected.rows);
            assert_eq!(actual.k, expected.k);
            assert_eq!(actual.topk_ids, expected.topk_ids);
            assert_eq!(actual.topk_dists, expected.topk_dists);
        }
        assert_eq!(deferred_result.profile.persistent_success_count, 1);
        assert!(deferred_result.profile.cpu_result_scatter_wall > Duration::ZERO);
        let mut two_stage_params = params.clone();
        two_stage_params.gpu_subtree_execution_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeExecutionMode::TwoStage;
        let two_stage = backend
            .process_quantized_subtree_l2_compact_topk(&request, quantized, &two_stage_params)
            .unwrap_or_else(|err| {
                panic!("two-stage SQ+WMMA quantized-only subtree should run: {err}")
            });

        let expected_metadata_bytes =
            rows * std::mem::size_of::<u32>() + rows * std::mem::size_of::<f32>();
        let expected_code_bytes = sq.codes.len() * std::mem::size_of::<i8>()
            + rows * std::mem::size_of::<f32>()
            + rows * std::mem::size_of::<f32>();
        assert_eq!(fused.profile.persistent_success_count, 1);
        assert_eq!(
            fused.profile.resident_h2d_bytes,
            expected_metadata_bytes + expected_code_bytes
        );
        assert_eq!(fused.profile.sq_wmma_rows, rows);
        assert_eq!(fused.profile.sq_wmma_padded_dim, sq.padded_dim);
        assert_eq!(fused.profile.sq_wmma_code_bytes, expected_code_bytes);
        assert_eq!(fused.profile.rabitq_plus_rows, 0);
        assert_eq!(fused.profile.subtree_vector_h2d_wall, Duration::ZERO);
        assert_eq!(
            fused.profile.raw_resident_h2d_bytes_saved_estimate,
            rows * dim * std::mem::size_of::<f32>()
        );
        assert_eq!(fused.profile.leaf_dco.exact_fallback_rows, 0);
        assert!(
            fused
                .compact_batches
                .iter()
                .flat_map(|batch| batch.topk_ids.iter())
                .any(|&id| id != u32::MAX)
        );
        assert_eq!(two_stage.compact_batches.len(), fused.compact_batches.len());
        for (actual, expected) in two_stage
            .compact_batches
            .iter()
            .zip(fused.compact_batches.iter())
        {
            assert_eq!(actual.point_ids, expected.point_ids);
            assert_eq!(actual.rows, expected.rows);
            assert_eq!(actual.k, expected.k);
            assert_eq!(actual.topk_ids, expected.topk_ids);
        }
        assert_eq!(two_stage.profile.persistent_success_count, 1);
        assert!(two_stage.profile.partition_only_kernel_event_wall > Duration::ZERO);
        assert!(two_stage.profile.partition_only_total_wall > Duration::ZERO);
        assert!(two_stage.profile.resident_topk_kernel_event_wall > Duration::ZERO);
        assert_eq!(
            two_stage.profile.persistent_leaf_pushes,
            two_stage.profile.persistent_topk_pops
        );
        assert_eq!(two_stage.profile.sq_wmma_rows, rows);
        assert_eq!(two_stage.profile.sq_wmma_padded_dim, sq.padded_dim);
        assert_eq!(two_stage.profile.sq_wmma_code_bytes, expected_code_bytes);
        assert_eq!(two_stage.profile.subtree_vector_h2d_wall, Duration::ZERO);
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_scheduler_modes_match_baseline_on_device() {
        use crate::algorithm::pipnn::params::PiPNNGpuSubtreePersistentSchedulerMode as Mode;

        let rows = 529usize;
        let dim = 96usize;
        let mut x_row_major = synthetic_leaf_replay_vectors(rows, dim);
        x_row_major[..dim].fill(0.0);
        let duplicate = x_row_major[dim..2 * dim].to_vec();
        x_row_major[2 * dim..3 * dim].copy_from_slice(&duplicate);
        x_row_major[3 * dim..4 * dim].fill(0.0);
        x_row_major[3 * dim] = 1.0;
        x_row_major[4 * dim..5 * dim].fill(0.0);
        x_row_major[4 * dim] = -1.0;
        let global_ids: Vec<u32> = (0..rows as u32).collect();
        let sq = crate::algorithm::pipnn::dco_sq_int8::quantize_sq_int8_matrix(
            &x_row_major,
            rows,
            dim,
            crate::algorithm::pipnn::dco_sq_int8::SQ_INT8_DEFAULT_K_ALIGN,
        )
        .expect("SQ-int8 quantization should succeed");
        let code_sums = vec![0.0_f32; rows];
        let quantized = GpuSubtreeQuantizedInput {
            distance_kind: GpuSubtreeQuantizedDistanceKind::SqInt8,
            global_ids: &global_ids,
            codes: &sq.codes,
            deltas: &sq.scales,
            code_sums: &code_sums,
            norms: &sq.norms,
            dim,
            padded_dim: sq.padded_dim,
            code_layout: GpuSubtreeQuantizedCodeLayout::DenseI8,
            code_row_bytes: sq.padded_dim,
            bits: 8,
        };
        let mut params = PiPNNParams::default();
        params.random_seed = 987;
        params.leaf_knn = 2;
        params.c_min = rows;
        params.c_max = rows;
        params.max_depth = 1;
        params.max_leaders = 16;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.psamp_fraction = 1.0;
        params.gpu_workspace_budget_bytes = 256 * 1024 * 1024;
        params.gpu_subtree_assignment_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        params.gpu_subtree_sq_wmma_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeSqWmmaMode::Build;
        params.gpu_subtree_sq8_leaf_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeSq8LeafMode::RowOwned;
        params.gpu_subtree_persistent_idle_backoff_ns = 350;
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &global_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: rows,
            adaptive_c_max: rows,
            min_recurse_size: rows,
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };
        let backend =
            super::cuda_backend::CudaComputeBackend::new(0, &params).expect("CUDA backend");
        let mut results = Vec::new();
        for mode in [
            Mode::Baseline,
            Mode::LocalCounters,
            Mode::LocalCountersBarrier,
            Mode::AdaptiveIdle,
        ] {
            params.gpu_subtree_persistent_scheduler_mode = mode;
            let result = backend
                .process_quantized_subtree_l2_compact_topk(&request, quantized, &params)
                .unwrap_or_else(|err| panic!("persistent scheduler mode {mode} should run: {err}"));
            assert_eq!(result.profile.persistent_success_count, 1, "mode={mode}");
            assert_eq!(result.profile.persistent_fallback_count, 0, "mode={mode}");
            assert_eq!(result.profile.cpu_fallbacks, 0, "mode={mode}");
            assert_eq!(
                result.profile.persistent_large_ticket_batch_actual, 8,
                "mode={mode}"
            );
            assert_eq!(
                result.profile.persistent_queue_overflow_flags, 0,
                "mode={mode}"
            );
            assert_eq!(result.profile.persistent_watchdog_trips, 0, "mode={mode}");
            if mode == Mode::Baseline {
                assert_eq!(result.profile.persistent_topk_local_counter_flushes, 0);
                assert_eq!(result.profile.persistent_topk_idle_backoff_calls, 0);
            } else {
                assert!(
                    result.profile.persistent_topk_local_counter_flushes > 0,
                    "mode={mode} profile={:?}",
                    result.profile
                );
            }
            if mode == Mode::AdaptiveIdle {
                assert!(
                    result.profile.persistent_topk_idle_backoff_calls > 0,
                    "profile={:?}",
                    result.profile
                );
                assert!(result.profile.persistent_topk_idle_backoff_requested_ns > 0);
            }
            results.push((mode, result));
        }

        let baseline = &results[0].1;
        for (mode, result) in results.iter().skip(1) {
            assert_eq!(
                result.compact_batches.len(),
                baseline.compact_batches.len(),
                "mode={mode}"
            );
            for (actual, expected) in result
                .compact_batches
                .iter()
                .zip(baseline.compact_batches.iter())
            {
                assert_eq!(actual.point_ids, expected.point_ids, "mode={mode}");
                assert_eq!(actual.topk_ids, expected.topk_ids, "mode={mode}");
                for (&actual_dist, &expected_dist) in
                    actual.topk_dists.iter().zip(expected.topk_dists.iter())
                {
                    assert!(
                        (actual_dist - expected_dist).abs() <= 1.0e-6,
                        "mode={mode} actual={actual_dist} expected={expected_dist}"
                    );
                }
            }
        }
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_sq_wmma_two_stage_large_leaf_uses_staged_row_locks() {
        let rows = 640usize;
        let dim = 32usize;
        let x_row_major = synthetic_leaf_replay_vectors(rows, dim);
        let global_ids: Vec<u32> = (0..rows as u32).collect();
        let sq = crate::algorithm::pipnn::dco_sq_int8::quantize_sq_int8_matrix(
            &x_row_major,
            rows,
            dim,
            crate::algorithm::pipnn::dco_sq_int8::SQ_INT8_DEFAULT_K_ALIGN,
        )
        .expect("SQ-int8 quantization should succeed");
        let code_sums = vec![0.0_f32; rows];
        let quantized = GpuSubtreeQuantizedInput {
            distance_kind: GpuSubtreeQuantizedDistanceKind::SqInt8,
            global_ids: &global_ids,
            codes: &sq.codes,
            deltas: &sq.scales,
            code_sums: &code_sums,
            norms: &sq.norms,
            dim,
            padded_dim: sq.padded_dim,
            code_layout: GpuSubtreeQuantizedCodeLayout::DenseI8,
            code_row_bytes: sq.padded_dim,
            bits: 8,
        };
        let mut params = PiPNNParams::default();
        params.random_seed = 456;
        params.leaf_knn = 2;
        params.c_min = rows;
        params.c_max = rows;
        params.max_depth = 1;
        params.max_leaders = 2;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.psamp_fraction = 1.0;
        params.gpu_workspace_budget_bytes = 128 * 1024 * 1024;
        params.gpu_subtree_assignment_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        params.gpu_subtree_execution_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeExecutionMode::TwoStage;
        params.gpu_subtree_sq_wmma_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeSqWmmaMode::Build;
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &global_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: rows,
            adaptive_c_max: rows,
            min_recurse_size: rows,
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };
        let backend =
            super::cuda_backend::CudaComputeBackend::new(0, &params).expect("CUDA backend");

        let result = backend
            .process_quantized_subtree_l2_compact_topk(&request, quantized, &params)
            .unwrap_or_else(|err| panic!("two-stage large-leaf SQ+WMMA subtree should run: {err}"));

        assert_eq!(result.profile.persistent_success_count, 1);
        assert_eq!(result.profile.persistent_leaf_count, 1);
        assert_eq!(result.profile.persistent_leaf_pushes, 25);
        assert_eq!(
            result.profile.persistent_leaf_pushes,
            result.profile.persistent_topk_pops
        );
        assert_eq!(result.profile.leaf_dco.tile_started, 25);
        assert_eq!(result.profile.leaf_dco.tile_done, 25);
        assert!(result.profile.leaf_dco.staged_tiles > 0);
        assert_eq!(
            result.profile.leaf_dco.col_tasks_started,
            result.profile.leaf_dco.col_tasks_done
        );
        assert_eq!(
            result.profile.leaf_dco.finalize_started,
            result.profile.leaf_dco.finalize_done
        );
        assert!(result.profile.leaf_dco.finalize_started > 0);
        assert!(result.profile.resident_topk_kernel_event_wall > Duration::ZERO);
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_staged_leaf_matches_row_owned_at_column_split_boundaries() {
        use crate::algorithm::pipnn::params::PiPNNGpuSubtreeSq8LeafMode;

        for rows in [128usize, 129, 256, 512, 513] {
            let dim = 32usize;
            let x_row_major = synthetic_leaf_replay_vectors(rows, dim);
            let global_ids: Vec<u32> = (0..rows as u32).collect();
            let sq = crate::algorithm::pipnn::dco_sq_int8::quantize_sq_int8_matrix(
                &x_row_major,
                rows,
                dim,
                crate::algorithm::pipnn::dco_sq_int8::SQ_INT8_DEFAULT_K_ALIGN,
            )
            .expect("SQ-int8 quantization should succeed");
            let code_sums = vec![0.0_f32; rows];
            let request = super::GpuSubtreePartitionRequest {
                point_ids: &global_ids,
                root_leader_ids: None,
                depth: 1,
                parent_points: rows,
                adaptive_c_max: rows,
                min_recurse_size: rows,
                memory_budget_bytes: Some(128 * 1024 * 1024),
            };
            let mut base_params = PiPNNParams::default();
            base_params.random_seed = 456;
            base_params.leaf_knn = 2;
            base_params.c_min = rows;
            base_params.c_max = rows;
            base_params.max_depth = 1;
            base_params.max_leaders = 2;
            base_params.fanout_top = 1;
            base_params.fanout_second = 1;
            base_params.psamp_fraction = 1.0;
            base_params.gpu_workspace_budget_bytes = 128 * 1024 * 1024;
            base_params.gpu_subtree_assignment_backend =
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
            base_params.gpu_subtree_leaf_topk_backend =
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
            base_params.gpu_subtree_sq_wmma_mode =
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeSqWmmaMode::Build;
            let backend = super::cuda_backend::CudaComputeBackend::new(0, &base_params)
                .expect("CUDA backend");

            let run = |mode| {
                let mut params = base_params.clone();
                params.gpu_subtree_sq8_leaf_mode = mode;
                let quantized = GpuSubtreeQuantizedInput {
                    distance_kind: GpuSubtreeQuantizedDistanceKind::SqInt8,
                    global_ids: &global_ids,
                    codes: &sq.codes,
                    deltas: &sq.scales,
                    code_sums: &code_sums,
                    norms: &sq.norms,
                    dim,
                    padded_dim: sq.padded_dim,
                    code_layout: GpuSubtreeQuantizedCodeLayout::DenseI8,
                    code_row_bytes: sq.padded_dim,
                    bits: 8,
                };
                backend
                    .process_quantized_subtree_l2_compact_topk(&request, quantized, &params)
                    .unwrap_or_else(|err| {
                        panic!("{mode} SQ8 leaf should run for rows={rows}: {err}")
                    })
            };

            let staged = run(PiPNNGpuSubtreeSq8LeafMode::Staged);
            let row_owned = run(PiPNNGpuSubtreeSq8LeafMode::RowOwned);
            let tile_rows = staged.profile.persistent_leaf_tile_rows.max(1);
            let row_tiles = (rows + tile_rows - 1) / tile_rows;
            let col_tasks = if rows > 128 * 4 {
                (rows + 128 - 1) / 128
            } else {
                1
            };
            assert_eq!(
                staged.profile.persistent_leaf_pushes,
                row_tiles * col_tasks,
                "rows={rows} must publish the expected row-tile/column-range product"
            );
            let mut column_coverage = vec![0u8; rows];
            for col_task in 0..col_tasks {
                let col_base = if col_tasks > 1 { col_task * 128 } else { 0 };
                let col_count = if col_tasks > 1 {
                    (rows - col_base).min(128)
                } else {
                    rows
                };
                for covered in &mut column_coverage[col_base..col_base + col_count] {
                    *covered += 1;
                }
            }
            assert!(
                column_coverage.iter().all(|&count| count == 1),
                "rows={rows} staged column ranges must cover every candidate exactly once"
            );
            assert_eq!(
                staged.compact_batches.len(),
                row_owned.compact_batches.len(),
                "rows={rows}"
            );
            for (actual, expected) in staged
                .compact_batches
                .iter()
                .zip(row_owned.compact_batches.iter())
            {
                assert_eq!(actual.point_ids, expected.point_ids, "rows={rows}");
                assert_eq!(actual.topk_ids, expected.topk_ids, "rows={rows}");
                for (&actual_dist, &expected_dist) in
                    actual.topk_dists.iter().zip(expected.topk_dists.iter())
                {
                    assert!(
                        (actual_dist - expected_dist).abs() <= 1.0e-5,
                        "rows={rows} actual={actual_dist} expected={expected_dist}"
                    );
                }
            }
        }
    }

    #[cfg(feature = "pipnn_cuda")]
    fn run_cuda_persistent_subtree_leaf_quantized_wmma_dco(
        dco_mode: crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoMode,
        label: &str,
        require_exact_match: bool,
    ) {
        let rows = if dco_mode
            == crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoMode::RabitqSplitFilter
        {
            std::env::var("SHEAR_PIPNN_RABITQ_SPLIT_LEAF_TEST_ROWS")
                .ok()
                .and_then(|value| value.parse::<usize>().ok())
                .unwrap_or(128)
        } else {
            128
        };
        let wiki10m_like_shape = rows > 128;
        let dim = 1024usize;
        let mut dataset = InmemDataset::new(rows, 1.0, dim).expect("dataset");
        dataset
            .data
            .copy_from_slice(&synthetic_leaf_replay_vectors(rows, dim));
        let store = InmemDatasetPointStore::new(&dataset, rows);
        let mut params = PiPNNParams::default();
        params.leaf_knn = 2;
        params.c_min = if wiki10m_like_shape { 256 } else { rows };
        params.c_max = if wiki10m_like_shape { 1280 } else { rows };
        params.max_depth = if wiki10m_like_shape { 12 } else { 1 };
        params.max_leaders = if wiki10m_like_shape { 1500 } else { 2 };
        params.fanout_top = if wiki10m_like_shape { 6 } else { 1 };
        params.fanout_second = if wiki10m_like_shape { 3 } else { 1 };
        params.psamp_fraction = if wiki10m_like_shape { 0.05 } else { 1.0 };
        params.gpu_workspace_budget_bytes = if wiki10m_like_shape {
            1024 * 1024 * 1024
        } else {
            128 * 1024 * 1024
        };
        params.gpu_subtree_assignment_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_dco_mode = dco_mode;
        params.gpu_subtree_leaf_dco_rerank_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoRerankMode::Exact;
        params.gpu_subtree_leaf_dco_survivors = 16;
        params.gpu_subtree_leaf_dco_audit = true;
        let sidecar_temp_dir = if dco_mode
            == crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoMode::RabitqSplitFilter
        {
            let dir = std::env::temp_dir().join(format!(
                "shear-rabitq-split-leaf-test-{}-{}",
                std::process::id(),
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .expect("system time")
                    .as_nanos()
            ));
            std::fs::create_dir_all(&dir).expect("create split sidecar temp dir");
            let prefix = dir.join("leaf.rabitq8split");
            crate::algorithm::pipnn::dco_rabitq::create_rabitq_split_sidecar_from_point_store(
                &store,
                &prefix,
                params.gpu_subtree_rabitq_plus_bits,
                params.gpu_subtree_rabitq_plus_rotator,
                params.gpu_subtree_rabitq_plus_seed,
                0,
            )
            .expect("create tiny RabitQ-Library split sidecar");
            params.gpu_subtree_rabitq_plus_sidecar_prefix = Some(prefix);
            Some(dir)
        } else {
            None
        };
        let point_ids: Vec<u32> = (0..rows as u32).collect();
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &point_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: rows,
            adaptive_c_max: if wiki10m_like_shape { 2560 } else { rows },
            min_recurse_size: if wiki10m_like_shape {
                5120
            } else {
                rows.saturating_add(1)
            },
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };
        let backend =
            super::cuda_backend::CudaComputeBackend::new(0, &params).expect("CUDA backend");

        let baseline = if wiki10m_like_shape {
            None
        } else {
            let mut baseline_params = params.clone();
            baseline_params.gpu_subtree_leaf_dco_mode =
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoMode::None;
            baseline_params.gpu_subtree_leaf_dco_survivors = 0;
            baseline_params.gpu_subtree_leaf_dco_audit = false;
            Some(
                backend
                    .process_subtree_l2_compact_topk(&store, &request, &baseline_params)
                    .unwrap_or_else(|err| {
                        panic!("persistent leaf tiled baseline should run: {err}")
                    }),
            )
        };

        for rerank_mode in [
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoRerankMode::Exact,
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoRerankMode::ExactStamp,
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoRerankMode::None,
        ] {
            params.gpu_subtree_leaf_dco_rerank_mode = rerank_mode;
            let result = backend
                .process_subtree_l2_compact_topk(&store, &request, &params)
                .unwrap_or_else(|err| {
                    panic!("persistent leaf {label} DCO {rerank_mode} should run: {err}")
                });

            assert_eq!(
                result.profile.leaf_topk_backend,
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32
            );
            assert_eq!(result.profile.persistent_success_count, 1);
            assert!(result.profile.leaf_dco.leaf_count > 0);
            assert!(result.profile.leaf_dco.prefilter_pairs > 0);
            assert!(result.profile.leaf_dco.pruned_pairs > 0);
            assert_eq!(result.profile.leaf_dco.exact_fallback_rows, 0);
            assert!(result.profile.leaf_dco.false_prune_audit_pairs > 0);
            assert!(result.profile.leaf_dco.metadata_bytes > 0);
            assert!(result.profile.resident_topk_metadata_h2d_bytes > 0);
            match rerank_mode {
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoRerankMode::Exact => {
                    assert!(result.profile.leaf_dco.exact_pairs > 0);
                    assert_eq!(result.profile.leaf_dco.exact_stamp_pairs, 0);
                    assert_eq!(result.profile.leaf_dco.approx_output_pairs, 0);
                }
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoRerankMode::ExactStamp => {
                    assert_eq!(result.profile.leaf_dco.exact_pairs, 0);
                    assert!(result.profile.leaf_dco.exact_stamp_pairs > 0);
                    assert_eq!(result.profile.leaf_dco.approx_output_pairs, 0);
                }
                crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoRerankMode::None => {
                    assert_eq!(result.profile.leaf_dco.exact_pairs, 0);
                    assert_eq!(result.profile.leaf_dco.exact_stamp_pairs, 0);
                    assert!(result.profile.leaf_dco.approx_output_pairs > 0);
                }
            }
            if let Some(baseline) = &baseline {
                assert_eq!(result.compact_batches.len(), baseline.compact_batches.len());
                for (actual, expected) in result
                    .compact_batches
                    .iter()
                    .zip(baseline.compact_batches.iter())
                {
                    assert_eq!(actual.point_ids, expected.point_ids);
                    assert_eq!(actual.rows, expected.rows);
                    assert_eq!(actual.k, expected.k);
                    assert!(actual.topk_ids.iter().all(|&id| id != u32::MAX));
                    if rerank_mode
                        == crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoRerankMode::Exact
                        && require_exact_match
                    {
                        assert_eq!(actual.topk_ids, expected.topk_ids);
                    }
                }
            } else {
                for batch in &result.compact_batches {
                    assert!(batch.topk_ids.iter().all(|&id| id != u32::MAX));
                }
            }
        }
        if let Some(dir) = sidecar_temp_dir {
            let _ = std::fs::remove_dir_all(dir);
        }
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_persistent_subtree_leaf_rabitq_split_rejects_global_ids_outside_sidecar_rows() {
        let sidecar_rows = 128usize;
        let dataset_rows = sidecar_rows * 2;
        let dim = 1024usize;
        let mut dataset = InmemDataset::new(dataset_rows, 1.0, dim).expect("dataset");
        dataset
            .data
            .copy_from_slice(&synthetic_leaf_replay_vectors(dataset_rows, dim));
        let sidecar_store = InmemDatasetPointStore::new(&dataset, sidecar_rows);
        let run_store = InmemDatasetPointStore::new(&dataset, dataset_rows);
        let dir = std::env::temp_dir().join(format!(
            "shear-rabitq-split-bounds-test-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("system time")
                .as_nanos()
        ));
        std::fs::create_dir_all(&dir).expect("create split sidecar bounds temp dir");
        let prefix = dir.join("leaf.rabitq8split");
        crate::algorithm::pipnn::dco_rabitq::create_rabitq_split_sidecar_from_point_store(
            &sidecar_store,
            &prefix,
            crate::algorithm::pipnn::dco_rabitq::RABITQ_DEFAULT_TOTAL_BITS,
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeRabitqPlusRotator::FhtKac,
            42,
            0,
        )
        .expect("create bounded RabitQ-Library split sidecar");

        let mut params = PiPNNParams::default();
        params.leaf_knn = 2;
        params.c_min = sidecar_rows;
        params.c_max = sidecar_rows;
        params.max_depth = 1;
        params.max_leaders = 2;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.psamp_fraction = 1.0;
        params.gpu_workspace_budget_bytes = 128 * 1024 * 1024;
        params.gpu_subtree_assignment_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_dco_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoMode::RabitqSplitFilter;
        params.gpu_subtree_leaf_dco_rerank_mode =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeDcoRerankMode::None;
        params.gpu_subtree_leaf_dco_survivors = 16;
        params.gpu_subtree_leaf_dco_audit = false;
        params.gpu_subtree_rabitq_plus_sidecar_prefix = Some(prefix);
        let point_ids: Vec<u32> = (sidecar_rows as u32..dataset_rows as u32).collect();
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &point_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: sidecar_rows,
            adaptive_c_max: sidecar_rows,
            min_recurse_size: sidecar_rows + 1,
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };
        let backend =
            super::cuda_backend::CudaComputeBackend::new(0, &params).expect("CUDA backend");
        let err = backend
            .process_subtree_l2_compact_topk(&run_store, &request, &params)
            .expect_err("out-of-sidecar global ids should be rejected before CUDA launch");
        let msg = format!("{err:?}");
        assert!(
            msg.contains("global id 255 exceeds split sidecar rows 128"),
            "unexpected error: {msg}"
        );
        let _ = std::fs::remove_dir_all(dir);
    }

