        let mut store_ids = point_ids.clone();
        store_ids.sort_unstable();
        store_ids.dedup();
        let store = SparseCudaSubtreePointStore::from_fbin_rows(base, store_ids)?;
        let mut params = PiPNNParams::default();
        params.leaf_knn = 2;
