    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_gpu_persistent_subtree_wiki10m_scaled_sq8_dp4a_staged_shape_finishes() {
        use crate::algorithm::pipnn::params::{
            PiPNNGpuSubtreePersistentLargeTicketBatch, PiPNNGpuSubtreeSq8AssignmentKernel,
            PiPNNGpuSubtreeSq8LeafExecutor, PiPNNGpuSubtreeSq8LeafMode, PiPNNGpuSubtreeSqWmmaMode,
        };

        let rows = std::env::var("SHEAR_PIPNN_SQ8_DP4A_STAGED_TEST_ROWS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .unwrap_or(10_934);
        let dim = 1024usize;
        let x_row_major = queue_shadow_test_vectors(rows, dim);
        let global_ids: Vec<u32> = (0..rows as u32).collect();
        let sq = crate::algorithm::pipnn::dco_sq_int8::quantize_sq_int8_matrix(
            &x_row_major,
            rows,
            dim,
            crate::algorithm::pipnn::dco_sq_int8::SQ_INT8_DEFAULT_K_ALIGN,
        )
        .expect("SQ-int8 quantization should succeed");
        let code_sums = vec![0.0_f32; rows];
        let quantized = GpuSubtreeQuantizedInput {
            distance_kind: GpuSubtreeQuantizedDistanceKind::SqInt8,
            global_ids: &global_ids,
            codes: &sq.codes,
            deltas: &sq.scales,
            code_sums: &code_sums,
            norms: &sq.norms,
            dim,
            padded_dim: sq.padded_dim,
            code_layout: GpuSubtreeQuantizedCodeLayout::DenseI8,
            code_row_bytes: sq.padded_dim,
            bits: 8,
        };
        let mut params = PiPNNParams::default();
        params.random_seed = 42;
        params.leaf_knn = 2;
        params.c_min = 256;
        params.c_max = 1280;
        params.max_depth = 12;
        params.max_leaders = 1500;
        params.fanout_top = 6;
        params.fanout_second = 3;
        params.psamp_fraction = 0.05;
        params.gpu_workspace_budget_bytes = 16 * 1024 * 1024 * 1024;
        params.gpu_subtree_assignment_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeAssignmentBackend::PersistentWmmaTf32;
        params.gpu_subtree_leaf_topk_backend =
            crate::algorithm::pipnn::params::PiPNNGpuSubtreeLeafTopKBackend::PersistentWmmaTf32;
        params.gpu_subtree_sq_wmma_mode = PiPNNGpuSubtreeSqWmmaMode::Build;
        params.gpu_subtree_sq8_assignment_kernel = PiPNNGpuSubtreeSq8AssignmentKernel::WarpDp4a;
        params.gpu_subtree_sq8_leaf_executor = PiPNNGpuSubtreeSq8LeafExecutor::WarpDp4a;
        params.gpu_subtree_sq8_leaf_mode = PiPNNGpuSubtreeSq8LeafMode::Staged;
        params.gpu_subtree_persistent_large_ticket_batch =
            PiPNNGpuSubtreePersistentLargeTicketBatch::One;
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &global_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: 10_000_000,
            adaptive_c_max: 1280,
            min_recurse_size: 5120,
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };
        let backend =
            super::cuda_backend::CudaComputeBackend::new(0, &params).expect("CUDA backend");

        let partition_only = std::env::var_os("SHEAR_PIPNN_SQ8_DP4A_PARTITION_ONLY").is_some();
        let result = if partition_only {
            backend.debug_run_quantized_partition_only_for_test(&request, quantized, &params)
        } else {
            backend.process_quantized_subtree_l2_compact_topk(&request, quantized, &params)
        }
        .expect("scaled SQ8 DP4A staged subtree should finish");

        assert_eq!(result.profile.persistent_success_count, 1);
        assert_eq!(result.profile.persistent_queue_overflow_flags, 0);
        assert!(result.profile.persistent_large_sq8_dp4a_tiles > 0);
        assert!(
            result.profile.persistent_large_sq8_dp4a_tiles
                <= result.profile.persistent_large_physical_tiles
        );
        if !partition_only {
            assert!(result.profile.persistent_leaf_sq8_dp4a_tiles > 0);
            assert_eq!(
                result.profile.leaf_dco.col_tasks_started,
                result.profile.leaf_dco.col_tasks_done
            );
            assert_eq!(
                result.profile.leaf_dco.finalize_started,
                result.profile.leaf_dco.finalize_done
            );
        }
    }

