    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_gpu_persistent_subtree_128k_produces_leaves_without_active_budget_abort() {
        let rows = 131_072;
        let dim = 8;
        let mut dataset = InmemDataset::new(rows, 1.0, dim).expect("dataset");
        dataset
            .data
            .copy_from_slice(&queue_shadow_test_vectors(rows, dim));
        let store = InmemDatasetPointStore::new(&dataset, rows);
        let mut params = PiPNNParams::default();
        params.leaf_knn = 2;
        params.c_min = 128;
        params.c_max = 512;
        params.max_depth = 12;
        params.max_leaders = 64;
        params.fanout_top = 1;
        params.fanout_second = 2;
        params.psamp_fraction = 0.2;
        params.gpu_workspace_budget_bytes = 4 * 1024 * 1024 * 1024;
        let point_ids: Vec<u32> = (0..rows as u32).collect();
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &point_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: rows,
            adaptive_c_max: 512,
            min_recurse_size: 128,
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };
        let backend =
            super::cuda_backend::CudaComputeBackend::new(0, &params).expect("CUDA backend");

        let result = backend
            .process_subtree_l2_compact_topk(&store, &request, &params)
            .expect("128k persistent subtree should produce leaves instead of tripping active-work budget");

        assert_eq!(result.profile.persistent_attempt_count, 1);
        assert_eq!(result.profile.persistent_success_count, 1);
        assert_eq!(result.profile.persistent_queue_overflow_flags, 0);
        assert_eq!(result.profile.persistent_active_work_trips, 0);
        assert!(result.profile.persistent_active_work_ticks > 0);
        assert!(result.profile.persistent_large_node_splits > 0);
        assert!(result.profile.persistent_large_node_max_rows >= rows);
        assert!(result.profile.persistent_leaf_pushes > 0);
        assert_eq!(
            result.profile.persistent_leaf_pushes,
            result.profile.persistent_topk_pops
        );
        assert!(result.profile.persistent_leaf_size_max <= result.profile.persistent_leaf_max);
        let mut covered_rows = vec![0_u32; rows];
        for point_id in result
            .compact_batches
            .iter()
            .flat_map(|batch| batch.point_ids.iter())
        {
            covered_rows[*point_id as usize] += 1;
        }
        let missing_rows = covered_rows.iter().filter(|&&count| count == 0).count();
        assert_eq!(missing_rows, 0, "profile={:?}", result.profile);
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_subtree_compact_topk_returns_global_ids_with_leaf_membership() {
        let store = CountingCudaSubtreePointStore::new(96, 5);
        let mut params = PiPNNParams::default();
        params.leaf_knn = 2;
        params.c_min = 8;
        params.c_max = 24;
        params.max_depth = 4;
        params.max_leaders = 4;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.psamp_fraction = 1.0;
        let backend = super::cuda_backend::CudaComputeBackend::new(0, &params)
            .expect("CUDA backend should initialize on CUDA-capable host");
        let point_ids: Vec<u32> = (0..96).collect();
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &point_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: point_ids.len(),
            adaptive_c_max: params.adaptive_c_max(point_ids.len()),
            min_recurse_size: params.adaptive_c_max(point_ids.len()).saturating_mul(2),
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };

        let result = backend
            .process_subtree_l2_compact_topk(&store, &request, &params)
            .expect("CUDA compact subtree top-k");

        assert_eq!(
            store.batch_reads(),
            1,
            "CUDA compact subtree should materialize vectors once before partition and top-k"
        );
        assert!(result.leaf_count > 0);
        assert!(result.assignment_passes > 0);
        assert_eq!(result.profile.persistent_attempt_count, 1);
        assert_eq!(result.profile.persistent_success_count, 1);
        assert_eq!(result.profile.persistent_fallback_count, 0);
        assert_eq!(result.profile.persistent_queue_overflow_flags, 0);
        assert!(
            result.profile.persistent_kernel_event_wall > Duration::ZERO,
            "CUDA compact subtree should report persistent kernel time"
        );
        assert_eq!(result.profile.assignment_kernel_wall, Duration::ZERO);
        assert_eq!(result.profile.assignment_d2h_wall, Duration::ZERO);
        assert_eq!(
            result.profile.assignment_active_ids_h2d_wall,
            Duration::ZERO
        );
        assert_eq!(
            result.profile.assignment_leader_ids_h2d_wall,
            Duration::ZERO
        );
        assert_eq!(result.profile.assignment_kernel_event_wall, Duration::ZERO);
        assert_eq!(result.profile.assignment_d2h_submit_wall, Duration::ZERO);
        assert_eq!(result.profile.assignment_sync_wait_wall, Duration::ZERO);
        assert_eq!(
            result
                .compact_batches
                .iter()
                .map(|batch| batch.rows)
                .sum::<usize>(),
            96
        );
        for batch in &result.compact_batches {
            assert_eq!(batch.point_ids.len(), batch.rows);
            assert_eq!(batch.topk_ids.len(), batch.rows * batch.k);
            assert_eq!(batch.topk_dists.len(), batch.rows * batch.k);
            for row in 0..batch.rows {
                let point = batch.point_ids[row];
                for rank in 0..batch.k {
                    let neighbor = batch.topk_ids[row * batch.k + rank];
                    if neighbor == u32::MAX {
                        continue;
                    }
                    assert_ne!(neighbor, point);
                    assert!(
                        batch.point_ids.contains(&neighbor),
                        "neighbor {neighbor} must stay inside the source compact leaf"
                    );
                }
            }
        }
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_subtree_compact_topk_uploads_resident_metadata_once() {
        let store = CountingCudaSubtreePointStore::new(48, 3);
        let mut params = PiPNNParams::default();
        params.leaf_knn = 2;
        params.c_min = 4;
        params.c_max = 12;
        params.max_depth = 4;
        params.max_leaders = 4;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.psamp_fraction = 1.0;
        params.gpu_workspace_budget_bytes = 64 * 1024 * 1024;
        let backend = super::cuda_backend::CudaComputeBackend::new(0, &params)
            .expect("CUDA backend should initialize on CUDA-capable host");
        let point_ids: Vec<u32> = (0..48).rev().collect();
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &point_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: point_ids.len(),
            adaptive_c_max: params.adaptive_c_max(point_ids.len()),
            min_recurse_size: params.adaptive_c_max(point_ids.len()).saturating_mul(2),
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };

        let result = backend
            .process_subtree_l2_compact_topk(&store, &request, &params)
            .expect("CUDA compact subtree top-k");

        assert_eq!(store.batch_reads(), 1);
        assert!(result.profile.subtree_vector_h2d_wall > Duration::ZERO);
        assert!(result.profile.subtree_global_ids_h2d_wall > Duration::ZERO);
        assert!(result.profile.subtree_norms_h2d_wall > Duration::ZERO);
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_subtree_compact_topk_does_not_materialize_compact_x() {
        let store = CountingCudaSubtreePointStore::new(64, 8);
        let mut params = PiPNNParams::default();
        params.leaf_knn = 3;
        params.c_min = 4;
        params.c_max = 16;
        params.max_depth = 4;
        params.max_leaders = 4;
        params.fanout_top = 1;
        params.fanout_second = 1;
        params.psamp_fraction = 1.0;
        params.gpu_workspace_budget_bytes = 64 * 1024 * 1024;
        let backend = super::cuda_backend::CudaComputeBackend::new(0, &params)
            .expect("CUDA backend should initialize on CUDA-capable host");
        let point_ids: Vec<u32> = (0..64).rev().collect();
        let request = super::GpuSubtreePartitionRequest {
            point_ids: &point_ids,
            root_leader_ids: None,
            depth: 1,
            parent_points: point_ids.len(),
            adaptive_c_max: params.adaptive_c_max(point_ids.len()),
            min_recurse_size: params.adaptive_c_max(point_ids.len()).saturating_mul(2),
            memory_budget_bytes: Some(params.effective_oom_memory_budget_bytes()),
        };

        let result = backend
            .process_subtree_l2_compact_topk(&store, &request, &params)
            .expect("CUDA compact subtree top-k");

        let legacy_vector_reupload_bytes = result
            .compact_batches
            .iter()
            .map(|batch| {
                batch
                    .rows
                    .saturating_mul(store.dim())
                    .saturating_mul(std::mem::size_of::<f32>())
            })
            .sum::<usize>();
        assert_eq!(
            store.batch_reads(),
            1,
            "resident subtree top-k must reuse the one resident vector upload"
        );
        assert!(
            result.profile.resident_topk_metadata_h2d_bytes < legacy_vector_reupload_bytes,
            "resident metadata upload {} should be smaller than legacy compact_x upload {}",
            result.profile.resident_topk_metadata_h2d_bytes,
            legacy_vector_reupload_bytes
        );
        assert_eq!(
            result.profile.h2d_bytes,
            result.profile.resident_h2d_bytes + result.profile.resident_topk_metadata_h2d_bytes
        );
    }

    #[test]
    fn compact_topk_workspace_plan_requires_leaf_vectors_before_gpu_execution() {
        let rows = 256;
        let dim = 128;
        let k = 4;
        let fixed_input_bytes = rows * dim * std::mem::size_of::<f32>()
            + rows * std::mem::size_of::<u32>()
            + rows * std::mem::size_of::<f32>()
            + 2 * std::mem::size_of::<u64>();
        let budget = fixed_input_bytes - 1;

        assert!(plan_compact_topk_l2_workspace(rows, dim, k, Some(budget)).is_none());
    }

    #[cfg(feature = "pipnn_cuda")]
    #[test]
    fn cuda_compact_topk_matches_cpu_shadow_on_tiny_leaf() {
        let mut dataset = InmemDataset::new(4, 1.0, 2).expect("dataset");
        dataset
            .data
            .copy_from_slice(&[0.0, 0.0, 1.0, 0.0, -1.0, 0.0, 0.0, 2.0]);
        let store = InmemDatasetPointStore::new(&dataset, 4);
        let leaf = vec![2, 0, 3, 1];
        let mut params = PiPNNParams::default();
        params.leaf_knn = 2;
        params.gpu_workspace_budget_bytes = 64 * 1024 * 1024;

        let (expected, _) =
            compute_leaf_topk_l2_cpu_shadow(&store, &leaf, &params).expect("cpu shadow top-k");
        let backend = super::cuda_backend::build_cuda_backend(0, &params).expect("CUDA backend");
        let (actual, profile) = backend
            .compute_leaf_topk_l2(&store, &leaf, &params, 1024)
            .expect("CUDA compact top-k");

        assert_eq!(actual.point_ids, expected.point_ids);
        assert_eq!(actual.rows, expected.rows);
        assert_eq!(actual.k, expected.k);
        assert_eq!(actual.topk_ids, expected.topk_ids);
        assert_eq!(actual.topk_dists, expected.topk_dists);
        assert_eq!(profile.gpu_cpu_fallbacks, 0);
        assert_eq!(profile.gpu_workspace_pressure_events, 0);
        assert!(profile.gpu_h2d_bytes > 0);
        assert_eq!(profile.gpu_d2h_bytes, expected.estimated_dtoh_bytes);
    }

